window.MT_DATA['id'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Indonésie, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Premiers jours à Jakarta","phrases":[{"fr":"Je travaille à Jakarta.","tgt":"Saya bekerja di Jakarta.","lit":"je · travailler · à · Jakarta"},{"fr":"Nous habitons à Jakarta maintenant.","tgt":"Kami tinggal di Jakarta sekarang.","lit":"nous · habiter · à · Jakarta · maintenant"},{"fr":"Mon mari travaille ici, lui aussi.","tgt":"Suami saya juga bekerja di sini.","lit":"mari · je · aussi · travailler · à · ici"},{"fr":"Je mange du nasi goreng chaque matin.","tgt":"Saya makan nasi goreng setiap pagi.","lit":"je · manger · riz · frit · chaque · matin"},{"fr":"Hier, j'ai mangé au warung.","tgt":"Kemarin saya makan di warung.","lit":"hier · je · manger · à · warung"},{"fr":"Demain, nous mangeons au warung, nous aussi.","tgt":"Besok kami juga makan di warung.","lit":"demain · nous · aussi · manger · à · warung"},{"fr":"Elle boit du thé sucré.","tgt":"Dia minum teh manis.","lit":"elle · boire · thé · sucré"},{"fr":"Ils boivent du café tous les matins.","tgt":"Mereka minum kopi setiap pagi.","lit":"ils · boire · café · chaque · matin"},{"fr":"J'ai déjà bu un café.","tgt":"Saya sudah minum kopi.","lit":"je · [accompli] · boire · café"},{"fr":"Je vais au bureau en ojek.","tgt":"Saya pergi ke kantor naik ojek.","lit":"je · aller · vers · bureau · monter · ojek"}],"tip":{"title":"Pas de conjugaison : le verbe ne change jamais","example":"Hier, j'ai mangé au warung. — Kemarin saya <b>makan</b> di warung.","body":"Voici la meilleure nouvelle de votre apprentissage : en indonésien, le verbe ne se conjugue jamais. « Makan », qui veut dire manger, reste « makan » avec tout le monde : « saya makan », je mange, « dia makan », il ou elle mange, « mereka makan », ils mangent. Le temps ne change pas non plus le verbe. Pour parler du passé, on ajoute simplement un mot comme « kemarin », hier, ou « sudah », déjà. Décomposons : « Kemarin saya makan di warung », c'est mot à mot hier, je, manger, au warung. Et pour le futur, on dit « besok saya makan », demain je mange. Vous n'avez donc aucune terminaison à retenir, seulement le bon petit mot de temps au début de la phrase. Astuce : pensez à un enfant qui parle avec des verbes à l'infinitif, c'est exactement la logique indonésienne, et c'est parfaitement correct.","lit":"hier · je · manger · à · warung","say":{"Makan":"Makan","makan":"makan","saya makan":"saya makan","dia makan":"dia makan","mereka makan":"mereka makan","kemarin":"kemarin","sudah":"sudah","Kemarin saya makan di warung":"Kemarin saya makan di warung","besok saya makan":"besok saya makan"}}},{"title":"Bonjour aux voisins","phrases":[{"fr":"Bonjour, Madame !","tgt":"Selamat pagi, Bu!","lit":"bon · matin · Madame"},{"fr":"Bonjour, Monsieur Budi !","tgt":"Selamat siang, Pak Budi!","lit":"bon · midi · Monsieur · Budi"},{"fr":"Bonsoir à tous !","tgt":"Selamat malam, semuanya!","lit":"bon · soir · tout le monde"},{"fr":"Comment allez-vous ?","tgt":"Apa kabar?","lit":"quoi · nouvelle"},{"fr":"Je vais bien, merci.","tgt":"Kabar baik, terima kasih.","lit":"nouvelle · bonne · merci"},{"fr":"Bonne nuit, à demain.","tgt":"Selamat tidur, sampai besok.","lit":"bon · dormir · jusqu'à · demain"},{"fr":"Bon après-midi, Madame Sari.","tgt":"Selamat sore, Bu Sari.","lit":"bon · après-midi · Madame · Sari"},{"fr":"Bon travail !","tgt":"Selamat bekerja!","lit":"bon · travailler"},{"fr":"Au revoir, Madame, je m'en vais.","tgt":"Selamat tinggal, Bu.","lit":"bon · rester · Madame"},{"fr":"Bonne route, Monsieur Budi !","tgt":"Selamat jalan, Pak Budi!","lit":"bon · route · Monsieur · Budi"}],"tip":{"title":"Saluer : « selamat pagi », « selamat siang », « selamat malam »","example":"Bonjour, Madame ! — <b>Selamat pagi</b>, Bu!","body":"En indonésien, on ne dit pas un seul bonjour pour toute la journée : on salue selon l'heure. Tout commence par « selamat », qui veut dire à peu près heureux ou bon, suivi du moment de la journée. Le matin, jusque vers onze heures, on dit « selamat pagi », bon matin. En milieu de journée, c'est « selamat siang », bon midi, puis l'après-midi « selamat sore ». Le soir venu, on passe à « selamat malam », bon soir. Décomposons : « Selamat pagi, Bu », c'est bon, matin, Madame. On ajoute presque toujours « Bu » pour une femme et « Pak » pour un homme, c'est la politesse de base. La même recette sert ailleurs : « selamat jalan », bonne route, ou « selamat tidur », bonne nuit. Astuce : retenez « selamat » comme une clé, puis ajoutez simplement ce que vous souhaitez à l'autre.","lit":"bon · matin · Madame","say":{"selamat pagi":"selamat pagi","selamat siang":"selamat siang","selamat malam":"selamat malam","selamat":"selamat","selamat sore":"selamat sore","Selamat pagi, Bu":"Selamat pagi, Bu","Bu":"Bu","Pak":"Pak","selamat jalan":"selamat jalan","selamat tidur":"selamat tidur"}}},{"title":"Le café du matin","phrases":[{"fr":"Je commande un café au lait.","tgt":"Saya pesan kopi susu.","lit":"je · commander · café · lait"},{"fr":"Le café sans sucre, s'il vous plaît.","tgt":"Kopinya tanpa gula, ya.","lit":"café-[le] · sans · sucre · [hein]"},{"fr":"Le café est vraiment bon ici.","tgt":"Kopi di sini enak sekali.","lit":"café · à · ici · bon · très"},{"fr":"J'aime le café noir.","tgt":"Saya suka kopi hitam.","lit":"je · aimer · café · noir"},{"fr":"Goûtez ce café, Madame.","tgt":"Coba kopi ini, Bu.","lit":"essayer · café · ce · Madame"},{"fr":"Je cherche un café près d'ici.","tgt":"Saya cari kafe dekat sini.","lit":"je · chercher · café · près · ici"},{"fr":"Attention, le café est brûlant !","tgt":"Hati-hati, kopinya panas!","lit":"attention · café-[le] · chaud"},{"fr":"Ma tasse est un peu petite.","tgt":"Cangkir saya agak kecil.","lit":"tasse · je · un peu · petit"},{"fr":"Je goûte d'abord, d'accord ?","tgt":"Saya cicip dulu, ya.","lit":"je · goûter · d'abord · [hein]"},{"fr":"Chaque matin, j'ai besoin d'un café.","tgt":"Setiap pagi saya perlu kopi.","lit":"chaque · matin · je · avoir besoin · café"}],"tip":{"title":"La prononciation : on dit tout, et le « c » se dit « tch »","example":"Je cherche un café près d'ici. — Saya <b>cari</b> kafe dekat sini.","body":"Bonne nouvelle : l'indonésien se prononce presque toujours comme il s'écrit, et on prononce toutes les lettres. Le « u » se dit « ou », comme dans « susu », le lait, que l'on dit « soussou ». La lettre « c » se dit toujours « tch » : « cari », chercher, se dit « tchari », et « kecil », petit, se dit « ketchil ». Le « j » se dit « dj », et le « r » est roulé, comme dans le sud de la France. Attention aussi aux voyelles nasales du français, qui n'existent pas ici : « makan » se dit « ma-kann », en faisant bien entendre le « n ». Décomposons « Saya cari kafe dekat sini » : « sa-ya, tcha-ri, ka-fé, de-kat, si-ni », chaque syllabe avec la même force. Astuce : pensez à « cangkir », la tasse, et dites « tchangkir » en souriant, vous aurez le bon réflexe pour toujours.","lit":"je · chercher · café · près · ici","say":{"susu":"susu","cari":"cari","kecil":"kecil","makan":"makan","Saya cari kafe dekat sini":"Saya cari kafe dekat sini","cangkir":"cangkir","sa-ya, tcha-ri, ka-fé, de-kat, si-ni":"saya, cari, kafe, dekat, sini","u":"u"}}},{"title":"Se présenter au bureau","phrases":[{"fr":"Moi, c'est Julien.","tgt":"Nama saya Julien.","lit":"nom · je · Julien"},{"fr":"Comment vous appelez-vous ?","tgt":"Siapa nama Anda?","lit":"qui · nom · vous"},{"fr":"Je m'appelle Dewi, et vous ?","tgt":"Nama saya Dewi, dan Anda?","lit":"nom · je · Dewi · et · vous"},{"fr":"Enchanté de faire votre connaissance.","tgt":"Senang berkenalan dengan Anda.","lit":"content · faire connaissance · avec · vous"},{"fr":"Je suis le nouvel employé.","tgt":"Saya karyawan baru.","lit":"je · employé · nouveau"},{"fr":"Vous travaillez ici depuis longtemps ?","tgt":"Anda sudah lama bekerja di sini?","lit":"vous · [accompli] · longtemps · travailler · à · ici"},{"fr":"Je travaille avec Monsieur Hadi.","tgt":"Saya bekerja dengan Pak Hadi.","lit":"je · travailler · avec · Monsieur · Hadi"},{"fr":"Voici ma carte de visite.","tgt":"Ini kartu nama saya.","lit":"ceci · carte · nom · je"},{"fr":"Appelez-moi simplement Julien.","tgt":"Panggil saya Julien saja.","lit":"appeler · je · Julien · seulement"},{"fr":"Vous parlez un peu français ?","tgt":"Anda bisa sedikit bahasa Prancis?","lit":"vous · pouvoir · un peu · langue · France"}],"tip":{"title":"« Saya », « Anda » et « nama saya » : se présenter poliment","example":"Je m'appelle Dewi, et vous ? — <b>Nama saya</b> Dewi, dan <b>Anda</b>?","body":"Pour parler de vous, retenez un seul mot : « saya », qui veut dire je, moi, et aussi me. C'est le mot poli de tous les jours, au bureau comme au marché. Pour s'adresser à quelqu'un poliment, on dit « Anda », qui veut dire vous. Pour se présenter, on ne dit pas je m'appelle, mais « nama saya », mot à mot nom, moi, c'est-à-dire mon nom. Décomposons : « Nama saya Dewi », c'est nom, moi, Dewi. Pour demander le nom de l'autre, on dit « Siapa nama Anda ? », mot à mot qui, nom, vous. Dans la conversation, les Indonésiens préfèrent souvent dire « Bapak » à un homme et « Ibu » à une femme, plutôt que « Anda ». Astuce : souriez en disant « nama saya », puis votre prénom, c'est la phrase qui ouvre toutes les portes à Jakarta.","lit":"nom · je · Dewi · et · vous","say":{"Saya":"Saya","Anda":"Anda","nama saya":"nama saya","saya":"saya","Nama saya Dewi":"Nama saya Dewi","Siapa nama Anda ?":"Siapa nama Anda?","Bapak":"Bapak","Ibu":"Ibu"}}},{"title":"Qui sont les voisins ?","phrases":[{"fr":"Moi, je suis français.","tgt":"Saya orang Prancis.","lit":"je · personne · France"},{"fr":"Ma voisine est très gentille.","tgt":"Tetangga saya baik sekali.","lit":"voisin · je · gentil · très"},{"fr":"Monsieur Budi est professeur.","tgt":"Pak Budi seorang guru.","lit":"Monsieur · Budi · un-[classificateur] · professeur"},{"fr":"Leur maison est grande.","tgt":"Rumah mereka besar.","lit":"maison · ils · grand"},{"fr":"Leur enfant est encore petit.","tgt":"Anaknya masih kecil.","lit":"enfant-[son] · encore · petit"},{"fr":"Je suis fatigué aujourd'hui.","tgt":"Saya capek hari ini.","lit":"je · fatigué · jour · ce"},{"fr":"Ce quartier est calme.","tgt":"Daerah ini tenang.","lit":"quartier · ce · calme"},{"fr":"Madame Sari est infirmière à l'hôpital.","tgt":"Bu Sari perawat di rumah sakit.","lit":"Madame · Sari · infirmière · à · maison · malade"},{"fr":"Nous sommes nouveaux dans le quartier.","tgt":"Kami orang baru di sini.","lit":"nous · personne · nouveau · à · ici"},{"fr":"Vous êtes vraiment aimable.","tgt":"Anda baik sekali.","lit":"vous · gentil · très"}],"tip":{"title":"Pas de verbe être : « Saya orang Prancis »","example":"Moi, je suis français. — Saya <b>orang Prancis</b>.","body":"En indonésien, le verbe être disparaît tout simplement. Pour dire je suis fatigué, on dit « saya capek », mot à mot je, fatigué, et c'est tout. Pour dire la maison est grande, on dit « rumah besar », maison, grand. Pour la nationalité, on utilise le mot « orang », qui veut dire personne : « Saya orang Prancis », c'est je, personne, France, donc je suis français. De même, « orang Indonesia » veut dire un Indonésien. Pour un métier, on colle simplement le nom : « Bu Sari perawat », Madame Sari, infirmière. Vous entendrez aussi parfois le petit mot « adalah » dans les discours, mais à l'oral on s'en passe presque toujours. Astuce : enlevez le verbe être de votre phrase française, mettez les mots bout à bout, et vous avez déjà une phrase indonésienne correcte.","lit":"je · personne · France","say":{"Saya orang Prancis":"Saya orang Prancis","saya capek":"saya capek","rumah besar":"rumah besar","orang":"orang","orang Indonesia":"orang Indonesia","Bu Sari perawat":"Bu Sari perawat","adalah":"adalah"}}},{"title":"Au warung du coin","phrases":[{"fr":"Moi, je ne mange pas de viande.","tgt":"Saya tidak makan daging.","lit":"je · pas · manger · viande"},{"fr":"Ce n'est pas épicé, n'est-ce pas ?","tgt":"Ini tidak pedas, kan?","lit":"ceci · pas · épicé · n'est-ce pas"},{"fr":"Le thé n'est pas sucré.","tgt":"Tehnya tidak manis.","lit":"thé-[le] · pas · sucré"},{"fr":"Ici, ce n'est pas cher.","tgt":"Di sini tidak mahal.","lit":"à · ici · pas · cher"},{"fr":"Je n'aime pas le piment.","tgt":"Saya tidak suka cabai.","lit":"je · pas · aimer · piment"},{"fr":"Le warung n'est pas loin.","tgt":"Warungnya tidak jauh.","lit":"warung-[le] · pas · loin"},{"fr":"Pardon, je ne comprends pas.","tgt":"Maaf, saya tidak mengerti.","lit":"pardon · je · pas · comprendre"},{"fr":"Aujourd'hui, je n'ai pas faim.","tgt":"Hari ini saya tidak lapar.","lit":"jour · ce · je · pas · affamé"},{"fr":"La soupe n'est pas chaude.","tgt":"Supnya tidak panas.","lit":"soupe-[la] · pas · chaud"},{"fr":"Ce n'est pas grave du tout.","tgt":"Tidak apa-apa.","lit":"pas · quoi-quoi"}],"tip":{"title":"« Tidak » : la négation devant un verbe ou un adjectif","example":"Je n'aime pas le piment. — Saya <b>tidak</b> suka cabai.","body":"Pour dire non à une action ou à une qualité, on utilise « tidak », que l'on place juste devant le verbe ou l'adjectif. En français, la négation entoure le verbe avec ne et pas ; en indonésien, un seul mot suffit, toujours au même endroit. Décomposons : « Saya tidak suka cabai », c'est je, pas, aimer, piment. Avec un adjectif, c'est pareil : « tidak pedas », pas épicé, ou « tidak mahal », pas cher. Dans la rue, vous entendrez souvent la forme courte « nggak » ou « gak », qui veut dire la même chose entre amis. Et retenez la formule « tidak apa-apa », mot à mot pas quoi quoi, qui veut dire ce n'est pas grave. Astuce : imaginez « tidak » comme un petit panneau stop posé juste avant le mot que vous voulez annuler.","lit":"je · pas · aimer · piment","say":{"Tidak":"Tidak","tidak":"tidak","Saya tidak suka cabai":"Saya tidak suka cabai","tidak pedas":"tidak pedas","tidak mahal":"tidak mahal","nggak":"nggak","gak":"gak","tidak apa-apa":"tidak apa-apa"}}},{"title":"Ce n'est pas mon ojek","phrases":[{"fr":"Ce n'est pas mon ojek.","tgt":"Itu bukan ojek saya.","lit":"cela · pas · ojek · je"},{"fr":"Je ne suis pas touriste, j'habite ici.","tgt":"Saya bukan turis, saya tinggal di sini.","lit":"je · pas · touriste · je · habiter · à · ici"},{"fr":"Ce n'est pas du café, c'est du thé.","tgt":"Ini bukan kopi, ini teh.","lit":"ceci · pas · café · ceci · thé"},{"fr":"Monsieur Hadi n'est pas mon chef.","tgt":"Pak Hadi bukan atasan saya.","lit":"Monsieur · Hadi · pas · supérieur · je"},{"fr":"Ce n'est pas mon bureau.","tgt":"Ini bukan kantor saya.","lit":"ceci · pas · bureau · je"},{"fr":"Non, ce n'est pas celui-là.","tgt":"Bukan, bukan itu.","lit":"pas · pas · cela"},{"fr":"Elle n'est pas indonésienne.","tgt":"Dia bukan orang Indonesia.","lit":"elle · pas · personne · Indonésie"},{"fr":"C'est votre casque ? Non, pas le mien.","tgt":"Ini helm Anda? Bukan, bukan punya saya.","lit":"ceci · casque · vous · pas · pas · appartenir · je"},{"fr":"Ce n'est pas une voiture, c'est une moto.","tgt":"Itu bukan mobil, itu motor.","lit":"cela · pas · voiture · cela · moto"},{"fr":"Ce n'est pas un gros problème.","tgt":"Itu bukan masalah besar.","lit":"cela · pas · problème · grand"}],"tip":{"title":"« Bukan » : la négation devant un nom","example":"Ce n'est pas du café, c'est du thé. — Ini <b>bukan</b> kopi, ini teh.","body":"L'indonésien a deux mots pour dire pas, et le choix dépend du mot qui suit. Devant un verbe ou un adjectif, on dit « tidak » ; devant un nom, on dit « bukan ». Ainsi, « Saya bukan turis », c'est je, pas, touriste, donc je ne suis pas touriste. Décomposons : « Ini bukan kopi, ini teh », c'est ceci, pas, café, ceci, thé. Comparez avec « kopinya tidak panas », le café n'est pas chaud, où l'on nie l'adjectif chaud. « Bukan » sert aussi à corriger quelqu'un : si l'on vous demande « Ini helm Anda ? », c'est votre casque, vous répondez simplement « Bukan », non, pas ça. Astuce : « bukan » commence par un « b » comme dans « barang », une chose ; pensez-y quand vous niez une chose, une personne ou un objet.","lit":"ceci · pas · café · ceci · thé","say":{"Bukan":"Bukan","tidak":"tidak","bukan":"bukan","Saya bukan turis":"Saya bukan turis","Ini bukan kopi, ini teh":"Ini bukan kopi, ini teh","kopinya tidak panas":"kopinya tidak panas","Ini helm Anda ?":"Ini helm Anda?","barang":"barang"}}},{"title":"Des questions au marché","phrases":[{"fr":"Est-ce qu'il y a des mangues ?","tgt":"Apakah ada mangga?","lit":"[question] · il y a · mangue"},{"fr":"Les bananes sont fraîches ?","tgt":"Pisangnya segar?","lit":"banane-[la] · frais"},{"fr":"Est-ce que c'est sucré ?","tgt":"Apakah ini manis?","lit":"[question] · ceci · sucré"},{"fr":"Les tomates sont chères aujourd'hui ?","tgt":"Tomatnya mahal hari ini?","lit":"tomate-[la] · cher · jour · ce"},{"fr":"Est-ce que vous ouvrez le dimanche ?","tgt":"Apakah Anda buka hari Minggu?","lit":"[question] · vous · ouvrir · jour · dimanche"},{"fr":"Je peux goûter ?","tgt":"Boleh saya coba?","lit":"permis · je · essayer"},{"fr":"Vous êtes d'ici, Monsieur ?","tgt":"Bapak orang sini?","lit":"Monsieur · personne · ici"},{"fr":"Est-ce que ce marché ferme l'après-midi ?","tgt":"Apakah pasar ini tutup sore?","lit":"[question] · marché · ce · fermer · après-midi"},{"fr":"Oui, c'est très frais.","tgt":"Ya, segar sekali.","lit":"oui · frais · très"},{"fr":"Ce sont des avocats, là ?","tgt":"Itu alpukat?","lit":"cela · avocat"}],"tip":{"title":"« Apakah » et l'intonation : poser une question","example":"Est-ce que c'est sucré ? — <b>Apakah</b> ini manis?","body":"Pour poser une question fermée, celle dont la réponse est oui ou non, vous avez deux possibilités très simples. La première, c'est de mettre « apakah » au début de la phrase, exactement comme notre est-ce que. Décomposons : « Apakah ini manis ? », c'est est-ce que, ceci, sucré. La seconde, la plus courante à l'oral, consiste à garder la phrase normale et à faire monter la voix à la fin : « Pisangnya segar ? », les bananes sont fraîches. On ne change jamais l'ordre des mots, contrairement au français soutenu. Pour répondre, on dit « ya », oui, ou « tidak », non, ou on répète le mot clé, comme « segar », frais. Le mot « apakah » est un peu plus poli et plus clair, parfait au début. Astuce : au marché, faites simplement monter la voix sur le dernier mot, tout le monde vous comprendra.","lit":"[question] · ceci · sucré","say":{"Apakah":"Apakah","apakah":"apakah","Apakah ini manis ?":"Apakah ini manis?","Pisangnya segar ?":"Pisangnya segar?","ya":"ya","tidak":"tidak","segar":"segar"}}},{"title":"Ma maison, mon quartier","phrases":[{"fr":"Voici ma maison.","tgt":"Ini rumah saya.","lit":"ceci · maison · je"},{"fr":"Ma maison est petite mais jolie.","tgt":"Rumah saya kecil tapi bagus.","lit":"maison · je · petit · mais · joli"},{"fr":"Votre maison est dans quelle rue ?","tgt":"Rumah Anda di jalan apa?","lit":"maison · vous · à · rue · quoi"},{"fr":"Ma femme est au marché.","tgt":"Istri saya di pasar.","lit":"épouse · je · à · marché"},{"fr":"Notre voisin est très sympathique.","tgt":"Tetangga kami ramah sekali.","lit":"voisin · nous · aimable · très"},{"fr":"La chambre de mon fils est en haut.","tgt":"Kamar anak saya di atas.","lit":"chambre · enfant · je · à · haut"},{"fr":"C'est la moto de Monsieur Budi.","tgt":"Itu motor Pak Budi.","lit":"cela · moto · Monsieur · Budi"},{"fr":"Leur jardin est plein de fleurs.","tgt":"Kebun mereka penuh bunga.","lit":"jardin · ils · plein · fleur"},{"fr":"Mon bureau est loin d'ici.","tgt":"Kantor saya jauh dari sini.","lit":"bureau · je · loin · de · ici"},{"fr":"Votre clé est sur la table.","tgt":"Kunci Anda di atas meja.","lit":"clé · vous · à · dessus · table"}],"tip":{"title":"Le possessif après le nom : « rumah saya »","example":"Voici ma maison. — Ini <b>rumah saya</b>.","body":"En indonésien, il n'y a pas de mots spéciaux comme mon, ton ou notre. On reprend simplement le pronom et on le place après le nom. Ainsi, ma maison se dit « rumah saya », mot à mot maison, moi. Votre maison se dit « rumah Anda », maison, vous, et leur maison « rumah mereka », maison, eux. Décomposons : « Ini rumah saya », c'est ceci, maison, moi, donc voici ma maison. Ça marche aussi avec un prénom : « motor Pak Budi », la moto de Monsieur Budi, sans aucun petit mot de. Et le genre n'existe pas, donc pas de mon ou ma à choisir. Vous entendrez aussi la terminaison « nya », qui veut dire son ou sa, comme dans « anaknya », son enfant. Astuce : dites d'abord la chose, puis le propriétaire, comme si vous montriez l'objet du doigt avant de regarder la personne.","lit":"ceci · maison · je","say":{"rumah saya":"rumah saya","rumah Anda":"rumah Anda","rumah mereka":"rumah mereka","Ini rumah saya":"Ini rumah saya","motor Pak Budi":"motor Pak Budi","anaknya":"anaknya","nya":"nya"}}},{"title":"Un nasi goreng bien chaud","phrases":[{"fr":"Un café chaud, s'il vous plaît.","tgt":"Tolong, kopi panas satu.","lit":"s'il vous plaît · café · chaud · un"},{"fr":"Je voudrais un thé sucré bien froid.","tgt":"Saya mau teh manis dingin.","lit":"je · vouloir · thé · sucré · froid"},{"fr":"Ce nasi goreng est délicieux.","tgt":"Nasi goreng ini enak.","lit":"riz · frit · ce · délicieux"},{"fr":"J'aime le riz blanc.","tgt":"Saya suka nasi putih.","lit":"je · aimer · riz · blanc"},{"fr":"Le poulet frit est très bon.","tgt":"Ayam gorengnya enak sekali.","lit":"poulet · frit-[le] · bon · très"},{"fr":"Je prends une grande portion.","tgt":"Saya pesan porsi besar.","lit":"je · commander · portion · grand"},{"fr":"Je voudrais de l'eau froide.","tgt":"Saya mau air dingin.","lit":"je · vouloir · eau · froid"},{"fr":"C'est le petit warung au bout de la rue.","tgt":"Itu warung kecil di ujung jalan.","lit":"cela · warung · petit · à · bout · rue"},{"fr":"Le café noir est trop amer.","tgt":"Kopi hitamnya terlalu pahit.","lit":"café · noir-[le] · trop · amer"},{"fr":"Je voudrais un jus d'orange frais.","tgt":"Saya mau jus jeruk segar.","lit":"je · vouloir · jus · orange · frais"}],"tip":{"title":"L'adjectif après le nom : « kopi panas »","example":"Un café chaud, s'il vous plaît. — Tolong, <b>kopi panas</b> satu.","body":"Ici, l'indonésien ressemble au français : l'adjectif se place après le nom. Un café chaud se dit « kopi panas », café, chaud. Mais en indonésien, c'est toujours le cas, même pour les adjectifs que nous mettons devant : un grand warung se dit « warung besar », warung, grand. Et l'adjectif ne s'accorde jamais, ni au féminin ni au pluriel. Le nom du plat le plus célèbre suit la même règle : « nasi goreng », c'est riz, frit, et « ayam goreng », poulet, frit. Décomposons : « Saya mau teh manis dingin », c'est je, vouloir, thé, sucré, froid. Si vous ajoutez « ini », ce, il se place tout à la fin : « nasi goreng ini », ce nasi goreng. Astuce : pensez au menu du warung, où chaque plat se lit dans cet ordre, le nom d'abord et la façon de le préparer ensuite.","lit":"s'il vous plaît · café · chaud · un","say":{"kopi panas":"kopi panas","warung besar":"warung besar","nasi goreng":"nasi goreng","ayam goreng":"ayam goreng","Saya mau teh manis dingin":"Saya mau teh manis dingin","ini":"ini","nasi goreng ini":"nasi goreng ini"}}},{"title":"Qu'est-ce que c'est, ça ?","phrases":[{"fr":"Ceci, qu'est-ce que c'est ?","tgt":"Ini apa?","lit":"ceci · quoi"},{"fr":"Ça, c'est du tempeh.","tgt":"Itu tempe.","lit":"cela · tempeh"},{"fr":"Ce plat est vraiment délicieux.","tgt":"Makanan ini enak sekali.","lit":"nourriture · ce · délicieux · très"},{"fr":"Et ça, c'est combien ?","tgt":"Itu berapa?","lit":"cela · combien"},{"fr":"Tenez, ceci est pour vous.","tgt":"Ini untuk Anda.","lit":"ceci · pour · vous"},{"fr":"Cette dame est ma voisine.","tgt":"Ibu itu tetangga saya.","lit":"dame · cela · voisin · je"},{"fr":"Je prends celui-ci.","tgt":"Saya ambil yang ini.","lit":"je · prendre · celui · ceci"},{"fr":"Pas celui-là, celui-ci.","tgt":"Bukan yang itu, yang ini.","lit":"pas · celui · cela · celui · ceci"},{"fr":"Ce marché est plein de vie.","tgt":"Pasar ini ramai sekali.","lit":"marché · ce · animé · très"},{"fr":"Ces gâteaux-là ont l'air bons.","tgt":"Kue itu kelihatan enak.","lit":"gâteau · cela · sembler · bon"}],"tip":{"title":"« Ini » et « itu » : ceci et cela","example":"Je prends celui-ci. — Saya ambil yang <b>ini</b>.","body":"Deux petits mots vous serviront partout : « ini », ceci, pour ce qui est proche, et « itu », cela, pour ce qui est plus loin. Seuls, ils remplacent un objet : « Ini apa ? », c'est quoi, ceci. Après un nom, ils deviennent ce, cette ou ces : « pasar ini », ce marché, « ibu itu », cette dame. Attention, l'ordre est inverse du français, car le mot vient toujours après le nom. Pour dire celui-ci ou celui-là, on ajoute « yang » devant : « yang ini », celui-ci, « yang itu », celui-là. Décomposons : « Saya ambil yang ini », c'est je, prendre, celui, ceci. Comme il n'y a pas de pluriel obligatoire, « kue itu » peut vouloir dire ce gâteau ou ces gâteaux. Astuce : au marché, montrez l'objet du doigt et dites « yang ini », c'est la phrase la plus utile de la semaine.","lit":"je · prendre · celui · ceci","say":{"Ini":"Ini","itu":"itu","ini":"ini","Ini apa ?":"Ini apa?","pasar ini":"pasar ini","ibu itu":"ibu itu","yang":"yang","yang ini":"yang ini","yang itu":"yang itu","Saya ambil yang ini":"Saya ambil yang ini","kue itu":"kue itu"}}},{"title":"Combien de mangues ?","phrases":[{"fr":"Un, deux, trois, quatre, cinq.","tgt":"Satu, dua, tiga, empat, lima.","lit":"un · deux · trois · quatre · cinq"},{"fr":"Six, sept, huit, neuf, dix.","tgt":"Enam, tujuh, delapan, sembilan, sepuluh.","lit":"six · sept · huit · neuf · dix"},{"fr":"Je voudrais trois mangues.","tgt":"Saya mau tiga mangga.","lit":"je · vouloir · trois · mangue"},{"fr":"Deux cafés au lait, s'il vous plaît.","tgt":"Tolong, dua kopi susu.","lit":"s'il vous plaît · deux · café · lait"},{"fr":"J'ai deux enfants.","tgt":"Saya punya dua anak.","lit":"je · avoir · deux · enfant"},{"fr":"Je prends dix œufs.","tgt":"Saya ambil sepuluh butir telur.","lit":"je · prendre · dix · [classificateur] · œuf"},{"fr":"Nous sommes quatre.","tgt":"Kami empat orang.","lit":"nous · quatre · personne"},{"fr":"Leur maison est au numéro sept.","tgt":"Rumah mereka nomor tujuh.","lit":"maison · ils · numéro · sept"},{"fr":"Mon bureau est au cinquième étage.","tgt":"Kantor saya di lantai lima.","lit":"bureau · je · à · étage · cinq"},{"fr":"Attendez cinq minutes, s'il vous plaît.","tgt":"Tolong tunggu lima menit.","lit":"s'il vous plaît · attendre · cinq · minute"}],"tip":{"title":"Compter de « satu » à « sepuluh »","example":"Je voudrais trois mangues. — Saya mau <b>tiga</b> mangga.","body":"Les dix premiers nombres sont la base de tout le reste, alors prenons-les tranquillement. On dit « satu », un, « dua », deux, « tiga », trois, « empat », quatre, et « lima », cinq. Puis « enam », six, « tujuh », sept, « delapan », huit, « sembilan », neuf, et enfin « sepuluh », dix. Le nombre se place devant le nom, comme en français, et le nom ne change pas : « tiga mangga », trois mangue, sans aucun pluriel. Décomposons : « Saya mau tiga mangga », c'est je, vouloir, trois, mangue. Pour un étage ou un numéro, le nombre vient après : « lantai lima », le cinquième étage, mot à mot étage cinq. Astuce : comptez sur vos doigts à voix haute en marchant vers le bureau, de « satu » à « sepuluh », puis à rebours.","lit":"je · vouloir · trois · mangue","say":{"satu":"satu","sepuluh":"sepuluh","dua":"dua","tiga":"tiga","empat":"empat","lima":"lima","enam":"enam","tujuh":"tujuh","delapan":"delapan","sembilan":"sembilan","tiga mangga":"tiga mangga","Saya mau tiga mangga":"Saya mau tiga mangga","lantai lima":"lantai lima"}}},{"title":"Les prix au marché","phrases":[{"fr":"Il coûte combien, celui-ci ?","tgt":"Yang ini berapa harganya?","lit":"celui · ceci · combien · prix-[son]"},{"fr":"Dix mille roupies.","tgt":"Sepuluh ribu rupiah.","lit":"dix · mille · roupie"},{"fr":"Quinze mille roupies le kilo.","tgt":"Lima belas ribu rupiah sekilo.","lit":"cinq · [onze à dix-neuf] · mille · roupie · un-kilo"},{"fr":"Ce poisson coûte cinquante mille roupies.","tgt":"Ikan ini lima puluh ribu rupiah.","lit":"poisson · ce · cinq · dizaine · mille · roupie"},{"fr":"C'est trop cher, Madame.","tgt":"Terlalu mahal, Bu.","lit":"trop · cher · Madame"},{"fr":"Vingt mille, c'est possible ?","tgt":"Dua puluh ribu, boleh?","lit":"deux · dizaine · mille · permis"},{"fr":"Le nasi goreng coûte vingt-cinq mille roupies.","tgt":"Nasi gorengnya dua puluh lima ribu rupiah.","lit":"riz · frit-[le] · deux · dizaine · cinq · mille · roupie"},{"fr":"Je n'ai que cent mille roupies.","tgt":"Saya cuma punya seratus ribu rupiah.","lit":"je · seulement · avoir · un-cent · mille · roupie"},{"fr":"Le loyer est de trois millions de roupies par mois.","tgt":"Sewa rumahnya tiga juta rupiah sebulan.","lit":"location · maison-[la] · trois · million · roupie · un-mois"},{"fr":"Gardez la monnaie, Monsieur.","tgt":"Ambil saja kembaliannya, Pak.","lit":"prendre · seulement · monnaie-[la] · Monsieur"}],"tip":{"title":"Les grands nombres : « puluh », « ratus », « ribu »","example":"Ce poisson coûte cinquante mille roupies. — Ikan ini lima <b>puluh</b> <b>ribu</b> rupiah.","body":"Avec la roupie, on parle vite en milliers, mais le système est d'une logique parfaite. On construit tout avec trois mots : « puluh », la dizaine, « ratus », la centaine, et « ribu », le millier. Vingt se dit « dua puluh », deux dizaines, trente « tiga puluh », trois dizaines. Pour un seul, on remplace « satu » par le petit « se » : « sepuluh », dix, « seratus », cent, « seribu », mille. De onze à dix-neuf, on ajoute « belas » : « lima belas », quinze. Décomposons : « lima puluh ribu », c'est cinq, dizaine, mille, donc cinquante mille. Et un million se dit « juta », comme dans « tiga juta », trois millions. Astuce : écoutez le prix comme un petit calcul, chiffre puis taille, et repérez toujours le mot « ribu » à la fin, c'est lui qui dit combien de billets sortir.","lit":"poisson · ce · cinq · dizaine · mille · roupie","say":{"puluh":"puluh","ratus":"ratus","ribu":"ribu","dua puluh":"dua puluh","tiga puluh":"tiga puluh","satu":"satu","sepuluh":"sepuluh","seratus":"seratus","seribu":"seribu","belas":"belas","lima belas":"lima belas","lima puluh ribu":"lima puluh ribu","juta":"juta","tiga juta":"tiga juta"}}},{"title":"Il y a un warung ici ?","phrases":[{"fr":"Il y a un warung près d'ici ?","tgt":"Ada warung dekat sini?","lit":"il y a · warung · près · ici"},{"fr":"Oui, il y en a un au coin, là-bas.","tgt":"Ada, di pojok sana.","lit":"il y a · à · coin · là-bas"},{"fr":"Vous avez du thé sucré ?","tgt":"Ada teh manis?","lit":"il y a · thé · sucré"},{"fr":"Il n'y a plus de riz.","tgt":"Tidak ada nasi lagi.","lit":"pas · il y a · riz · encore"},{"fr":"J'ai une petite question.","tgt":"Saya ada sedikit pertanyaan.","lit":"je · il y a · un peu · question"},{"fr":"Il y a beaucoup de monde au marché ce matin.","tgt":"Pagi ini ada banyak orang di pasar.","lit":"matin · ce · il y a · beaucoup · personne · à · marché"},{"fr":"Est-ce qu'il y a de l'eau chaude ?","tgt":"Apakah ada air panas?","lit":"[question] · il y a · eau · chaud"},{"fr":"Madame Sari est là ?","tgt":"Bu Sari ada?","lit":"Madame · Sari · il y a"},{"fr":"Elle n'est pas à la maison.","tgt":"Dia tidak ada di rumah.","lit":"elle · pas · il y a · à · maison"},{"fr":"Il y a un ojek devant la maison.","tgt":"Ada ojek di depan rumah.","lit":"il y a · ojek · à · devant · maison"}],"tip":{"title":"« Ada » : il y a, et avoir","example":"Il y a un warung près d'ici ? — <b>Ada</b> warung dekat sini?","body":"Le mot « ada » est un vrai passe-partout. D'abord, il veut dire il y a : « Ada ojek di depan rumah », il y a un ojek devant la maison. Ensuite, il sert à demander si quelque chose est disponible : « Ada teh manis ? », vous avez du thé sucré, mot à mot il y a thé sucré. Il veut aussi dire être là, être présent : « Bu Sari ada ? », Madame Sari est là ? Décomposons : « Ada warung dekat sini ? », c'est il y a, warung, près, ici. Pour la négation, on dit « tidak ada », il n'y a pas, et la réponse courte à une question est simplement « ada », oui il y en a. À l'oral, on dit aussi « saya ada », j'ai, à côté de « saya punya ». Astuce : dans un magasin, commencez toutes vos demandes par « ada », suivi de ce que vous cherchez, en faisant monter la voix.","lit":"il y a · warung · près · ici","say":{"Ada":"Ada","ada":"ada","Ada ojek di depan rumah":"Ada ojek di depan rumah","Ada teh manis ?":"Ada teh manis?","Bu Sari ada ?":"Bu Sari ada?","Ada warung dekat sini ?":"Ada warung dekat sini?","tidak ada":"tidak ada","saya ada":"saya ada","saya punya":"saya punya"}}},{"title":"Où est-ce qu'on est ?","phrases":[{"fr":"Je suis au bureau.","tgt":"Saya di kantor.","lit":"je · à · bureau"},{"fr":"Vous êtes où, en ce moment ?","tgt":"Anda di mana sekarang?","lit":"vous · à · où · maintenant"},{"fr":"Ce soir, je suis à la maison.","tgt":"Malam ini saya di rumah.","lit":"soir · ce · je · à · maison"},{"fr":"Le marché est à côté de la gare.","tgt":"Pasarnya di sebelah stasiun.","lit":"marché-[le] · à · côté · gare"},{"fr":"Le warung est en face du bureau.","tgt":"Warungnya di depan kantor.","lit":"warung-[le] · à · devant · bureau"},{"fr":"Mon portable est dans le sac.","tgt":"HP saya di dalam tas.","lit":"portable · je · à · intérieur · sac"},{"fr":"Les enfants sont à l'école.","tgt":"Anak-anak di sekolah.","lit":"enfant-enfant · à · école"},{"fr":"L'ojek est déjà devant.","tgt":"Ojeknya sudah di depan.","lit":"ojek-[le] · [accompli] · à · devant"},{"fr":"Mon bureau est dans le quartier de Sudirman.","tgt":"Kantor saya di daerah Sudirman.","lit":"bureau · je · à · quartier · Sudirman"},{"fr":"Nous sommes à Jakarta depuis une semaine.","tgt":"Kami sudah satu minggu di Jakarta.","lit":"nous · [accompli] · une · semaine · à · Jakarta"}],"tip":{"title":"« Di » : être à un endroit","example":"Je suis au bureau. — Saya <b>di</b> kantor.","body":"Pour dire où l'on se trouve, il suffit du petit mot « di », qui veut dire à, dans ou en. Et comme il n'y a pas de verbe être, la phrase est ultra courte : « Saya di kantor », je, à, bureau, donc je suis au bureau. On peut préciser la position avec un deuxième mot : « di depan », devant, « di dalam », dedans, « di atas », dessus, ou « di sebelah », à côté. Décomposons : « HP saya di dalam tas », c'est portable, moi, à, intérieur, sac. Pour demander où, on dit « di mana », mot à mot à quoi, donc où : « Anda di mana ? », vous êtes où ? Attention à ne pas confondre avec « ke », qui veut dire vers et sert quand on se déplace : « ke kantor », au bureau, en y allant. Astuce : « di » pour être quelque part, « ke » pour y aller, comme une photo et une flèche.","lit":"je · à · bureau","say":{"Di":"Di","di":"di","Saya di kantor":"Saya di kantor","di depan":"di depan","di dalam":"di dalam","di atas":"di atas","di sebelah":"di sebelah","HP saya di dalam tas":"HP saya di dalam tas","di mana":"di mana","Anda di mana ?":"Anda di mana?","ke":"ke","ke kantor":"ke kantor"}}},{"title":"L'heure de partir au bureau","phrases":[{"fr":"Excusez-moi, il est quelle heure ?","tgt":"Permisi, sekarang jam berapa?","lit":"permission · maintenant · heure · combien"},{"fr":"Il est sept heures pile.","tgt":"Sekarang jam tujuh tepat.","lit":"maintenant · heure · sept · pile"},{"fr":"Je pars à huit heures.","tgt":"Saya berangkat jam delapan.","lit":"je · partir · heure · huit"},{"fr":"Le bureau ouvre à neuf heures.","tgt":"Kantor buka pukul sembilan.","lit":"bureau · ouvrir · heure · neuf"},{"fr":"Il est sept heures et demie.","tgt":"Sekarang jam setengah delapan.","lit":"maintenant · heure · moitié · huit"},{"fr":"On se voit à midi ?","tgt":"Kita ketemu jam dua belas?","lit":"nous · se rencontrer · heure · deux · [onze à dix-neuf]"},{"fr":"Notre réunion commence à dix heures.","tgt":"Rapat kami mulai pukul sepuluh.","lit":"réunion · nous · commencer · heure · dix"},{"fr":"Je travaille huit heures par jour.","tgt":"Saya kerja delapan jam sehari.","lit":"je · travailler · huit · heure · un-jour"},{"fr":"Ici, le marché ouvre dès cinq heures du matin.","tgt":"Pasar di sini buka dari jam lima pagi.","lit":"marché · à · ici · ouvrir · depuis · heure · cinq · matin"},{"fr":"Je rentre à six heures du soir.","tgt":"Saya pulang jam enam sore.","lit":"je · rentrer · heure · six · après-midi"}],"tip":{"title":"L'heure : « jam » et « pukul »","example":"Il est sept heures pile. — Sekarang <b>jam</b> tujuh tepat.","body":"Pour dire l'heure, on met le mot « jam », l'heure, devant le nombre : « jam tujuh », sept heures, mot à mot heure sept. Le mot « pukul » veut dire la même chose, mais il est plus officiel, on l'entend au bureau ou dans les annonces : « pukul sembilan », neuf heures. Attention, si le nombre vient avant « jam », on parle d'une durée : « delapan jam », c'est huit heures de temps. Pour demander l'heure, on dit « jam berapa ? », heure combien. La demi-heure réserve une surprise : on dit « setengah delapan », moitié huit, pour sept heures et demie, car on compte la moitié vers l'heure suivante. Décomposons : « Sekarang jam setengah delapan », c'est maintenant, heure, moitié, huit. Pour préciser, on ajoute « pagi », le matin, ou « malam », le soir. Astuce : « jam » devant, c'est l'horloge ; « jam » derrière, c'est le chronomètre.","lit":"maintenant · heure · sept · pile","say":{"jam":"jam","pukul":"pukul","jam tujuh":"jam tujuh","pukul sembilan":"pukul sembilan","delapan jam":"delapan jam","jam berapa ?":"jam berapa?","setengah delapan":"setengah delapan","Sekarang jam setengah delapan":"Sekarang jam setengah delapan","pagi":"pagi","malam":"malam"}}},{"title":"Les questions au bureau","phrases":[{"fr":"Qui est-ce, là-bas ?","tgt":"Siapa itu?","lit":"qui · cela"},{"fr":"C'est quoi, ce bruit ?","tgt":"Itu suara apa?","lit":"cela · son · quoi"},{"fr":"Les toilettes, c'est où ?","tgt":"Kamar kecil di mana?","lit":"chambre · petit · à · où"},{"fr":"Combien de personnes travaillent ici ?","tgt":"Berapa orang bekerja di sini?","lit":"combien · personne · travailler · à · ici"},{"fr":"Qui est votre chef ?","tgt":"Siapa atasan Anda?","lit":"qui · supérieur · vous"},{"fr":"Vous habitez où ?","tgt":"Anda tinggal di mana?","lit":"vous · habiter · à · où"},{"fr":"Quel âge a votre enfant ?","tgt":"Umur anak Anda berapa?","lit":"âge · enfant · vous · combien"},{"fr":"D'habitude, vous déjeunez où ?","tgt":"Biasanya Anda makan siang di mana?","lit":"d'habitude · vous · manger · midi · à · où"},{"fr":"Où est la salle de réunion ?","tgt":"Ruang rapat di mana?","lit":"salle · réunion · à · où"},{"fr":"Quel est votre numéro de portable ?","tgt":"Nomor HP Anda berapa?","lit":"numéro · portable · vous · combien"}],"tip":{"title":"Les mots interrogatifs : « apa », « siapa », « di mana », « berapa »","example":"Vous habitez où ? — Anda tinggal <b>di mana</b>?","body":"Quatre mots suffisent pour poser presque toutes les questions du quotidien. « Apa » veut dire quoi, « siapa » veut dire qui, « di mana » veut dire où, et « berapa » veut dire combien. Le plus agréable, c'est qu'on peut les laisser à la place de la réponse, exactement comme en français parlé quand on dit tu habites où. Décomposons : « Anda tinggal di mana ? », c'est vous, habiter, à, où. On peut aussi les mettre au début : « Siapa itu ? », qui est-ce. Notez que « berapa » sert pour tous les chiffres, même un numéro de téléphone ou un âge : « Nomor telepon Anda berapa ? », votre numéro, combien. Et « apa » placé après un nom veut dire quel : « suara apa », quel bruit. Astuce : faites la phrase normale, remplacez le mot inconnu par le mot question, et levez un peu la voix.","lit":"vous · habiter · à · où","say":{"apa":"apa","siapa":"siapa","di mana":"di mana","berapa":"berapa","Apa":"Apa","Anda tinggal di mana ?":"Anda tinggal di mana?","Siapa itu ?":"Siapa itu?","Nomor telepon Anda berapa ?":"Nomor telepon Anda berapa?","suara apa":"suara apa"}}},{"title":"Ce que je veux","phrases":[{"fr":"Je veux un nasi goreng, s'il vous plaît.","tgt":"Saya mau nasi goreng, ya.","lit":"je · vouloir · riz · frit · [hein]"},{"fr":"Vous voulez boire quoi ?","tgt":"Anda mau minum apa?","lit":"vous · vouloir · boire · quoi"},{"fr":"Je veux aller au marché.","tgt":"Saya mau ke pasar.","lit":"je · vouloir · vers · marché"},{"fr":"Vous voulez venir avec nous ?","tgt":"Anda mau ikut kami?","lit":"vous · vouloir · suivre · nous"},{"fr":"Je ne veux pas de sucre.","tgt":"Saya tidak mau pakai gula.","lit":"je · pas · vouloir · utiliser · sucre"},{"fr":"Je veux louer une maison.","tgt":"Saya mau sewa rumah.","lit":"je · vouloir · louer · maison"},{"fr":"Ma femme veut un thé chaud.","tgt":"Istri saya mau teh panas.","lit":"épouse · je · vouloir · thé · chaud"},{"fr":"On dirait qu'il va pleuvoir.","tgt":"Sepertinya mau hujan.","lit":"on dirait · vouloir · pluie"},{"fr":"Je voudrais payer, s'il vous plaît.","tgt":"Saya mau bayar, Bu.","lit":"je · vouloir · payer · Madame"},{"fr":"Vous allez où, Monsieur ?","tgt":"Mau ke mana, Pak?","lit":"vouloir · vers · où · Monsieur"}],"tip":{"title":"« Mau » : vouloir","example":"Je veux aller au marché. — Saya <b>mau</b> ke pasar.","body":"Le mot « mau » veut dire vouloir, et vous allez l'utiliser cent fois par jour. Il se place devant ce que l'on veut, un objet ou une action : « Saya mau kopi », je veux un café, « Saya mau bayar », je veux payer. Comme tous les verbes, il ne change jamais, et il n'est pas impoli : il sert aussi pour je voudrais. Décomposons : « Saya mau ke pasar », c'est je, vouloir, vers, marché, sans même un verbe aller. C'est d'ailleurs la question du chauffeur d'ojek : « Mau ke mana, Pak ? », vouloir, vers, où, Monsieur, donc vous allez où. Pour refuser, on dit « tidak mau », je ne veux pas. Et « mau » sert aussi pour un futur proche : « mau hujan », il va pleuvoir. Astuce : quand vous ne savez pas comment commencer une demande, dites « saya mau », puis montrez ce que vous voulez.","lit":"je · vouloir · vers · marché","say":{"Mau":"Mau","mau":"mau","Saya mau kopi":"Saya mau kopi","Saya mau bayar":"Saya mau bayar","Saya mau ke pasar":"Saya mau ke pasar","Mau ke mana, Pak ?":"Mau ke mana, Pak?","tidak mau":"tidak mau","mau hujan":"mau hujan","saya mau":"saya mau"}}},{"title":"Les enfants des voisins","phrases":[{"fr":"Les enfants jouent dans la rue.","tgt":"Anak-anak bermain di jalan.","lit":"enfant-enfant · jouer · à · rue"},{"fr":"Les maisons sont petites ici.","tgt":"Rumah-rumah di sini kecil.","lit":"maison-maison · à · ici · petit"},{"fr":"Bonjour, mesdames !","tgt":"Selamat pagi, ibu-ibu!","lit":"bon · matin · madame-madame"},{"fr":"Mes amis arrivent ce soir.","tgt":"Teman-teman saya datang malam ini.","lit":"ami-ami · je · venir · soir · ce"},{"fr":"Il y a beaucoup d'enfants dans cette école.","tgt":"Ada banyak anak di sekolah ini.","lit":"il y a · beaucoup · enfant · à · école · ce"},{"fr":"Il y a deux chats sur le toit.","tgt":"Ada dua kucing di atap.","lit":"il y a · deux · chat · à · toit"},{"fr":"Les légumes sont frais ici.","tgt":"Sayur-sayuran di sini segar.","lit":"légume-légumes · à · ici · frais"},{"fr":"Les messieurs boivent du café au warung.","tgt":"Bapak-bapak minum kopi di warung.","lit":"monsieur-monsieur · boire · café · à · warung"},{"fr":"Les enfants, venez manger !","tgt":"Anak-anak, ayo makan!","lit":"enfant-enfant · allez · manger"},{"fr":"Ce sont mes collègues de bureau.","tgt":"Mereka teman-teman kantor saya.","lit":"ils · ami-ami · bureau · je"}],"tip":{"title":"Le pluriel par redoublement : « anak-anak »","example":"Les enfants jouent dans la rue. — <b>Anak-anak</b> bermain di jalan.","body":"En indonésien, un nom n'a pas de pluriel obligatoire : « anak » peut vouloir dire un enfant ou des enfants, selon le contexte. Quand on veut vraiment insister sur le pluriel, on répète simplement le mot : « anak-anak », enfant enfant, donc les enfants. De même, « rumah-rumah » veut dire les maisons, et « teman-teman », les amis. Décomposons : « Anak-anak bermain di jalan », c'est enfant, enfant, jouer, à, rue. Attention, si vous avez déjà un nombre ou le mot « banyak », beaucoup, on ne répète pas : on dit « dua kucing », deux chats, et « banyak anak », beaucoup d'enfants. Le redoublement sert aussi pour saluer un groupe avec chaleur : « ibu-ibu », mesdames. Astuce : dites le mot deux fois d'un seul souffle, sans pause, comme un petit écho joyeux.","lit":"enfant-enfant · jouer · à · rue","say":{"anak-anak":"anak-anak","anak":"anak","rumah-rumah":"rumah-rumah","teman-teman":"teman-teman","Anak-anak bermain di jalan":"Anak-anak bermain di jalan","banyak":"banyak","dua kucing":"dua kucing","banyak anak":"banyak anak","ibu-ibu":"ibu-ibu"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Merci beaucoup pour tout !","tgt":"Terima kasih banyak atas semuanya!","lit":"merci · beaucoup · pour · tout"},{"fr":"Je vous en prie, Madame.","tgt":"Sama-sama, Bu.","lit":"pareil-pareil · Madame"},{"fr":"Pardon, je suis en retard.","tgt":"Maaf, saya terlambat.","lit":"pardon · je · en retard"},{"fr":"Excusez-moi, je peux passer ?","tgt":"Permisi, numpang lewat.","lit":"permission · emprunter · passer"},{"fr":"Ce premier module est déjà terminé.","tgt":"Modul pertama ini sudah selesai.","lit":"module · premier · ce · [accompli] · fini"},{"fr":"Maintenant, je parle un peu indonésien.","tgt":"Sekarang saya bisa sedikit bahasa Indonesia.","lit":"maintenant · je · pouvoir · un peu · langue · Indonésie"},{"fr":"L'indonésien n'est pas si difficile.","tgt":"Bahasa Indonesia tidak terlalu sulit.","lit":"langue · Indonésie · pas · trop · difficile"},{"fr":"Maintenant, je connais bien mon quartier.","tgt":"Sekarang saya sudah kenal baik daerah saya.","lit":"maintenant · je · [accompli] · connaître · bien · quartier · je"},{"fr":"Le module suivant parlera de voyages.","tgt":"Modul berikutnya tentang perjalanan.","lit":"module · suivant · sur · voyage"},{"fr":"Merci, et à très bientôt !","tgt":"Terima kasih, sampai jumpa lagi!","lit":"merci · jusqu'à · rencontre · encore"}],"tip":{"title":"Les formules magiques : « terima kasih », « sama-sama », « maaf », « permisi »","example":"Excusez-moi, je peux passer ? — <b>Permisi</b>, numpang lewat.","body":"Pour finir ce module, voici quatre formules qui rendent la vie à Jakarta tellement plus douce. « Terima kasih » veut dire merci, mot à mot recevoir l'affection, et « terima kasih banyak », merci beaucoup. On y répond par « sama-sama », de rien, mot à mot pareil pareil, comme pour dire merci à vous aussi. « Maaf » veut dire pardon ou désolé, quand on a fait une erreur ou qu'on arrive en retard. « Permisi », enfin, c'est l'excusez-moi que l'on dit avant de déranger, pour passer devant quelqu'un, entrer chez un voisin ou appeler un vendeur. Décomposons : « Permisi, numpang lewat », c'est permission, emprunter, passer, donc je peux passer. On peut les adoucir en ajoutant « Pak » ou « Bu » à la fin. Astuce : « permisi » avant, « maaf » après, et « terima kasih » toujours, avec un sourire.","lit":"permission · emprunter · passer","say":{"terima kasih":"terima kasih","sama-sama":"sama-sama","maaf":"maaf","permisi":"permisi","Terima kasih":"Terima kasih","terima kasih banyak":"terima kasih banyak","Maaf":"Maaf","Permisi":"Permisi","Permisi, numpang lewat":"Permisi, numpang lewat","Pak":"Pak","Bu":"Bu"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Indonésie.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport de Bali","phrases":[{"fr":"Bonjour, je viens d'arriver à Bali.","tgt":"Selamat siang, saya baru tiba di Bali.","lit":"bon · midi · je · juste · arriver · à · Bali"},{"fr":"La porte de sortie, c'est où ?","tgt":"Di mana pintu keluar?","lit":"à · où · porte · sortir"},{"fr":"Voici mon passeport, madame.","tgt":"Ini paspor saya, Bu.","lit":"ceci · passeport · je · madame"},{"fr":"Je suis ici en touriste.","tgt":"Saya di sini sebagai turis.","lit":"je · à · ici · en tant que · touriste"},{"fr":"Je reste deux semaines à Bali.","tgt":"Saya tinggal dua minggu di Bali.","lit":"je · rester · deux · semaine · à · Bali"},{"fr":"Où est ma valise ?","tgt":"Di mana koper saya?","lit":"à · où · valise · je"},{"fr":"Cette valise est à moi.","tgt":"Koper ini milik saya.","lit":"valise · ceci · propriété · je"},{"fr":"Y a-t-il un distributeur ici ?","tgt":"Apakah ada ATM di sini?","lit":"[question] · il y a · distributeur · à · ici"},{"fr":"Je cherche un taxi.","tgt":"Saya cari taksi.","lit":"je · chercher · taxi"},{"fr":"Il fait très chaud ici !","tgt":"Di sini panas sekali!","lit":"à · ici · chaud · très"}]},{"title":"Le premier jour sur l'île","phrases":[{"fr":"Je suis arrivé hier.","tgt":"Saya tiba kemarin.","lit":"je · arriver · hier"},{"fr":"Aujourd'hui, je me repose.","tgt":"Hari ini saya istirahat.","lit":"jour · ceci · je · se reposer"},{"fr":"Demain, je vais à Ubud.","tgt":"Besok saya ke Ubud.","lit":"demain · je · vers · Ubud"},{"fr":"Hier, il a plu.","tgt":"Kemarin hujan.","lit":"hier · pluie"},{"fr":"Aujourd'hui, le ciel de Bali est clair.","tgt":"Hari ini langit Bali cerah.","lit":"jour · ceci · ciel · Bali · clair"},{"fr":"Demain matin, je vais à la plage.","tgt":"Besok pagi saya ke pantai.","lit":"demain · matin · je · vers · plage"},{"fr":"Hier soir, j'ai mangé du satay.","tgt":"Kemarin malam saya makan sate.","lit":"hier · soir · je · manger · satay"},{"fr":"Où allez-vous aujourd'hui ?","tgt":"Hari ini Anda mau ke mana?","lit":"jour · ceci · vous · vouloir · vers · où"},{"fr":"Aujourd'hui, je suis fatigué.","tgt":"Hari ini saya capek.","lit":"jour · ceci · je · fatigué"},{"fr":"À demain, alors !","tgt":"Sampai besok, ya!","lit":"jusqu'à · demain · oui"}],"tip":{"title":"« Hari ini », « besok », « kemarin » : aujourd'hui, demain, hier","example":"Demain, je vais à Ubud. — <b>Besok</b> saya ke Ubud.","body":"En indonésien, le verbe ne change jamais : c'est le petit mot de temps qui dit quand ça se passe. « Hari ini » veut dire aujourd'hui, mot à mot jour ceci. « Besok » veut dire demain, et « kemarin » veut dire hier. On les place volontiers en tête de phrase, comme en français : « Besok saya ke Ubud », mot à mot demain moi vers Ubud, demain, je vais à Ubud. Avec « kemarin », la même phrase passe au passé sans rien changer d'autre : « Kemarin saya ke Ubud », hier, je suis allé à Ubud. On peut ajouter « pagi » pour le matin ou « malam » pour le soir : « besok pagi », demain matin. Pour retenir, pensez que « besok » ressemble à besoin : demain, j'aurai besoin de repos.","lit":"demain · je · vers · Ubud","say":{"Hari ini":"Hari ini","besok":"besok","kemarin":"kemarin","Besok":"Besok","Besok saya ke Ubud":"Besok saya ke Ubud","Kemarin saya ke Ubud":"Kemarin saya ke Ubud","pagi":"pagi","malam":"malam","besok pagi":"besok pagi"}}},{"title":"Le taxi pour Ubud","phrases":[{"fr":"Bonjour monsieur, je voudrais aller à Ubud.","tgt":"Selamat siang, Pak, saya mau ke Ubud.","lit":"bon · midi · monsieur · je · vouloir · vers · Ubud"},{"fr":"Il faut combien de temps pour Ubud ?","tgt":"Berapa lama ke Ubud?","lit":"combien · longtemps · vers · Ubud"},{"fr":"Environ une heure.","tgt":"Kira-kira satu jam.","lit":"environ · un · heure"},{"fr":"Voici l'adresse de l'hôtel.","tgt":"Ini alamat hotelnya.","lit":"ceci · adresse · hôtel-[le]"},{"fr":"La route est très embouteillée.","tgt":"Jalannya macet sekali.","lit":"route-[la] · embouteillé · très"},{"fr":"La climatisation est trop froide.","tgt":"AC-nya terlalu dingin.","lit":"climatisation-[la] · trop · froid"},{"fr":"Arrêtez-vous ici, monsieur.","tgt":"Berhenti di sini, Pak.","lit":"s'arrêter · à · ici · monsieur"},{"fr":"Je vous dois combien, monsieur ?","tgt":"Berapa, Pak?","lit":"combien · monsieur"},{"fr":"Gardez la monnaie, je vous en prie.","tgt":"Kembaliannya untuk Bapak saja.","lit":"monnaie-[la] · pour · monsieur · seulement"},{"fr":"Le chauffeur est très gentil.","tgt":"Sopirnya baik sekali.","lit":"chauffeur-[le] · gentil · très"}]},{"title":"À la réception de l'hôtel","phrases":[{"fr":"J'ai réservé une chambre.","tgt":"Saya sudah pesan kamar.","lit":"je · [accompli] · réserver · chambre"},{"fr":"Prenez place ici, je vous en prie.","tgt":"Silakan duduk di sini.","lit":"je vous en prie · s'asseoir · à · ici"},{"fr":"Entrez donc, je vous en prie.","tgt":"Silakan masuk.","lit":"je vous en prie · entrer"},{"fr":"Aidez-moi, s'il vous plaît.","tgt":"Tolong bantu saya.","lit":"s'il vous plaît · aider · je"},{"fr":"Appelez un taxi, s'il vous plaît.","tgt":"Tolong panggil taksi.","lit":"s'il vous plaît · appeler · taxi"},{"fr":"Je vous en prie, voici la clé.","tgt":"Silakan, ini kuncinya.","lit":"je vous en prie · ceci · clé-[la]"},{"fr":"Le petit-déjeuner est à sept heures.","tgt":"Sarapan jam tujuh.","lit":"petit-déjeuner · heure · sept"},{"fr":"Servez-vous, je vous en prie.","tgt":"Silakan ambil.","lit":"je vous en prie · prendre"},{"fr":"Répétez, s'il vous plaît.","tgt":"Tolong ulangi.","lit":"s'il vous plaît · répéter"},{"fr":"Le wifi a quel mot de passe ?","tgt":"Apa kata sandi wifinya?","lit":"quoi · mot · secret · wifi-[le]"}],"tip":{"title":"« Tolong » et « silakan » : s'il vous plaît","example":"Aidez-moi, s'il vous plaît. — <b>Tolong</b> bantu saya.","body":"Le français n'a qu'une formule, s'il vous plaît, mais l'indonésien en a deux, selon qui profite de l'action. « Tolong », c'est quand vous demandez un service pour vous : « Tolong bantu saya », mot à mot s'il vous plaît, aider, moi. Ce mot veut d'ailleurs dire aussi à l'aide. « Silakan », c'est quand vous invitez l'autre à faire quelque chose pour lui-même, comme je vous en prie : « Silakan masuk », entrez, ou « Silakan duduk », asseyez-vous. On place les deux mots tout au début de la phrase, juste avant le verbe. À l'hôtel, vous direz donc souvent « tolong », et la réceptionniste vous répondra « silakan ». Pour retenir : « tolong » quand c'est pour moi, « silakan » quand c'est pour vous.","lit":"s'il vous plaît · aider · je","say":{"Tolong":"Tolong","silakan":"silakan","Tolong bantu saya":"Tolong bantu saya","Silakan":"Silakan","Silakan masuk":"Silakan masuk","Silakan duduk":"Silakan duduk","tolong":"tolong"}}},{"title":"Une chambre à Ubud","phrases":[{"fr":"La chambre est très belle.","tgt":"Kamarnya bagus sekali.","lit":"chambre-[la] · beau · très"},{"fr":"Il y a une vue sur les rizières.","tgt":"Ada pemandangan sawah.","lit":"il y a · vue · rizière"},{"fr":"La salle de bain n'a pas d'eau chaude.","tgt":"Di kamar mandi tidak ada air panas.","lit":"à · pièce · se laver · ne pas · il y a · eau · chaud"},{"fr":"La climatisation est en panne.","tgt":"AC-nya rusak.","lit":"climatisation-[la] · cassé"},{"fr":"Je voudrais une serviette de plus.","tgt":"Saya mau handuk lagi.","lit":"je · vouloir · serviette · encore"},{"fr":"La chambre est un peu petite.","tgt":"Kamarnya agak kecil.","lit":"chambre-[la] · un peu · petit"},{"fr":"Il y a des moustiques.","tgt":"Ada nyamuk.","lit":"il y a · moustique"},{"fr":"Le lit est grand.","tgt":"Tempat tidurnya besar.","lit":"lieu · dormir-[le] · grand"},{"fr":"Il y a une piscine ?","tgt":"Ada kolam renang?","lit":"il y a · bassin · nager"},{"fr":"C'est calme, ici.","tgt":"Di sini tenang.","lit":"à · ici · calme"}]},{"title":"Au marché aux souvenirs","phrases":[{"fr":"Combien ça coûte ?","tgt":"Berapa harganya?","lit":"combien · prix-[le]"},{"fr":"Ce sarong coûte combien ?","tgt":"Berapa harga sarung ini?","lit":"combien · prix · sarong · ceci"},{"fr":"Cinquante mille roupies.","tgt":"Lima puluh ribu rupiah.","lit":"cinq · dizaine · mille · roupie"},{"fr":"Oh, c'est trop cher pour moi !","tgt":"Wah, terlalu mahal untuk saya!","lit":"oh · trop · cher · pour · je"},{"fr":"Vous pouvez faire moins ?","tgt":"Bisa kurang?","lit":"pouvoir · moins"},{"fr":"Trente mille, d'accord ?","tgt":"Tiga puluh ribu, ya?","lit":"trois · dizaine · mille · oui"},{"fr":"Et celui-ci, il coûte combien ?","tgt":"Kalau yang ini, berapa harganya?","lit":"si · celui · ceci · combien · prix-[le]"},{"fr":"J'en prends deux.","tgt":"Saya beli dua.","lit":"je · acheter · deux"},{"fr":"Tout ça, ça fait combien ?","tgt":"Semuanya berapa?","lit":"tout-[le] · combien"},{"fr":"Les deux pour cent mille roupies.","tgt":"Dua-duanya seratus ribu rupiah.","lit":"deux-deux-[les] · cent · mille · roupie"}],"tip":{"title":"« Berapa harganya ? » : demander un prix en roupies","example":"Combien ça coûte ? — <b>Berapa</b> <b>harganya</b>?","body":"Pour demander un prix, une seule phrase suffit : « Berapa harganya ? ». « Berapa » veut dire combien, « harga » veut dire prix, et la petite finale « nya » joue le rôle de l'article : mot à mot combien le prix. Pour un objet précis, on dit « Berapa harga sarung ini ? », combien prix sarong ceci. La réponse arrive presque toujours en milliers de roupies : « ribu » veut dire mille, donc « lima puluh ribu », cinq dizaines mille, c'est cinquante mille. Sur le marché, vous pouvez ensuite tenter « Bisa kurang ? », vous pouvez faire moins, avec le sourire. Dans la conversation de tous les jours, on dit même souvent « Berapa ? » tout court, en montrant l'objet du doigt. Astuce : retenez le refrain « berapa, berapa », vous l'entendrez partout à Bali.","lit":"combien · prix-[le]","say":{"Berapa harganya ?":"Berapa harganya?","Berapa":"Berapa","harga":"harga","Berapa harga sarung ini ?":"Berapa harga sarung ini?","ribu":"ribu","lima puluh ribu":"lima puluh ribu","Bisa kurang ?":"Bisa kurang?","Berapa ?":"Berapa?","berapa, berapa":"berapa, berapa","nya":"nya"}}},{"title":"Changer de l'argent","phrases":[{"fr":"Je voudrais changer de l'argent.","tgt":"Saya mau tukar uang.","lit":"je · vouloir · échanger · argent"},{"fr":"Où peut-on changer de l'argent ?","tgt":"Di mana tempat tukar uang?","lit":"à · où · lieu · échanger · argent"},{"fr":"Le taux est bon aujourd'hui ?","tgt":"Kursnya bagus hari ini?","lit":"taux-[le] · bon · jour · ceci"},{"fr":"J'ai deux cents euros.","tgt":"Saya punya dua ratus euro.","lit":"je · avoir · deux · centaine · euro"},{"fr":"Recomptez, s'il vous plaît.","tgt":"Tolong hitung lagi.","lit":"s'il vous plaît · compter · encore"},{"fr":"Il manque dix mille roupies.","tgt":"Kurang sepuluh ribu rupiah.","lit":"manquer · dix · mille · roupie"},{"fr":"Avez-vous des petits billets ?","tgt":"Ada uang kecil?","lit":"il y a · argent · petit"},{"fr":"Pardon, je n'ai pas de petits billets.","tgt":"Maaf, saya tidak punya uang kecil.","lit":"pardon · je · ne pas · avoir · argent · petit"},{"fr":"Le distributeur est en panne.","tgt":"ATM-nya rusak.","lit":"distributeur-[le] · cassé"},{"fr":"Je paie en espèces.","tgt":"Saya bayar tunai.","lit":"je · payer · espèces"}]},{"title":"Les trajets sur l'île","phrases":[{"fr":"Mon ami et moi venons de Paris.","tgt":"Saya dan teman saya dari Paris.","lit":"je · et · ami · je · de · Paris"},{"fr":"De l'aéroport à Ubud, c'est combien ?","tgt":"Dari bandara ke Ubud berapa?","lit":"de · aéroport · vers · Ubud · combien"},{"fr":"Ce bus va de Denpasar à Ubud.","tgt":"Bus ini dari Denpasar ke Ubud.","lit":"bus · ceci · de · Denpasar · vers · Ubud"},{"fr":"D'Ubud à la plage, c'est loin ?","tgt":"Dari Ubud ke pantai jauh?","lit":"de · Ubud · vers · plage · loin"},{"fr":"De l'hôtel au marché, il y a dix minutes.","tgt":"Dari hotel ke pasar sepuluh menit.","lit":"de · hôtel · vers · marché · dix · minute"},{"fr":"Je vais de Bali à Lombok.","tgt":"Saya pergi dari Bali ke Lombok.","lit":"je · aller · de · Bali · vers · Lombok"},{"fr":"D'où part le bateau ?","tgt":"Kapalnya berangkat dari mana?","lit":"bateau-[le] · partir · de · où"},{"fr":"Du port de Padang Bai.","tgt":"Dari pelabuhan Padang Bai.","lit":"de · port · Padang Bai"},{"fr":"Je me promène du matin au soir.","tgt":"Saya jalan-jalan dari pagi sampai malam.","lit":"je · se promener · de · matin · jusqu'à · soir"},{"fr":"Et vous, d'où venez-vous ?","tgt":"Kalau Anda, dari mana?","lit":"si · vous · de · où"}],"tip":{"title":"« Dari... ke... » : de... à...","example":"De l'aéroport à Ubud, c'est combien ? — <b>Dari</b> bandara <b>ke</b> Ubud berapa?","body":"Pour dire d'où l'on part et où l'on va, l'indonésien utilise deux petits mots très réguliers : « dari », de, et « ke », vers. On les enchaîne exactement comme en français : « dari bandara ke Ubud », de l'aéroport à Ubud. Remarquez qu'on n'a même pas besoin du verbe aller : « ke » suffit à montrer la direction. « Saya ke pantai » veut dire je vais à la plage, mot à mot moi vers plage. « Dari » sert aussi pour l'origine : « Saya dari Paris », je viens de Paris. Pour demander l'origine de quelqu'un, on dit « Anda dari mana ? », vous de où. Pour le temps, on remplace « ke » par « sampai », jusqu'à : « dari pagi sampai malam », du matin au soir. Astuce : « ke » est court comme une flèche qui pointe vers la destination.","lit":"de · aéroport · vers · Ubud · combien","say":{"Dari... ke...":"Dari... ke...","dari":"dari","ke":"ke","dari bandara ke Ubud":"dari bandara ke Ubud","Saya ke pantai":"Saya ke pantai","Dari":"Dari","Saya dari Paris":"Saya dari Paris","Anda dari mana ?":"Anda dari mana?","sampai":"sampai","dari pagi sampai malam":"dari pagi sampai malam"}}},{"title":"Les rizières en terrasses","phrases":[{"fr":"Les rizières sont magnifiques.","tgt":"Sawahnya indah sekali.","lit":"rizière-[la] · beau · très"},{"fr":"Tout est si vert !","tgt":"Hijau sekali!","lit":"vert · très"},{"fr":"Je voudrais prendre une photo.","tgt":"Saya mau ambil foto.","lit":"je · vouloir · prendre · photo"},{"fr":"Ce matin, il y a plein de touristes.","tgt":"Pagi ini banyak turis.","lit":"matin · ceci · beaucoup · touriste"},{"fr":"Le chemin est glissant.","tgt":"Jalannya licin.","lit":"chemin-[le] · glissant"},{"fr":"Attention, c'est boueux.","tgt":"Hati-hati, becek.","lit":"attention · boueux"},{"fr":"Ce paysan travaille dans la rizière.","tgt":"Petani itu kerja di sawah.","lit":"paysan · cela · travailler · à · rizière"},{"fr":"On a le droit de marcher ici ?","tgt":"Boleh jalan di sini?","lit":"avoir le droit · marcher · à · ici"},{"fr":"Il faut payer l'entrée ?","tgt":"Harus bayar tiket masuk?","lit":"devoir · payer · billet · entrer"},{"fr":"Dix mille roupies par personne.","tgt":"Sepuluh ribu rupiah per orang.","lit":"dix · mille · roupie · par · personne"}]},{"title":"Prêts pour l'excursion","phrases":[{"fr":"Vous avez déjà déjeuné ?","tgt":"Sudah makan siang?","lit":"[accompli] · manger · midi"},{"fr":"Pas encore, j'ai faim.","tgt":"Belum, saya lapar.","lit":"pas encore · je · faim"},{"fr":"Le chauffeur est déjà là.","tgt":"Sopirnya sudah datang.","lit":"chauffeur-[le] · [accompli] · venir"},{"fr":"Je n'ai pas encore fini.","tgt":"Saya belum selesai.","lit":"je · pas encore · fini"},{"fr":"Vous êtes prêt ?","tgt":"Anda sudah siap?","lit":"vous · [accompli] · prêt"},{"fr":"Oui, je suis prêt.","tgt":"Ya, saya sudah siap.","lit":"oui · je · [accompli] · prêt"},{"fr":"J'ai déjà payé.","tgt":"Saya sudah bayar.","lit":"je · [accompli] · payer"},{"fr":"La boutique n'est pas encore ouverte.","tgt":"Tokonya belum buka.","lit":"boutique-[la] · pas encore · ouvrir"},{"fr":"J'ai déjà réservé le billet de bateau.","tgt":"Saya sudah pesan tiket kapal.","lit":"je · [accompli] · réserver · billet · bateau"},{"fr":"Il est déjà huit heures !","tgt":"Sudah jam delapan!","lit":"[accompli] · heure · huit"}],"tip":{"title":"« Sudah » et « belum » : déjà et pas encore","example":"Le chauffeur est déjà là. — Sopirnya <b>sudah</b> datang.","body":"« Sudah » veut dire déjà, et c'est le grand marqueur de l'action accomplie, puisque le verbe ne se conjugue pas. « Saya sudah bayar », mot à mot moi déjà payer, veut dire j'ai payé. Son contraire est « belum », pas encore. C'est une négation pleine d'optimisme : on ne dit pas non, on dit pas encore. À la question « Sudah makan ? », vous avez déjà mangé, on répond « sudah » ou « belum », jamais « tidak ». Cette question est d'ailleurs une façon amicale de saluer, un peu comme un comment ça va. « Sudah » s'emploie aussi pour l'heure : « Sudah jam delapan », il est déjà huit heures. Pour retenir, répétez la paire en marchant : « sudah, belum », c'est fait, pas encore.","lit":"chauffeur-[le] · [accompli] · venir","say":{"Sudah":"Sudah","belum":"belum","Saya sudah bayar":"Saya sudah bayar","Sudah makan ?":"Sudah makan?","sudah":"sudah","tidak":"tidak","Sudah jam delapan":"Sudah jam delapan","sudah, belum":"sudah, belum"}}},{"title":"Au warung : satay et jus de mangue","phrases":[{"fr":"Je voudrais du satay de poulet.","tgt":"Saya mau sate ayam.","lit":"je · vouloir · satay · poulet"},{"fr":"Un jus de mangue, s'il vous plaît.","tgt":"Jus mangga satu, ya.","lit":"jus · mangue · un · oui"},{"fr":"Pas trop épicé, s'il vous plaît.","tgt":"Jangan terlalu pedas, ya.","lit":"ne pas (ordre) · trop · épicé · oui"},{"fr":"Ce satay est délicieux !","tgt":"Sate ini enak sekali!","lit":"satay · ceci · bon · très"},{"fr":"Avec du riz ?","tgt":"Pakai nasi?","lit":"utiliser · riz"},{"fr":"Oui, avec du riz blanc.","tgt":"Ya, pakai nasi putih.","lit":"oui · utiliser · riz · blanc"},{"fr":"Sans glaçons, s'il vous plaît.","tgt":"Tidak pakai es, ya.","lit":"ne pas · utiliser · glace · oui"},{"fr":"La sauce aux cacahuètes est très bonne.","tgt":"Bumbu kacangnya enak sekali.","lit":"sauce · cacahuète-[la] · bon · très"},{"fr":"Je voudrais payer, madame.","tgt":"Saya mau bayar, Bu.","lit":"je · vouloir · payer · madame"},{"fr":"J'ai encore faim.","tgt":"Saya masih lapar.","lit":"je · encore · faim"}]},{"title":"Demander son chemin","phrases":[{"fr":"Comment aller au marché d'Ubud ?","tgt":"Bagaimana cara ke Pasar Ubud?","lit":"comment · manière · vers · marché · Ubud"},{"fr":"Comment allez-vous aujourd'hui ?","tgt":"Bagaimana kabarnya hari ini?","lit":"comment · nouvelle-[la] · jour · ceci"},{"fr":"Excusez-moi, où est la plage ?","tgt":"Permisi, pantainya di mana?","lit":"pardon · plage-[la] · à · où"},{"fr":"Allez tout droit, c'est facile.","tgt":"Jalan terus saja, gampang.","lit":"marcher · continuer · seulement · facile"},{"fr":"Puis tournez à gauche après le pont.","tgt":"Lalu belok kiri sesudah jembatan.","lit":"ensuite · tourner · gauche · après · pont"},{"fr":"Au carrefour, tournez à droite.","tgt":"Di perempatan belok kanan.","lit":"à · carrefour · tourner · droite"},{"fr":"Comment s'est passé le voyage ?","tgt":"Bagaimana perjalanannya?","lit":"comment · voyage-[le]"},{"fr":"Comment trouvez-vous Bali ?","tgt":"Bagaimana Bali menurut Anda?","lit":"comment · Bali · selon · vous"},{"fr":"Je me suis perdu.","tgt":"Saya tersesat.","lit":"je · perdu"},{"fr":"C'est à côté de l'hôtel.","tgt":"Di sebelah hotel.","lit":"à · côté · hôtel"}],"tip":{"title":"« Bagaimana » : comment, et demander son chemin","example":"Comment aller au marché d'Ubud ? — <b>Bagaimana</b> cara ke Pasar Ubud?","body":"« Bagaimana » veut dire comment. On le prononce en entier, « ba, ga, i, ma, na », chaque syllabe compte. Pour demander comment aller quelque part, on ajoute « cara », la manière : « Bagaimana cara ke Pasar Ubud ? », mot à mot comment manière vers marché Ubud. Le même mot sert à demander des nouvelles ou un avis : « Bagaimana kabarnya ? », comment allez-vous, ou « Bagaimana perjalanannya ? », comment s'est passé le voyage. Pour comprendre la réponse, retenez trois mots : « kiri », gauche, « kanan », droite, et « terus », tout droit. Dans la rue, commencez toujours par « permisi », excusez-moi, c'est très poli. Astuce : « bagaimana » est un long mot qui roule, comme le chemin qu'on vous explique.","lit":"comment · manière · vers · marché · Ubud","say":{"Bagaimana":"Bagaimana","cara":"cara","Bagaimana cara ke Pasar Ubud ?":"Bagaimana cara ke Pasar Ubud?","Bagaimana kabarnya ?":"Bagaimana kabarnya?","Bagaimana perjalanannya ?":"Bagaimana perjalanannya?","kiri":"kiri","kanan":"kanan","terus":"terus","permisi":"permisi","bagaimana":"bagaimana","ba, ga, i, ma, na":"ba, ga, i, ma, na"}}},{"title":"Une journée à la plage","phrases":[{"fr":"La mer est belle aujourd'hui.","tgt":"Lautnya indah hari ini.","lit":"mer-[la] · beau · jour · ceci"},{"fr":"Le sable est vraiment très chaud.","tgt":"Pasirnya panas sekali.","lit":"sable-[le] · chaud · très"},{"fr":"Je voudrais louer une planche de surf.","tgt":"Saya mau sewa papan selancar.","lit":"je · vouloir · louer · planche · surf"},{"fr":"Les vagues sont grandes.","tgt":"Ombaknya besar.","lit":"vague-[la] · grand"},{"fr":"Attention, le courant est fort.","tgt":"Hati-hati, arusnya kuat.","lit":"attention · courant-[le] · fort"},{"fr":"J'ai besoin de crème solaire.","tgt":"Saya perlu tabir surya.","lit":"je · avoir besoin · écran · soleil"},{"fr":"Le coucher de soleil est magnifique.","tgt":"Matahari terbenamnya indah sekali.","lit":"soleil · se coucher-[le] · beau · très"},{"fr":"Je voudrais une noix de coco.","tgt":"Saya mau kelapa muda.","lit":"je · vouloir · coco · jeune"},{"fr":"Il y a de l'ombre là-bas.","tgt":"Di sana ada tempat teduh.","lit":"à · là-bas · il y a · lieu · ombragé"},{"fr":"J'ai pris un coup de soleil.","tgt":"Kulit saya terbakar matahari.","lit":"peau · je · brûlé · soleil"}]},{"title":"Louer un scooter","phrases":[{"fr":"Je voudrais louer un scooter.","tgt":"Saya mau sewa motor.","lit":"je · vouloir · louer · moto"},{"fr":"Vous savez conduire un scooter ?","tgt":"Anda bisa naik motor?","lit":"vous · pouvoir · monter · moto"},{"fr":"Oui, je sais conduire.","tgt":"Ya, saya bisa.","lit":"oui · je · pouvoir"},{"fr":"Je peux payer par carte ?","tgt":"Bisa bayar pakai kartu?","lit":"pouvoir · payer · utiliser · carte"},{"fr":"Je peux l'essayer un moment ?","tgt":"Boleh saya coba sebentar?","lit":"avoir le droit · je · essayer · un moment"},{"fr":"Vous parlez indonésien ?","tgt":"Anda bisa bahasa Indonesia?","lit":"vous · pouvoir · langue · Indonésie"},{"fr":"Je parle un peu indonésien.","tgt":"Saya bisa sedikit bahasa Indonesia.","lit":"je · pouvoir · un peu · langue · Indonésie"},{"fr":"On peut se garer ici ?","tgt":"Boleh parkir di sini?","lit":"avoir le droit · se garer · à · ici"},{"fr":"Non, ce n'est pas permis.","tgt":"Tidak boleh, Pak.","lit":"ne pas · avoir le droit · monsieur"},{"fr":"Je peux le garder jusqu'à demain ?","tgt":"Boleh sampai besok?","lit":"avoir le droit · jusqu'à · demain"}],"tip":{"title":"« Bisa » et « boleh » : pouvoir et avoir le droit","example":"Je peux l'essayer un moment ? — <b>Boleh</b> saya coba sebentar?","body":"Le français dit pouvoir pour deux idées différentes, et l'indonésien les sépare. « Bisa », c'est être capable, ou que c'est possible : « Saya bisa naik motor », je sais conduire un scooter. « Boleh », c'est avoir la permission : « Boleh saya coba ? », mot à mot permis moi essayer, est-ce que je peux l'essayer. On place ces mots juste avant le verbe, et pour poser la question, il suffit de monter la voix à la fin. Pour refuser poliment, on dit « tidak boleh », ce n'est pas permis, ou « tidak bisa », ce n'est pas possible. Au restaurant comme au marché, la question « Bisa bayar pakai kartu ? » vous servira souvent. Pour retenir : « bisa » pour la capacité, « boleh » pour l'autorisation, comme un panneau qui dit oui ou non.","lit":"avoir le droit · je · essayer · un moment","say":{"Bisa":"Bisa","boleh":"boleh","Saya bisa naik motor":"Saya bisa naik motor","Boleh":"Boleh","Boleh saya coba ?":"Boleh saya coba?","tidak boleh":"tidak boleh","tidak bisa":"tidak bisa","Bisa bayar pakai kartu ?":"Bisa bayar pakai kartu?","bisa":"bisa"}}},{"title":"Un petit souci de santé","phrases":[{"fr":"Est-ce qu'il y a une pharmacie dans le coin ?","tgt":"Ada apotek di dekat sini?","lit":"il y a · pharmacie · à · près · ici"},{"fr":"J'ai mal au ventre depuis hier soir.","tgt":"Perut saya sakit dari kemarin malam.","lit":"ventre · je · malade · depuis · hier · soir"},{"fr":"Je crois que j'ai un peu de fièvre.","tgt":"Sepertinya saya agak demam.","lit":"on dirait · je · un peu · fièvre"},{"fr":"Un moustique m'a piqué.","tgt":"Saya digigit nyamuk.","lit":"je · mordu · moustique"},{"fr":"Vous avez quelque chose contre le mal de tête ?","tgt":"Ada obat sakit kepala?","lit":"il y a · médicament · mal · tête"},{"fr":"Prenez ce médicament trois fois par jour.","tgt":"Minum obat ini tiga kali sehari.","lit":"boire · médicament · ceci · trois · fois · un-jour"},{"fr":"Après le repas, d'accord ?","tgt":"Sesudah makan, ya?","lit":"après · manger · oui"},{"fr":"J'ai besoin d'un médecin.","tgt":"Saya perlu dokter.","lit":"je · avoir besoin · médecin"},{"fr":"C'est grave ?","tgt":"Apakah ini serius?","lit":"[question] · ceci · grave"},{"fr":"Ne vous inquiétez pas, ce n'est rien.","tgt":"Jangan khawatir, tidak apa-apa.","lit":"ne pas (ordre) · inquiet · ne pas · quoi-quoi"}]},{"title":"Prendre l'ojek, le bus, le bateau","phrases":[{"fr":"Je prends l'ojek pour aller au marché.","tgt":"Saya naik ojek ke pasar.","lit":"je · monter · ojek · vers · marché"},{"fr":"Et si on prenait le bus ?","tgt":"Bagaimana kalau kita naik bus?","lit":"comment · si · nous · monter · bus"},{"fr":"Je prends le bateau pour Lombok.","tgt":"Saya naik kapal ke Lombok.","lit":"je · monter · bateau · vers · Lombok"},{"fr":"C'est plus rapide en ojek.","tgt":"Naik ojek lebih cepat.","lit":"monter · ojek · plus · rapide"},{"fr":"Je préfère y aller à pied.","tgt":"Saya jalan kaki saja.","lit":"je · marcher · pied · seulement"},{"fr":"Combien coûte l'ojek jusqu'à la plage ?","tgt":"Berapa naik ojek ke pantai?","lit":"combien · monter · ojek · vers · plage"},{"fr":"Mettez le casque, s'il vous plaît.","tgt":"Tolong pakai helm.","lit":"s'il vous plaît · porter · casque"},{"fr":"Je n'aime pas prendre l'avion.","tgt":"Saya tidak suka naik pesawat.","lit":"je · ne pas · aimer · monter · avion"},{"fr":"Je descends ici.","tgt":"Saya turun di sini.","lit":"je · descendre · à · ici"},{"fr":"On prend un taxi ou un ojek ?","tgt":"Naik taksi atau ojek?","lit":"monter · taxi · ou · ojek"}],"tip":{"title":"« Naik » + transport : prendre l'ojek, le bus, le bateau","example":"Je prends le bateau pour Lombok. — Saya <b>naik</b> kapal ke Lombok.","body":"« Naik » veut dire monter, et c'est le verbe qu'on utilise pour tous les transports. Là où le français dit prendre le bus, l'indonésien dit monter le bus : « naik bus ». « Saya naik kapal ke Lombok », mot à mot moi monter bateau vers Lombok, veut dire je prends le bateau pour Lombok. Ça marche avec tout : « naik ojek », la moto-taxi, « naik taksi », ou « naik pesawat », l'avion. Même conduire un scooter se dit « naik motor ». Pour descendre, on dit « turun » : « Saya turun di sini », je descends ici. Une seule exception : à pied se dit « jalan kaki », marcher pied, sans « naik ». Astuce : imaginez-vous en train d'enjamber la moto de l'ojek, vous montez, donc « naik ».","lit":"je · monter · bateau · vers · Lombok","say":{"Naik":"Naik","naik bus":"naik bus","Saya naik kapal ke Lombok":"Saya naik kapal ke Lombok","naik ojek":"naik ojek","naik taksi":"naik taksi","naik pesawat":"naik pesawat","naik motor":"naik motor","turun":"turun","Saya turun di sini":"Saya turun di sini","jalan kaki":"jalan kaki","naik":"naik"}}},{"title":"Une excursion aux îles Gili","phrases":[{"fr":"Les îles Gili sont près de Lombok.","tgt":"Pulau Gili dekat Lombok.","lit":"île · Gili · près · Lombok"},{"fr":"Sur l'île, il n'y a aucune voiture.","tgt":"Di pulau itu tidak ada mobil.","lit":"à · île · cela · ne pas · il y a · voiture"},{"fr":"On loue des vélos.","tgt":"Kita sewa sepeda.","lit":"nous · louer · vélo"},{"fr":"L'eau est très claire.","tgt":"Airnya jernih sekali.","lit":"eau-[la] · limpide · très"},{"fr":"Je veux voir les poissons dans la mer.","tgt":"Saya mau lihat ikan di laut.","lit":"je · vouloir · voir · poisson · à · mer"},{"fr":"J'ai vu une tortue !","tgt":"Saya lihat penyu!","lit":"je · voir · tortue de mer"},{"fr":"Le bateau part à dix heures.","tgt":"Kapalnya berangkat jam sepuluh.","lit":"bateau-[le] · partir · heure · dix"},{"fr":"La mer est agitée aujourd'hui.","tgt":"Lautnya berombak hari ini.","lit":"mer-[la] · avoir des vagues · jour · ceci"},{"fr":"J'ai le mal de mer.","tgt":"Saya mabuk laut.","lit":"je · ivre · mer"},{"fr":"Quelle belle journée !","tgt":"Hari yang indah sekali!","lit":"jour · qui · beau · très"}]},{"title":"Loin ou près ?","phrases":[{"fr":"C'est loin d'ici ?","tgt":"Jauh dari sini?","lit":"loin · de · ici"},{"fr":"Non, c'est tout près.","tgt":"Tidak, dekat sekali.","lit":"non · près · très"},{"fr":"La plage est près de l'hôtel.","tgt":"Pantainya dekat hotel.","lit":"plage-[la] · près · hôtel"},{"fr":"L'aéroport est loin d'Ubud.","tgt":"Bandara jauh dari Ubud.","lit":"aéroport · loin · de · Ubud"},{"fr":"Le marché est tout près, à cinq minutes.","tgt":"Pasarnya dekat, lima menit saja.","lit":"marché-[le] · près · cinq · minute · seulement"},{"fr":"C'est trop loin à pied.","tgt":"Terlalu jauh kalau jalan kaki.","lit":"trop · loin · si · marcher · pied"},{"fr":"Est-ce qu'il y a un warung par ici ?","tgt":"Ada warung dekat sini?","lit":"il y a · warung · près · ici"},{"fr":"Komodo, c'est loin de Bali ?","tgt":"Komodo jauh dari Bali?","lit":"Komodo · loin · de · Bali"},{"fr":"Pas très loin, une heure d'avion.","tgt":"Tidak terlalu jauh, satu jam naik pesawat.","lit":"ne pas · trop · loin · un · heure · monter · avion"},{"fr":"Mon hôtel est près de la mer.","tgt":"Hotel saya dekat laut.","lit":"hôtel · je · près · mer"}],"tip":{"title":"« Jauh » et « dekat » : loin et près","example":"C'est loin d'ici ? — <b>Jauh</b> dari sini?","body":"« Jauh » veut dire loin et « dekat » veut dire près. Ce sont des adjectifs, donc pas besoin de verbe être : « Jauh dari sini ? », mot à mot loin de ici, veut dire c'est loin d'ici. Avec « dari », on indique le point de comparaison : « Bandara jauh dari Ubud », l'aéroport est loin d'Ubud. Avec « dekat », on peut dire directement « dekat hotel », près de l'hôtel. Pour nuancer, ajoutez « sekali », très, après le mot : « dekat sekali », tout près, ou « terlalu », trop, avant : « terlalu jauh », trop loin. Le petit « h » final de « jauh » se souffle à peine, comme un soupir. Astuce : un trajet trop long fait soupirer, « jauh », alors qu'un endroit proche est net et court, « dekat ».","lit":"loin · de · ici","say":{"Jauh":"Jauh","dekat":"dekat","Jauh dari sini ?":"Jauh dari sini?","dari":"dari","Bandara jauh dari Ubud":"Bandara jauh dari Ubud","dekat hotel":"dekat hotel","sekali":"sekali","dekat sekali":"dekat sekali","terlalu":"terlalu","terlalu jauh":"terlalu jauh","jauh":"jauh"}}},{"title":"Un vol retardé","phrases":[{"fr":"Mon avion a du retard.","tgt":"Pesawat saya terlambat.","lit":"avion · je · en retard"},{"fr":"Le vol est annulé ?","tgt":"Pesawatnya batal?","lit":"avion-[le] · annulé"},{"fr":"À quelle heure part l'avion ?","tgt":"Pesawatnya berangkat jam berapa?","lit":"avion-[le] · partir · heure · combien"},{"fr":"Où est la porte sept ?","tgt":"Pintu tujuh di mana?","lit":"porte · sept · à · où"},{"fr":"Je dois attendre deux heures.","tgt":"Saya harus tunggu dua jam.","lit":"je · devoir · attendre · deux · heure"},{"fr":"Il y a un café dans l'aéroport ?","tgt":"Ada kafe di bandara?","lit":"il y a · café · à · aéroport"},{"fr":"Je rentre en France demain.","tgt":"Saya pulang ke Prancis besok.","lit":"je · rentrer · vers · France · demain"},{"fr":"Ma valise est trop lourde.","tgt":"Koper saya terlalu berat.","lit":"valise · je · trop · lourd"},{"fr":"Je voudrais une place près du hublot.","tgt":"Saya mau duduk dekat jendela.","lit":"je · vouloir · s'asseoir · près · fenêtre"},{"fr":"Enfin, on embarque !","tgt":"Akhirnya, kita naik pesawat!","lit":"enfin · nous · monter · avion"}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Je suis déjà allé à Bali.","tgt":"Saya pernah ke Bali.","lit":"je · [expérience] · vers · Bali"},{"fr":"Vous êtes déjà allé à Lombok ?","tgt":"Anda pernah ke Lombok?","lit":"vous · [expérience] · vers · Lombok"},{"fr":"Je ne suis jamais allé à Komodo.","tgt":"Saya belum pernah ke Komodo.","lit":"je · pas encore · [expérience] · vers · Komodo"},{"fr":"J'ai déjà goûté le durian.","tgt":"Saya pernah makan durian.","lit":"je · [expérience] · manger · durian"},{"fr":"Vous avez déjà pris l'ojek ?","tgt":"Anda pernah naik ojek?","lit":"vous · [expérience] · monter · ojek"},{"fr":"Je n'ai encore jamais conduit de scooter.","tgt":"Saya belum pernah naik motor.","lit":"je · pas encore · [expérience] · monter · moto"},{"fr":"J'ai appris beaucoup de mots d'indonésien.","tgt":"Saya sudah belajar banyak kata bahasa Indonesia.","lit":"je · [accompli] · apprendre · beaucoup · mot · langue · Indonésie"},{"fr":"Je sais demander un prix et mon chemin.","tgt":"Saya bisa tanya harga dan jalan.","lit":"je · pouvoir · demander · prix · et · chemin"},{"fr":"Je veux revenir à Bali l'année prochaine.","tgt":"Saya mau kembali ke Bali tahun depan.","lit":"je · vouloir · revenir · vers · Bali · année · devant"},{"fr":"Au revoir, Bali !","tgt":"Selamat tinggal, Bali!","lit":"bon · rester · Bali"}],"tip":{"title":"« Pernah » : l'expérience, j'y suis déjà allé","example":"Vous êtes déjà allé à Lombok ? — Anda <b>pernah</b> ke Lombok?","body":"« Pernah » sert à parler de l'expérience, de ce qu'on a déjà fait au moins une fois dans sa vie. « Saya pernah ke Bali », mot à mot moi expérience vers Bali, veut dire je suis déjà allé à Bali. À la différence de « sudah », qui dit qu'une action est terminée, « pernah » dit que vous l'avez vécue. On le place juste devant le verbe, et pour la question, on monte simplement la voix : « Anda pernah naik ojek ? », vous avez déjà pris l'ojek. Pour dire jamais, on dit « belum pernah », pas encore d'expérience, ce qui laisse la porte ouverte : « Saya belum pernah ke Komodo ». On peut aussi dire « tidak pernah », plus définitif. Astuce : à la fin de ce module, vous pourrez dire fièrement « Saya pernah ke Bali », et en indonésien en plus.","lit":"vous · [expérience] · vers · Lombok","say":{"Pernah":"Pernah","Saya pernah ke Bali":"Saya pernah ke Bali","sudah":"sudah","pernah":"pernah","Anda pernah naik ojek ?":"Anda pernah naik ojek?","belum pernah":"belum pernah","Saya belum pernah ke Komodo":"Saya belum pernah ke Komodo","tidak pernah":"tidak pernah"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Se présenter entre amis","phrases":[{"fr":"Salut, moi c'est Rina.","tgt":"Hai, namaku Rina.","lit":"salut · nom-moi · Rina"},{"fr":"Et toi, c'est quoi ton prénom ?","tgt":"Kalau kamu, siapa namamu?","lit":"si · toi · qui · nom-toi"},{"fr":"Je suis étudiante à Yogyakarta.","tgt":"Aku mahasiswi di Yogyakarta.","lit":"je · étudiante · à · Yogyakarta"},{"fr":"Je viens de France, de Lyon.","tgt":"Aku dari Prancis, dari Lyon.","lit":"je · de · France · de · Lyon"},{"fr":"Et toi, tu habites où à Yogya ?","tgt":"Kamu tinggal di mana di Yogya?","lit":"toi · habiter · à · où · à · Yogya"},{"fr":"J'habite tout près de Malioboro.","tgt":"Aku tinggal dekat Malioboro.","lit":"je · habiter · près · Malioboro"},{"fr":"Tu as quel âge, toi ?","tgt":"Umur kamu berapa?","lit":"âge · toi · combien"},{"fr":"Moi, j'ai vingt-deux ans.","tgt":"Umurku dua puluh dua tahun.","lit":"âge-moi · deux · dizaine · deux · an"},{"fr":"Contente de faire ta connaissance !","tgt":"Senang kenalan dengan kamu!","lit":"content · faire connaissance · avec · toi"},{"fr":"Moi aussi, je suis ravi.","tgt":"Aku juga senang.","lit":"je · aussi · content"}]},{"title":"Tutoyer un nouvel ami","phrases":[{"fr":"Tu es étudiant, toi aussi ?","tgt":"Kamu mahasiswa juga?","lit":"toi · étudiant · aussi"},{"fr":"Oui, je suis étudiant en deuxième année.","tgt":"Iya, aku mahasiswa tahun kedua.","lit":"oui · je · étudiant · année · deuxième"},{"fr":"Tu étudies quoi, à la fac ?","tgt":"Kamu kuliah jurusan apa?","lit":"toi · étudier · filière · quoi"},{"fr":"Moi, j'apprends l'indonésien.","tgt":"Aku belajar bahasa Indonesia.","lit":"je · apprendre · langue · Indonésie"},{"fr":"Il est bon, ton indonésien !","tgt":"Bahasa Indonesia kamu bagus!","lit":"langue · Indonésie · toi · bon"},{"fr":"Merci, tu es sympa.","tgt":"Makasih, kamu baik.","lit":"merci · toi · gentil"},{"fr":"Entre nous, on dit « aku » et « kamu », d'accord ?","tgt":"Kita pakai aku dan kamu, ya?","lit":"nous · utiliser · aku · et · kamu · hein"},{"fr":"Bien sûr, on est copains maintenant.","tgt":"Tentu, sekarang kita teman.","lit":"bien sûr · maintenant · nous · ami"},{"fr":"Tu me donnes ton numéro ?","tgt":"Boleh minta nomor kamu?","lit":"pouvoir · demander · numéro · toi"},{"fr":"Je t'appelle ce soir, alors.","tgt":"Nanti malam aku telepon kamu.","lit":"tout à l'heure · soir · je · téléphoner · toi"}],"tip":{"title":"« Aku » et « kamu » : se tutoyer entre amis","example":"Je t'appelle ce soir, alors. — Nanti malam <b>aku</b> telepon <b>kamu</b>.","body":"Jusqu'ici, vous disiez « saya » pour je et « Anda » pour vous : c'est la façon polie de parler. Entre amis, les Indonésiens passent à « aku », qui veut dire je ou moi, et à « kamu », qui veut dire tu ou toi. C'est exactement comme le passage du vous au tu en français. Prenez « Nanti malam aku telepon kamu » : mot à mot, tout à l'heure, soir, je, téléphoner, toi. Le verbe ne change pas, seuls les pronoms deviennent familiers. On dit par exemple « aku capek », je suis fatigué, ou « kamu mau ke mana », tu vas où. Pour dire mon ou ton, on colle souvent un petit son à la fin du mot : « namaku », mon nom, et « namamu », ton nom. Petite astuce pour retenir : « aku » et « kamu » finissent tous les deux par un « ou » bien rond, comme deux amis qui se répondent. Gardez quand même « saya » avec les personnes plus âgées ou que vous ne connaissez pas.","lit":"tout à l'heure · soir · je · téléphoner · toi","say":{"Aku":"Aku","kamu":"kamu","saya":"saya","Anda":"Anda","aku":"aku","Nanti malam aku telepon kamu":"Nanti malam aku telepon kamu","aku capek":"aku capek","kamu mau ke mana":"kamu mau ke mana","namaku":"namaku","namamu":"namamu"}}},{"title":"La vie étudiante à Yogyakarta","phrases":[{"fr":"Mon campus est immense.","tgt":"Kampusku besar sekali.","lit":"campus-moi · grand · très"},{"fr":"Les cours commencent à huit heures.","tgt":"Kuliahnya mulai jam delapan.","lit":"cours-[le] · commencer · heure · huit"},{"fr":"Aujourd'hui, je n'ai pas cours.","tgt":"Hari ini aku tidak ada kuliah.","lit":"jour · ce · je · ne pas · il y a · cours"},{"fr":"Notre prof est sympa.","tgt":"Dosen kami baik.","lit":"professeur · nous · gentil"},{"fr":"Il y a plein d'étudiants dans ce quartier.","tgt":"Di daerah ini ada banyak mahasiswa.","lit":"à · quartier · ce · il y a · beaucoup · étudiant"},{"fr":"Tu as fini ton devoir ?","tgt":"Tugasmu sudah selesai?","lit":"devoir-toi · [accompli] · fini"},{"fr":"Pas encore, il est difficile.","tgt":"Belum, tugasnya susah.","lit":"pas encore · devoir-[le] · difficile"},{"fr":"Allez, on révise ensemble à la bibliothèque !","tgt":"Yuk, belajar bareng di perpustakaan!","lit":"allez · étudier · ensemble · à · bibliothèque"},{"fr":"Mon copain étudie la musique.","tgt":"Temanku kuliah musik.","lit":"ami-moi · étudier · musique"},{"fr":"Yogyakarta, c'est la ville des étudiants.","tgt":"Yogyakarta itu kota pelajar.","lit":"Yogyakarta · ça · ville · étudiant"}]},{"title":"Parler de ses loisirs","phrases":[{"fr":"Moi, j'aime lire des romans.","tgt":"Aku suka baca novel.","lit":"je · aimer · lire · roman"},{"fr":"Et toi, tu aimes la musique ?","tgt":"Kamu suka musik?","lit":"toi · aimer · musique"},{"fr":"Oui, j'aime le gamelan.","tgt":"Iya, aku suka gamelan.","lit":"oui · je · aimer · gamelan"},{"fr":"Le football, ça ne me plaît pas.","tgt":"Aku tidak suka sepak bola.","lit":"je · ne pas · aimer · football"},{"fr":"C'est quoi, ton passe-temps ?","tgt":"Hobi kamu apa?","lit":"passe-temps · toi · quoi"},{"fr":"Moi, mon passe-temps, c'est la photo.","tgt":"Hobiku fotografi.","lit":"passe-temps-moi · photographie"},{"fr":"J'aime nager tôt le matin.","tgt":"Aku suka berenang pagi-pagi.","lit":"je · aimer · nager · tôt le matin"},{"fr":"Mon ami Andi aime jouer de la guitare.","tgt":"Temanku Andi suka main gitar.","lit":"ami-moi · Andi · aimer · jouer · guitare"},{"fr":"Ça te plaît, de danser ?","tgt":"Kamu suka menari?","lit":"toi · aimer · danser"},{"fr":"Pas trop, je préfère chanter.","tgt":"Tidak terlalu, aku lebih suka menyanyi.","lit":"ne pas · trop · je · plus · aimer · chanter"}],"tip":{"title":"« Suka » : aimer","example":"Et toi, tu aimes la musique ? — Kamu <b>suka</b> musik?","body":"Pour dire ce que vous aimez, il suffit d'un petit mot : « suka », qui veut dire aimer, apprécier. On le place juste après la personne, puis on ajoute la chose ou l'activité. Par exemple « Kamu suka musik », mot à mot toi, aimer, musique, veut dire tu aimes la musique. Pas besoin d'article, pas de conjugaison : « aku suka », « kamu suka », « kami suka », c'est toujours la même forme. Pour une activité, on met simplement le verbe derrière : « aku suka berenang », j'aime nager. Pour dire que vous n'aimez pas, ajoutez « tidak » devant : « aku tidak suka kopi », je n'aime pas le café. Et pour dire que vous préférez, dites « lebih suka », mot à mot plus aimer. Astuce : « suka » ressemble au mot sucre, et ce qu'on aime, c'est toujours un peu sucré.","lit":"toi · aimer · musique","say":{"Suka":"Suka","suka":"suka","Kamu suka musik":"Kamu suka musik","aku suka":"aku suka","kamu suka":"kamu suka","kami suka":"kami suka","aku suka berenang":"aku suka berenang","tidak":"tidak","aku tidak suka kopi":"aku tidak suka kopi","lebih suka":"lebih suka"}}},{"title":"Le café du soir","phrases":[{"fr":"Ce soir, on va au café, ça te dit ?","tgt":"Nanti malam kita ke kafe, yuk?","lit":"tout à l'heure · soir · nous · vers · café · allez"},{"fr":"Il y a un café sympa près du campus.","tgt":"Ada kafe enak dekat kampus.","lit":"il y a · café · agréable · près · campus"},{"fr":"Moi, je prends un café au lait.","tgt":"Aku pesan kopi susu.","lit":"je · commander · café · lait"},{"fr":"Tu veux un thé glacé ?","tgt":"Kamu mau es teh?","lit":"toi · vouloir · glace · thé"},{"fr":"Non merci, je prends un jus d'avocat.","tgt":"Tidak, makasih. Aku pesan jus alpukat.","lit":"non · merci · je · commander · jus · avocat"},{"fr":"Le café d'ici est bon et pas cher.","tgt":"Kopi di sini enak dan murah.","lit":"café · à · ici · bon · et · bon marché"},{"fr":"On s'installe dehors ?","tgt":"Kita duduk di luar, ya?","lit":"nous · s'asseoir · à · dehors · hein"},{"fr":"Ce soir, il y a un petit concert.","tgt":"Malam ini ada pertunjukan musik.","lit":"soir · ce · il y a · spectacle · musique"},{"fr":"Ce soir, c'est moi qui paie.","tgt":"Malam ini aku yang bayar.","lit":"soir · ce · je · celui qui · payer"},{"fr":"Merci, la prochaine fois, c'est mon tour.","tgt":"Makasih, lain kali giliranku.","lit":"merci · autre · fois · tour-moi"}]},{"title":"Parler de sa famille","phrases":[{"fr":"Mon père est instituteur.","tgt":"Bapakku guru.","lit":"père-moi · enseignant"},{"fr":"Ma mère travaille à l'hôpital.","tgt":"Ibuku kerja di rumah sakit.","lit":"mère-moi · travailler · à · maison · malade"},{"fr":"J'ai une grande sœur et un petit frère.","tgt":"Aku punya kakak perempuan dan adik laki-laki.","lit":"je · avoir · aîné · femme · et · cadet · homme"},{"fr":"Ma grande sœur vit à Bandung.","tgt":"Kakakku tinggal di Bandung.","lit":"aîné-moi · habiter · à · Bandung"},{"fr":"Mon petit frère va encore à l'école.","tgt":"Adikku masih sekolah.","lit":"cadet-moi · encore · école"},{"fr":"Et toi, tu as des frères et sœurs ?","tgt":"Kamu punya saudara?","lit":"toi · avoir · frère ou sœur"},{"fr":"Oui, j'ai un grand frère.","tgt":"Iya, aku punya kakak laki-laki.","lit":"oui · je · avoir · aîné · homme"},{"fr":"Ils habitent où, tes parents ?","tgt":"Orang tuamu tinggal di mana?","lit":"parents-toi · habiter · à · où"},{"fr":"Ils vivent à Yogyakarta avec ma petite sœur.","tgt":"Mereka tinggal di Yogyakarta dengan adikku.","lit":"ils · habiter · à · Yogyakarta · avec · cadet-moi"},{"fr":"Bonjour Monsieur, je suis un ami de Dewi.","tgt":"Selamat siang, Pak. Saya teman Dewi.","lit":"bon · midi · monsieur · je · ami · Dewi"}],"tip":{"title":"La famille : « bapak », « ibu », « kakak », « adik »","example":"J'ai une grande sœur et un petit frère. — Aku punya <b>kakak</b> perempuan dan <b>adik</b> laki-laki.","body":"En indonésien, la famille se dit avec quelques mots très courts. « Bapak » veut dire père, et « ibu » veut dire mère. Ce qui surprend, c'est que pour les frères et sœurs, on ne dit pas d'abord garçon ou fille, mais plus âgé ou plus jeune : « kakak », c'est l'aîné, et « adik », c'est le cadet. Pour préciser, on ajoute « laki-laki », homme, ou « perempuan », femme. Ainsi « kakak perempuan », mot à mot aîné femme, veut dire grande sœur, et « adik laki-laki » veut dire petit frère. Pour dire mon père, collez « ku » à la fin : « bapakku ». Autre détail très utile à l'oral : ces mots servent aussi à s'adresser poliment aux gens. On dit « Pak » à un monsieur et « Bu » à une dame, par exemple « terima kasih, Bu », merci Madame. Astuce : « kakak » se répète comme un grand qui parle fort, et « adik » est plus court, comme le petit dernier.","lit":"je · avoir · aîné · femme · et · cadet · homme","say":{"bapak":"bapak","ibu":"ibu","kakak":"kakak","adik":"adik","Bapak":"Bapak","laki-laki":"laki-laki","perempuan":"perempuan","kakak perempuan":"kakak perempuan","adik laki-laki":"adik laki-laki","bapakku":"bapakku","Pak":"Pak","Bu":"Bu","terima kasih, Bu":"terima kasih, Bu","ku":"ku"}}},{"title":"Le temps qu'il fait à Yogya","phrases":[{"fr":"Il fait chaud à Yogya aujourd'hui, hein.","tgt":"Hari ini Yogya panas, ya.","lit":"jour · ce · Yogya · chaud · hein"},{"fr":"Il pleuvra peut-être cet après-midi.","tgt":"Sore ini mungkin hujan.","lit":"après-midi · ce · peut-être · pluie"},{"fr":"Tu as pris ton parapluie ?","tgt":"Kamu bawa payung?","lit":"toi · apporter · parapluie"},{"fr":"En ce moment, c'est la saison des pluies.","tgt":"Sekarang musim hujan.","lit":"maintenant · saison · pluie"},{"fr":"En janvier, il pleut beaucoup ici.","tgt":"Bulan Januari di sini banyak hujan.","lit":"mois · janvier · à · ici · beaucoup · pluie"},{"fr":"Tôt le matin, l'air est frais.","tgt":"Pagi-pagi udaranya sejuk.","lit":"tôt le matin · air-[le] · frais"},{"fr":"J'aime bien la pluie le soir.","tgt":"Aku suka hujan di malam hari.","lit":"je · aimer · pluie · à · nuit · jour"},{"fr":"La pluie s'est arrêtée.","tgt":"Hujannya sudah berhenti.","lit":"pluie-[la] · [accompli] · s'arrêter"},{"fr":"Maintenant, le ciel est tout bleu.","tgt":"Sekarang langitnya biru.","lit":"maintenant · ciel-[le] · bleu"},{"fr":"Alors, on peut sortir !","tgt":"Kalau begitu, kita bisa keluar!","lit":"si · ainsi · nous · pouvoir · sortir"}]},{"title":"Un coup de fil à un ami","phrases":[{"fr":"Allô, tu es où, là ?","tgt":"Halo, kamu di mana?","lit":"allô · toi · à · où"},{"fr":"Je suis en train de manger au warung.","tgt":"Aku sedang makan di warung.","lit":"je · [en cours] · manger · à · warung"},{"fr":"Et toi, tu fais quoi en ce moment ?","tgt":"Kamu sedang apa?","lit":"toi · [en cours] · quoi"},{"fr":"Là, je suis en train de réviser.","tgt":"Aku sedang belajar.","lit":"je · [en cours] · étudier"},{"fr":"Budi est en train de dormir.","tgt":"Budi sedang tidur.","lit":"Budi · [en cours] · dormir"},{"fr":"Ma mère est en train de faire la cuisine.","tgt":"Ibuku sedang masak.","lit":"mère-moi · [en cours] · cuisiner"},{"fr":"Tu es occupé, là ?","tgt":"Kamu sedang sibuk?","lit":"toi · [en cours] · occupé"},{"fr":"Non, je regarde juste la télé.","tgt":"Tidak, aku cuma sedang nonton televisi.","lit":"non · je · seulement · [en cours] · regarder · télévision"},{"fr":"Je te rappelle un peu plus tard.","tgt":"Nanti aku telepon lagi.","lit":"tout à l'heure · je · téléphoner · encore"},{"fr":"D'accord, à plus tard !","tgt":"Oke, sampai nanti!","lit":"d'accord · jusqu'à · plus tard"}],"tip":{"title":"« Sedang » : être en train de","example":"Je suis en train de manger au warung. — Aku <b>sedang</b> makan di warung.","body":"Le verbe indonésien ne change jamais, alors comment dire qu'une action est en cours ? Avec un petit mot posé juste devant le verbe : « sedang », qui veut dire être en train de. « Aku sedang makan », mot à mot je, en cours, manger, veut dire je suis en train de manger. C'est très proche du français : on ajoute simplement un mot, sans rien toucher au reste. On dit « dia sedang tidur », il est en train de dormir, ou « kami sedang belajar », nous sommes en train d'étudier. La question « kamu sedang apa ? », mot à mot toi, en cours, quoi, veut dire qu'est-ce que tu fais en ce moment, et on l'entend sans arrêt au téléphone. Entre amis, vous entendrez aussi « lagi » à la place de « sedang », avec exactement le même sens. Astuce : « sedang » commence comme le mot seconde, et une action en cours se passe à la seconde même.","lit":"je · [en cours] · manger · à · warung","say":{"Sedang":"Sedang","sedang":"sedang","Aku sedang makan":"Aku sedang makan","dia sedang tidur":"dia sedang tidur","kami sedang belajar":"kami sedang belajar","kamu sedang apa ?":"kamu sedang apa?","lagi":"lagi"}}},{"title":"Le gudeg au warung","phrases":[{"fr":"Tu as déjà goûté le gudeg ?","tgt":"Kamu sudah pernah coba gudeg?","lit":"toi · [accompli] · [déjà vécu] · goûter · gudeg"},{"fr":"Pas encore, qu'est-ce que c'est ?","tgt":"Belum. Itu apa?","lit":"pas encore · ça · quoi"},{"fr":"C'est un plat à base de jacquier.","tgt":"Itu masakan dari nangka.","lit":"ça · plat · de · jacquier"},{"fr":"Le gudeg, c'est un peu sucré.","tgt":"Gudeg agak manis.","lit":"gudeg · un peu · sucré"},{"fr":"Allez, on mange du gudeg ce midi ?","tgt":"Siang ini kita makan gudeg, yuk?","lit":"midi · ce · nous · manger · gudeg · allez"},{"fr":"Le warung de Madame Sri est réputé.","tgt":"Warung Bu Sri terkenal.","lit":"warung · madame · Sri · célèbre"},{"fr":"Un gudeg avec un œuf, s'il vous plaît, Madame.","tgt":"Gudeg satu, pakai telur, ya, Bu.","lit":"gudeg · un · avec · œuf · hein · madame"},{"fr":"Et un thé chaud, aussi.","tgt":"Teh panas satu juga, Bu.","lit":"thé · chaud · un · aussi · madame"},{"fr":"Waouh, c'est délicieux !","tgt":"Wah, enak!","lit":"oh · délicieux"},{"fr":"Ça fait combien en tout, Madame ?","tgt":"Semuanya berapa, Bu?","lit":"tout-[le] · combien · madame"}]},{"title":"Comparer entre amis","phrases":[{"fr":"Le gudeg est plus sucré que les brochettes.","tgt":"Gudeg lebih manis dari sate.","lit":"gudeg · plus · sucré · que · sate"},{"fr":"Yogyakarta est plus calme que Jakarta.","tgt":"Yogyakarta lebih tenang dari Jakarta.","lit":"Yogyakarta · plus · calme · que · Jakarta"},{"fr":"Jakarta est plus grande que Yogya.","tgt":"Jakarta lebih besar dari Yogya.","lit":"Jakarta · plus · grand · que · Yogya"},{"fr":"Ma grande sœur est plus grande que moi.","tgt":"Kakakku lebih tinggi dari aku.","lit":"aîné-moi · plus · haut · que · moi"},{"fr":"Pour aller à Jakarta, le train est plus rapide que le bus.","tgt":"Ke Jakarta, kereta lebih cepat dari bus.","lit":"vers · Jakarta · train · plus · rapide · que · bus"},{"fr":"Ici, c'est moins cher qu'à Bali.","tgt":"Di sini lebih murah dari Bali.","lit":"à · ici · plus · bon marché · que · Bali"},{"fr":"Le café est plus amer que le thé.","tgt":"Kopi lebih pahit dari teh.","lit":"café · plus · amer · que · thé"},{"fr":"À Yogya, il fait plus chaud aujourd'hui qu'hier.","tgt":"Hari ini Yogya lebih panas dari kemarin.","lit":"jour · ce · Yogya · plus · chaud · que · hier"},{"fr":"Lequel est le meilleur, à ton avis ?","tgt":"Menurutmu, mana yang lebih enak?","lit":"selon-toi · lequel · celui qui · plus · bon"},{"fr":"Pour moi, les brochettes sont meilleures.","tgt":"Menurutku, sate lebih enak.","lit":"selon-moi · sate · plus · bon"}],"tip":{"title":"Comparer avec « lebih... dari »","example":"Yogyakarta est plus calme que Jakarta. — Yogyakarta <b>lebih</b> tenang <b>dari</b> Jakarta.","body":"Pour comparer deux choses, l'indonésien suit presque exactement l'ordre du français. On dit d'abord la première chose, puis « lebih », qui veut dire plus, puis l'adjectif, puis « dari », qui veut dire que, et enfin la deuxième chose. « Yogyakarta lebih tenang dari Jakarta », mot à mot Yogyakarta, plus, calme, que, Jakarta. Il n'y a pas de verbe être à ajouter, ni d'accord à faire. On dit par exemple « kopi lebih pahit dari teh », le café est plus amer que le thé, ou « hari ini lebih panas », aujourd'hui il fait plus chaud. Pour dire moins cher, on dit souvent tout simplement plus bon marché : « lebih murah ». Et pour dire meilleur en parlant de nourriture, on dit « lebih enak », plus délicieux. Astuce : « dari » veut aussi dire de, comme dans « aku dari Prancis », alors imaginez que vous partez de la deuxième chose pour mesurer la première.","lit":"Yogyakarta · plus · calme · que · Jakarta","say":{"lebih... dari":"lebih... dari","lebih":"lebih","dari":"dari","Yogyakarta lebih tenang dari Jakarta":"Yogyakarta lebih tenang dari Jakarta","kopi lebih pahit dari teh":"kopi lebih pahit dari teh","hari ini lebih panas":"hari ini lebih panas","lebih murah":"lebih murah","lebih enak":"lebih enak","aku dari Prancis":"aku dari Prancis"}}},{"title":"Les brochettes au warung","phrases":[{"fr":"Ce soir, on mange des brochettes !","tgt":"Malam ini makan sate, yuk!","lit":"soir · ce · manger · sate · allez"},{"fr":"J'adore les brochettes de poulet.","tgt":"Aku suka sate ayam.","lit":"je · aimer · sate · poulet"},{"fr":"Tu en veux combien, de brochettes ?","tgt":"Kamu mau sate berapa tusuk?","lit":"toi · vouloir · sate · combien · [classificateur]"},{"fr":"Dix brochettes, s'il vous plaît, Monsieur.","tgt":"Sate sepuluh tusuk, ya, Pak.","lit":"sate · dix · [classificateur] · hein · monsieur"},{"fr":"Avec du riz ou du lontong ?","tgt":"Pakai nasi atau lontong?","lit":"avec · riz · ou · lontong"},{"fr":"Juste du lontong, merci.","tgt":"Lontong saja, makasih.","lit":"lontong · seulement · merci"},{"fr":"La sauce aux cacahuètes est bonne.","tgt":"Bumbu kacangnya enak.","lit":"sauce · cacahuète-[la] · bon"},{"fr":"Dis, c'est pimenté, ça ?","tgt":"Ini pedas, tidak?","lit":"ceci · pimenté · non"},{"fr":"Un peu, mais c'est bon.","tgt":"Sedikit, tapi enak.","lit":"un peu · mais · bon"},{"fr":"J'en veux encore cinq.","tgt":"Aku mau tambah lima tusuk lagi.","lit":"je · vouloir · ajouter · cinq · [classificateur] · encore"}]},{"title":"Donner ses raisons","phrases":[{"fr":"Je suis fatigué parce que j'ai beaucoup étudié.","tgt":"Aku capek karena banyak belajar.","lit":"je · fatigué · parce que · beaucoup · étudier"},{"fr":"Je ne viens pas ce soir, parce que je suis malade.","tgt":"Nanti malam aku tidak datang karena sakit.","lit":"tout à l'heure · soir · je · ne pas · venir · parce que · malade"},{"fr":"Il pleut, donc on reste à la maison.","tgt":"Hujan, jadi kita di rumah saja.","lit":"pluie · donc · nous · à · maison · seulement"},{"fr":"J'ai faim, donc je vais au warung.","tgt":"Aku lapar, jadi aku ke warung.","lit":"je · faim · donc · je · vers · warung"},{"fr":"Pourquoi tu arrives en retard ?","tgt":"Kenapa kamu terlambat?","lit":"pourquoi · toi · en retard"},{"fr":"Parce que ça bouchonnait.","tgt":"Karena macet.","lit":"parce que · embouteillé"},{"fr":"J'aime Yogya parce que les gens sont aimables.","tgt":"Aku suka Yogya karena orangnya ramah.","lit":"je · aimer · Yogya · parce que · gens-[les] · aimable"},{"fr":"Le café est fermé, donc on va ailleurs.","tgt":"Kafenya tutup, jadi kita pergi ke tempat lain.","lit":"café-[le] · fermé · donc · nous · aller · vers · endroit · autre"},{"fr":"Ce n'est pas cher, donc j'en prends deux.","tgt":"Murah, jadi aku beli dua.","lit":"bon marché · donc · je · acheter · deux"},{"fr":"Je ne rentre pas encore, parce que c'est amusant.","tgt":"Aku belum mau pulang karena seru.","lit":"je · pas encore · vouloir · rentrer · parce que · amusant"}],"tip":{"title":"« Karena » et « jadi » : parce que, donc","example":"J'aime Yogya parce que les gens sont aimables. — Aku suka Yogya <b>karena</b> orangnya ramah.","body":"Pour expliquer une raison, l'indonésien utilise « karena », qui veut dire parce que. Pour donner une conséquence, il utilise « jadi », qui veut dire donc. Les deux se placent exactement comme en français, au milieu de la phrase. « Aku suka Yogya karena orangnya ramah », mot à mot je, aimer, Yogya, parce que, gens, aimable : j'aime Yogya parce que les gens sont aimables. Dans l'autre sens, « hujan, jadi kita di rumah saja » veut dire il pleut, donc on reste à la maison. Pour répondre à la question « kenapa », pourquoi, on peut commencer directement par « karena » : « karena macet », parce que ça bouchonnait. Notez qu'on n'a même pas besoin de répéter je : « aku capek karena banyak belajar » suffit. Astuce : « jadi » sonne un peu comme j'ai dit, et c'est bien ce qu'on dit avant de conclure.","lit":"je · aimer · Yogya · parce que · gens-[les] · aimable","say":{"Karena":"Karena","jadi":"jadi","karena":"karena","Aku suka Yogya karena orangnya ramah":"Aku suka Yogya karena orangnya ramah","hujan, jadi kita di rumah saja":"hujan, jadi kita di rumah saja","kenapa":"kenapa","karena macet":"karena macet","aku capek karena banyak belajar":"aku capek karena banyak belajar"}}},{"title":"Musique et cinéma","phrases":[{"fr":"Tu as vu ce film-là ?","tgt":"Kamu sudah nonton film itu?","lit":"toi · [accompli] · regarder · film · ce"},{"fr":"Oui, il est vraiment bien.","tgt":"Sudah, filmnya bagus.","lit":"[accompli] · film-[le] · bien"},{"fr":"Et toi, tu écoutes quoi, comme musique ?","tgt":"Kamu dengar musik apa?","lit":"toi · écouter · musique · quoi"},{"fr":"J'écoute surtout du dangdut.","tgt":"Aku paling sering dengar dangdut.","lit":"je · le plus · souvent · écouter · dangdut"},{"fr":"Tu connais ce chanteur-là ?","tgt":"Kamu tahu penyanyi ini?","lit":"toi · savoir · chanteur · ce"},{"fr":"Non, je ne vois pas qui c'est.","tgt":"Tidak, aku tidak tahu.","lit":"non · je · ne pas · savoir"},{"fr":"Samedi, on va au cinéma ?","tgt":"Hari Sabtu kita ke bioskop, yuk?","lit":"jour · samedi · nous · vers · cinéma · allez"},{"fr":"Ce film est un peu long.","tgt":"Film ini agak panjang.","lit":"film · ce · un peu · long"},{"fr":"La fin du film est triste.","tgt":"Akhir filmnya sedih.","lit":"fin · film-[le] · triste"},{"fr":"Elle me plaît beaucoup, cette chanson !","tgt":"Aku suka lagu ini!","lit":"je · aimer · chanson · ce"}]},{"title":"Les projets du week-end","phrases":[{"fr":"Ce week-end, c'est quoi ton programme ?","tgt":"Akhir pekan ini, apa rencanamu?","lit":"fin · semaine · ce · quoi · projet-toi"},{"fr":"Samedi, je vais aller à Prambanan.","tgt":"Hari Sabtu aku akan pergi ke Prambanan.","lit":"jour · samedi · je · [futur] · aller · vers · Prambanan"},{"fr":"Mes amis viendront avec moi.","tgt":"Teman-temanku akan ikut juga.","lit":"amis-moi · [futur] · suivre · aussi"},{"fr":"Dimanche, je vais me reposer.","tgt":"Hari Minggu aku akan istirahat.","lit":"jour · dimanche · je · [futur] · se reposer"},{"fr":"On partira tôt le matin.","tgt":"Kita akan berangkat pagi-pagi.","lit":"nous · [futur] · partir · tôt le matin"},{"fr":"Tu viendras, hein ?","tgt":"Kamu akan ikut, kan?","lit":"toi · [futur] · suivre · n'est-ce pas"},{"fr":"Je ne sais pas encore.","tgt":"Aku belum tahu.","lit":"je · pas encore · savoir"},{"fr":"Demain, il fera beau.","tgt":"Besok cuacanya akan cerah.","lit":"demain · temps-[le] · [futur] · ensoleillé"},{"fr":"Le soir, nous dînerons ensemble.","tgt":"Malamnya kita akan makan bersama.","lit":"soir-[le] · nous · [futur] · manger · ensemble"},{"fr":"Je rentrerai lundi.","tgt":"Hari Senin aku akan pulang.","lit":"jour · lundi · je · [futur] · rentrer"}],"tip":{"title":"« Akan » : parler du futur","example":"Samedi, je vais aller à Prambanan. — Hari Sabtu aku <b>akan</b> pergi ke Prambanan.","body":"En français, le futur change la fin du verbe : je partirai, tu viendras. En indonésien, rien de tout cela : on pose simplement le petit mot « akan » devant le verbe, et la phrase passe au futur. « Aku akan pergi », mot à mot je, futur, aller, veut dire j'irai ou je vais aller. On dit aussi « kita akan makan bersama », nous mangerons ensemble, ou « besok akan hujan », demain il pleuvra. Très souvent, un mot de temps comme « besok », demain, ou « hari Sabtu », samedi, suffit déjà à dire que c'est le futur, et dans la conversation on peut même laisser tomber « akan ». Mais le garder rend votre phrase très claire. Retenez la famille des petits mots placés devant le verbe : « sudah » pour le passé, « sedang » pour le présent en cours et « akan » pour l'avenir. Astuce : « akan » sonne comme à quand, la question qu'on pose justement sur l'avenir.","lit":"jour · samedi · je · [futur] · aller · vers · Prambanan","say":{"Akan":"Akan","akan":"akan","Aku akan pergi":"Aku akan pergi","kita akan makan bersama":"kita akan makan bersama","besok akan hujan":"besok akan hujan","besok":"besok","hari Sabtu":"hari Sabtu","sudah":"sudah","sedang":"sedang"}}},{"title":"Une sortie à Borobudur","phrases":[{"fr":"On part pour Borobudur à quatre heures du matin.","tgt":"Kita berangkat ke Borobudur jam empat pagi.","lit":"nous · partir · vers · Borobudur · heure · quatre · matin"},{"fr":"On veut voir le lever du soleil.","tgt":"Kita mau lihat matahari terbit.","lit":"nous · vouloir · voir · soleil · se lever"},{"fr":"C'est loin d'ici, Borobudur ?","tgt":"Borobudur jauh dari sini?","lit":"Borobudur · loin · de · ici"},{"fr":"Environ une heure en voiture.","tgt":"Kira-kira satu jam naik mobil.","lit":"environ · un · heure · monter · voiture"},{"fr":"Combien coûte le billet d'entrée ?","tgt":"Tiket masuknya berapa?","lit":"billet · entrer-[le] · combien"},{"fr":"Il y a plein de marches.","tgt":"Tangganya banyak.","lit":"escalier-[le] · beaucoup"},{"fr":"Attends-moi, je suis crevé !","tgt":"Tunggu aku, aku capek!","lit":"attendre · moi · je · fatigué"},{"fr":"Regarde, le paysage est magnifique !","tgt":"Lihat, pemandangannya indah!","lit":"regarder · paysage-[le] · beau"},{"fr":"Tu peux me prendre en photo ?","tgt":"Kamu bisa foto aku?","lit":"toi · pouvoir · photographier · moi"},{"fr":"Je n'étais jamais venu ici avant.","tgt":"Aku belum pernah ke sini.","lit":"je · pas encore · [déjà vécu] · vers · ici"}]},{"title":"Un cadeau pour un ami","phrases":[{"fr":"Tiens, ce cadeau est pour toi.","tgt":"Hadiah ini untuk kamu.","lit":"cadeau · ce · pour · toi"},{"fr":"Merci, c'est pour mon anniversaire ?","tgt":"Makasih, ini untuk ulang tahunku?","lit":"merci · ceci · pour · anniversaire-moi"},{"fr":"J'achète un batik pour ma mère.","tgt":"Aku beli batik untuk ibuku.","lit":"je · acheter · batik · pour · mère-moi"},{"fr":"Je suis venu à Yogya pour étudier.","tgt":"Aku datang ke Yogya untuk kuliah.","lit":"je · venir · vers · Yogya · pour · étudier"},{"fr":"Il faut de l'argent pour aller à Bali.","tgt":"Perlu uang untuk ke Bali.","lit":"besoin · argent · pour · vers · Bali"},{"fr":"Il est pour qui, ce gâteau ?","tgt":"Kue ini untuk siapa?","lit":"gâteau · ce · pour · qui"},{"fr":"C'est pour Andi, c'est son anniversaire aujourd'hui.","tgt":"Untuk Andi, hari ini dia ulang tahun.","lit":"pour · Andi · jour · ce · il · anniversaire"},{"fr":"Il y a une chaise libre pour toi.","tgt":"Ada kursi kosong untuk kamu.","lit":"il y a · chaise · vide · pour · toi"},{"fr":"On se voit pour déjeuner ?","tgt":"Kita ketemu untuk makan siang, yuk?","lit":"nous · se voir · pour · manger · midi · allez"},{"fr":"Ce livre sert à apprendre l'indonésien.","tgt":"Buku ini untuk belajar bahasa Indonesia.","lit":"livre · ce · pour · apprendre · langue · Indonésie"}],"tip":{"title":"« Untuk » : pour quelqu'un, pour faire","example":"Tiens, ce cadeau est pour toi. — Hadiah ini <b>untuk</b> kamu.","body":"Le mot « untuk » veut dire pour, et il s'utilise presque comme en français. D'abord pour une personne : « hadiah ini untuk kamu », mot à mot cadeau, ce, pour, toi, veut dire ce cadeau est pour toi. Remarquez qu'il n'y a pas de verbe être : « untuk » suffit à relier les deux parties. Ensuite pour un but, devant un verbe : « aku datang untuk kuliah », je suis venu pour étudier. Là encore, le verbe reste à sa forme de base, sans aucune terminaison. Pour poser la question pour qui, on dit « untuk siapa ? », par exemple « kue ini untuk siapa ? », il est pour qui, ce gâteau. Entre amis, vous entendrez très souvent « buat » à la place de « untuk », avec le même sens : « buat kamu », pour toi. Astuce : « untuk » commence par un son proche de un, comme un cadeau qu'on tend à quelqu'un.","lit":"cadeau · ce · pour · toi","say":{"Untuk":"Untuk","untuk":"untuk","hadiah ini untuk kamu":"hadiah ini untuk kamu","aku datang untuk kuliah":"aku datang untuk kuliah","untuk siapa ?":"untuk siapa?","kue ini untuk siapa ?":"kue ini untuk siapa?","buat":"buat","buat kamu":"buat kamu"}}},{"title":"Faire un compliment","phrases":[{"fr":"Elle est jolie, ta chemise.","tgt":"Kemejamu bagus.","lit":"chemise-toi · joli"},{"fr":"Merci, c'est un batik de Yogya.","tgt":"Makasih, ini batik Yogya.","lit":"merci · ceci · batik · Yogya"},{"fr":"Ta cuisine est délicieuse !","tgt":"Masakanmu enak!","lit":"cuisine-toi · délicieux"},{"fr":"Elle est belle, ta maison.","tgt":"Rumahmu bagus.","lit":"maison-toi · beau"},{"fr":"Tu as une belle voix.","tgt":"Suaramu bagus.","lit":"voix-toi · beau"},{"fr":"Tu es drôle, toi !","tgt":"Kamu lucu!","lit":"toi · drôle"},{"fr":"Ton indonésien est de plus en plus fluide.","tgt":"Bahasa Indonesiamu makin lancar.","lit":"langue · Indonésie-toi · de plus en plus · fluide"},{"fr":"Ah bon ? Merci beaucoup !","tgt":"Masa? Makasih banyak!","lit":"vraiment · merci · beaucoup"},{"fr":"Elles sont belles, tes photos.","tgt":"Foto-fotomu bagus.","lit":"photos-toi · beau"},{"fr":"Tu as vraiment bon goût.","tgt":"Seleramu bagus.","lit":"goût-toi · bon"}]},{"title":"Trop ou très ?","phrases":[{"fr":"C'est trop pimenté pour moi !","tgt":"Ini terlalu pedas untukku!","lit":"ceci · trop · pimenté · pour-moi"},{"fr":"Ce gudeg est très bon.","tgt":"Gudeg ini enak sekali.","lit":"gudeg · ce · bon · très"},{"fr":"Ce café est trop sucré.","tgt":"Kopi ini terlalu manis.","lit":"café · ce · trop · sucré"},{"fr":"Il fait très chaud cet après-midi.","tgt":"Sore ini panas sekali.","lit":"après-midi · ce · chaud · très"},{"fr":"Le billet est trop cher.","tgt":"Tiketnya terlalu mahal.","lit":"billet-[le] · trop · cher"},{"fr":"Borobudur est très beau au lever du soleil.","tgt":"Borobudur indah sekali waktu matahari terbit.","lit":"Borobudur · beau · très · moment · soleil · se lever"},{"fr":"Au café, la musique est trop forte.","tgt":"Musik di kafe terlalu keras.","lit":"musique · à · café · trop · fort"},{"fr":"Je suis très content de te voir.","tgt":"Aku senang sekali ketemu kamu.","lit":"je · content · très · rencontrer · toi"},{"fr":"Ce n'est pas trop loin.","tgt":"Tidak terlalu jauh.","lit":"ne pas · trop · loin"},{"fr":"Merci, tu es vraiment gentil.","tgt":"Terima kasih, kamu baik sekali.","lit":"merci · toi · gentil · très"}],"tip":{"title":"« Terlalu » et « sekali » : trop et très","example":"Ce café est trop sucré. — Kopi ini <b>terlalu</b> manis.","body":"Voici deux mots qu'on utilise tout le temps à table et entre amis. « Terlalu » veut dire trop, et il se place avant l'adjectif, comme en français : « kopi ini terlalu manis », mot à mot café, ce, trop, sucré, veut dire ce café est trop sucré. « Sekali » veut dire très, mais attention, il se place après l'adjectif : « enak sekali », mot à mot bon très, veut dire très bon. C'est la grande différence à retenir : trop vient devant, très vient derrière. On dit ainsi « terlalu mahal », trop cher, et « panas sekali », très chaud. Pour dire pas trop, on ajoute « tidak » : « tidak terlalu jauh », ce n'est pas trop loin. Entre amis, vous entendrez aussi « banget » après l'adjectif, qui veut dire vraiment très. Astuce : « sekali » veut aussi dire une fois, imaginez que l'adjectif est dit une fois de plus, pour insister.","lit":"café · ce · trop · sucré","say":{"Terlalu":"Terlalu","sekali":"sekali","kopi ini terlalu manis":"kopi ini terlalu manis","Sekali":"Sekali","enak sekali":"enak sekali","terlalu mahal":"terlalu mahal","panas sekali":"panas sekali","tidak":"tidak","tidak terlalu jauh":"tidak terlalu jauh","banget":"banget"}}},{"title":"Se dire au revoir après une soirée","phrases":[{"fr":"Il se fait tard, déjà.","tgt":"Sudah malam.","lit":"[accompli] · nuit"},{"fr":"Il faut que je rentre maintenant.","tgt":"Aku harus pulang sekarang.","lit":"je · devoir · rentrer · maintenant"},{"fr":"Merci pour cette soirée au warung.","tgt":"Makasih untuk malam ini di warung.","lit":"merci · pour · soir · ce · à · warung"},{"fr":"On s'est vraiment bien amusés.","tgt":"Seru sekali.","lit":"amusant · très"},{"fr":"Tu rentres comment, toi ?","tgt":"Kamu pulang naik apa?","lit":"toi · rentrer · monter · quoi"},{"fr":"Moi, je prends un ojek.","tgt":"Aku naik ojek.","lit":"je · monter · ojek"},{"fr":"Sois prudent sur la route.","tgt":"Hati-hati di jalan.","lit":"prudent · à · route"},{"fr":"Quand tu arrives, envoie un message, hein.","tgt":"Kalau sudah sampai, kirim pesan, ya.","lit":"si · [accompli] · arriver · envoyer · message · hein"},{"fr":"On se revoit la semaine prochaine ?","tgt":"Minggu depan ketemu lagi, ya?","lit":"semaine · prochain · se voir · encore · hein"},{"fr":"Bonne nuit et à bientôt, Rina !","tgt":"Selamat malam, sampai jumpa, Rina!","lit":"bon · nuit · jusqu'à · rencontre · Rina"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Maintenant, je peux bavarder avec mes amis.","tgt":"Sekarang aku bisa ngobrol dengan teman-temanku.","lit":"maintenant · je · pouvoir · bavarder · avec · amis-moi"},{"fr":"Je connais tous les mots de ce module.","tgt":"Aku tahu semua kata di modul ini.","lit":"je · savoir · tout · mot · dans · module · ce"},{"fr":"Tous mes amis parlent indonésien.","tgt":"Semua temanku bisa bahasa Indonesia.","lit":"tout · ami-moi · pouvoir · langue · Indonésie"},{"fr":"Moi aussi, je le parle un peu.","tgt":"Aku juga bisa sedikit.","lit":"je · aussi · pouvoir · un peu"},{"fr":"J'aime aussi la cuisine de Yogya.","tgt":"Aku juga suka masakan Yogya.","lit":"je · aussi · aimer · cuisine · Yogya"},{"fr":"Ici, tout le monde est aimable.","tgt":"Semua orang di sini ramah.","lit":"tout · personne · à · ici · aimable"},{"fr":"J'ai tout compris !","tgt":"Aku sudah paham semuanya!","lit":"je · [accompli] · comprendre · tout-[le]"},{"fr":"L'indonésien est plus facile que je ne pensais.","tgt":"Bahasa Indonesia lebih mudah dari yang aku kira.","lit":"langue · Indonésie · plus · facile · que · ce que · je · penser"},{"fr":"Je vais continuer à m'entraîner.","tgt":"Aku akan terus berlatih.","lit":"je · [futur] · continuer · s'entraîner"},{"fr":"Rendez-vous au niveau deux !","tgt":"Sampai jumpa di tingkat dua!","lit":"jusqu'à · rencontre · à · niveau · deux"}],"tip":{"title":"« Juga » et « semua » : aussi et tous","example":"Moi aussi, je le parle un peu. — Aku <b>juga</b> bisa sedikit.","body":"Pour finir ce module, deux petits mots très pratiques dans une conversation. « Juga » veut dire aussi, et il se place juste après la personne ou la chose concernée : « aku juga », moi aussi. « Aku juga bisa sedikit », mot à mot je, aussi, pouvoir, un peu, veut dire moi aussi, je parle un peu. On dit de même « aku juga suka », moi aussi j'aime. « Semua » veut dire tous ou tout, et il se place devant le mot, comme en français : « semua teman », tous les amis, ou « semua orang », tout le monde. Seul, à la fin d'une phrase, on dit plutôt « semuanya », c'est-à-dire le tout : « aku sudah paham semuanya », j'ai tout compris. Remarquez que le nom ne change pas au pluriel : « teman » veut dire ami ou amis. Astuce : « juga » se dit vite, comme un écho qui répète la phrase de l'autre, et « semua » sonne comme sème, on sème sur tout le champ.","lit":"je · aussi · pouvoir · un peu","say":{"Juga":"Juga","semua":"semua","aku juga":"aku juga","Aku juga bisa sedikit":"Aku juga bisa sedikit","aku juga suka":"aku juga suka","Semua":"Semua","semua teman":"semua teman","semua orang":"semua orang","semuanya":"semuanya","aku sudah paham semuanya":"aku sudah paham semuanya","teman":"teman","juga":"juga"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Le premier jour au bureau","phrases":[{"fr":"Bonjour, je commence à travailler ici aujourd'hui.","tgt":"Selamat pagi, saya mulai bekerja di sini hari ini."},{"fr":"Bienvenue dans notre équipe à Bandung !","tgt":"Selamat datang di tim kami di Bandung!"},{"fr":"Excusez-moi, où est mon poste de travail ?","tgt":"Permisi, meja kerja saya di mana?"},{"fr":"Votre place est à côté de la fenêtre.","tgt":"Tempat Anda di sebelah jendela."},{"fr":"Le directeur arrive généralement vers neuf heures.","tgt":"Direktur biasanya datang sekitar jam sembilan."},{"fr":"On travaille du lundi au vendredi.","tgt":"Kami bekerja dari hari Senin sampai hari Jumat."},{"fr":"La salle de réunion se trouve au deuxième étage.","tgt":"Ruang rapat ada di lantai dua."},{"fr":"Si vous avez une question, demandez-moi simplement.","tgt":"Kalau ada pertanyaan, tanya saya saja."},{"fr":"Merci, tout le monde est très accueillant ici.","tgt":"Terima kasih, semua orang di sini sangat ramah."},{"fr":"J'espère que je vais vite m'habituer.","tgt":"Semoga saya cepat terbiasa."}]},{"title":"Les collègues","phrases":[{"fr":"Mon collègue Budi travaille au service marketing.","tgt":"Rekan kerja saya, Budi, bekerja di bagian pemasaran."},{"fr":"Il part au bureau tous les jours à sept heures.","tgt":"Dia berangkat ke kantor setiap hari jam tujuh."},{"fr":"Ibu Sari parle très bien français.","tgt":"Ibu Sari berbicara bahasa Prancis dengan sangat baik."},{"fr":"Elle a étudié deux ans à Lyon.","tgt":"Dia belajar di Lyon selama dua tahun."},{"fr":"Tous les vendredis, nous faisons du sport ensemble.","tgt":"Setiap hari Jumat, kami berolahraga bersama."},{"fr":"Certains collègues viennent au bureau à pied.","tgt":"Beberapa rekan kerja berjalan kaki ke kantor."},{"fr":"Dewi est mariée et a deux enfants.","tgt":"Dewi sudah berkeluarga dan punya dua anak."},{"fr":"À midi, on se retrouve souvent au café d'en bas.","tgt":"Siang hari, kami sering berkumpul di kafe di bawah."},{"fr":"Budi joue au badminton chaque week-end.","tgt":"Budi bermain bulu tangkis setiap akhir pekan."},{"fr":"Je suis en bons termes avec toute l'équipe.","tgt":"Saya berteman baik dengan semua orang di tim."}],"tip":{"title":"Le préfixe « ber- » : les verbes d'état et d'activité","example":"Tous les vendredis, nous faisons du sport ensemble. — Setiap hari Jumat, kami <b>berolahraga</b> bersama.","body":"En indonésien, beaucoup de verbes se fabriquent en ajoutant le petit préfixe « ber » devant un mot de base, et il se prononce « beur », très court. Par exemple, « olahraga » veut dire le sport, et « berolahraga » veut dire faire du sport : dans notre phrase, on dit littéralement chaque vendredi, nous faisons-du-sport ensemble. De la même façon, « jalan », la route, donne « berjalan », marcher, et « main » donne « bermain », jouer. Ces verbes décrivent une activité ou un état, et ils n'ont presque jamais de complément direct, un peu comme nos verbes dormir ou marcher. Ils permettent aussi de dire qu'on possède quelque chose : « berkeluarga », c'est avoir une famille. Pour retenir, pensez que « ber » allume le mot et le transforme en action que l'on vit soi-même.","lit":"chaque · jour · vendredi · nous · faire du sport · ensemble","say":{"olahraga":"olahraga","berolahraga":"berolahraga","jalan":"jalan","berjalan":"berjalan","main":"main","bermain":"bermain","berkeluarga":"berkeluarga"}}},{"title":"Les embouteillages du matin","phrases":[{"fr":"La circulation est terrible ce matin.","tgt":"Lalu lintas pagi ini parah sekali."},{"fr":"La rue Dago est complètement bouchée.","tgt":"Jalan Dago macet total."},{"fr":"Je crois que je vais être en retard à la réunion.","tgt":"Sepertinya saya akan terlambat ke rapat."},{"fr":"Vous devriez prendre un ojek, c'est plus rapide.","tgt":"Sebaiknya Anda naik ojek, lebih cepat."},{"fr":"Le chauffeur d'ojek connaît un raccourci par les ruelles.","tgt":"Tukang ojeknya tahu jalan pintas lewat gang kecil."},{"fr":"Le week-end, beaucoup de gens de Jakarta viennent ici.","tgt":"Pada akhir pekan, banyak orang dari Jakarta datang ke sini."},{"fr":"C'est pour ça qu'il y a autant de voitures.","tgt":"Itu sebabnya ada banyak sekali mobil."},{"fr":"J'ai mis une heure pour faire cinq kilomètres.","tgt":"Saya butuh satu jam untuk menempuh lima kilometer."},{"fr":"Demain, je partirai plus tôt de chez moi.","tgt":"Besok saya akan berangkat dari rumah lebih pagi."},{"fr":"Désolé pour le retard, la route était bouchée.","tgt":"Maaf saya terlambat, jalannya macet."}]},{"title":"La pause déjeuner : un batagor","phrases":[{"fr":"Et si on mangeait un batagor ce midi ?","tgt":"Bagaimana kalau siang ini kita makan batagor?"},{"fr":"Il y a un bon vendeur de batagor près du bureau.","tgt":"Ada penjual batagor yang enak dekat kantor."},{"fr":"Le batagor, c'est du tofu farci au poisson, puis frit.","tgt":"Batagor adalah tahu isi ikan yang digoreng."},{"fr":"On le mange avec une sauce aux cacahuètes.","tgt":"Batagor dimakan dengan bumbu kacang."},{"fr":"Une portion, pas trop épicée, s'il vous plaît.","tgt":"Satu porsi, tidak terlalu pedas, ya, Pak."},{"fr":"Je vous dois combien en tout, monsieur ?","tgt":"Jadi berapa semuanya, Pak?"},{"fr":"Quinze mille roupies, avec le thé glacé.","tgt":"Lima belas ribu rupiah, sudah termasuk es teh."},{"fr":"C'est vraiment bon marché pour un repas aussi bon.","tgt":"Murah sekali untuk makanan seenak ini."},{"fr":"Il faut manger vite, la réunion reprend à une heure.","tgt":"Kita harus makan cepat, rapat mulai lagi jam satu."},{"fr":"Demain, c'est moi qui invite.","tgt":"Besok saya yang traktir."}]},{"title":"Une journée chargée","phrases":[{"fr":"Ce matin, j'ai lu tous mes courriels.","tgt":"Pagi ini saya membaca semua email saya."},{"fr":"Ensuite, j'ai écrit un rapport pour le directeur.","tgt":"Lalu saya menulis laporan untuk direktur."},{"fr":"Mon collègue a appelé un client important.","tgt":"Rekan kerja saya menelepon klien penting."},{"fr":"Nous avons préparé la présentation de demain.","tgt":"Kami menyiapkan presentasi untuk besok."},{"fr":"Qui va expliquer le projet aux clients ?","tgt":"Siapa yang akan menjelaskan proyek ini kepada klien?"},{"fr":"Ibu Rina dirige cette équipe depuis trois ans.","tgt":"Ibu Rina sudah memimpin tim ini selama tiga tahun."},{"fr":"J'ai envoyé le dossier avant midi.","tgt":"Saya mengirim berkas itu sebelum jam dua belas."},{"fr":"Le soir, j'éteins l'ordinateur à six heures.","tgt":"Sore hari, saya mematikan komputer jam enam."},{"fr":"Je dois encore acheter quelque chose pour le dîner.","tgt":"Saya masih harus membeli sesuatu untuk makan malam."},{"fr":"Quelle journée fatigante, j'ai besoin de me reposer !","tgt":"Hari yang melelahkan, saya perlu beristirahat!"}],"tip":{"title":"Le préfixe « me- » : les verbes d'action","example":"Ensuite, j'ai écrit un rapport pour le directeur. — Lalu saya <b>menulis</b> laporan untuk direktur.","body":"Le préfixe « me » sert à former les verbes d'action, ceux qui agissent sur quelque chose : on écrit un rapport, on lit un message, on envoie un dossier. Sa particularité, c'est qu'il se fond dans le mot pour rester facile à prononcer. Avec « tulis », écrire, le « t » disparaît et on dit « menulis » ; avec « baca », lire, on dit « membaca » ; avec « kirim », envoyer, on dit « mengirim ». Dans notre exemple, on dit mot à mot ensuite, je écrire rapport pour directeur, sans aucune conjugaison. Bonne nouvelle pour l'oral : entre amis, beaucoup d'Indonésiens raccourcissent et disent simplement « nulis » ou « baca ». Retenez que « me » annonce une action tournée vers un objet, alors que « ber » parle de ce que l'on vit soi-même.","lit":"ensuite · je · écrire · rapport · pour · directeur","say":{"tulis":"tulis","menulis":"menulis","baca":"baca","membaca":"membaca","kirim":"kirim","mengirim":"mengirim","nulis":"nulis"}}},{"title":"Au supermarché","phrases":[{"fr":"Où est le riz que j'achète d'habitude ?","tgt":"Di mana beras yang biasa saya beli?"},{"fr":"Celui-ci est moins cher que celui-là.","tgt":"Yang ini lebih murah daripada yang itu."},{"fr":"Je prends le grand, pas le petit.","tgt":"Saya ambil yang besar, bukan yang kecil."},{"fr":"Avez-vous des mangues qui sont bien mûres ?","tgt":"Apakah ada mangga yang sudah matang?"},{"fr":"Les légumes qui viennent de Lembang sont très frais.","tgt":"Sayuran yang berasal dari Lembang sangat segar."},{"fr":"La caissière qui porte des lunettes est très gentille.","tgt":"Kasir yang memakai kacamata itu sangat ramah."},{"fr":"Je voudrais aussi le café de Java qui est sur l'étagère du haut.","tgt":"Saya juga mau kopi Jawa yang ada di rak atas."},{"fr":"Vous avez besoin d'un sac, madame ?","tgt":"Perlu kantong, Bu?"},{"fr":"Non merci, j'ai déjà un sac avec moi.","tgt":"Tidak, terima kasih, saya sudah bawa kantong sendiri."},{"fr":"Au total, ça fait quatre-vingt-cinq mille roupies.","tgt":"Totalnya delapan puluh lima ribu rupiah."}],"tip":{"title":"« Yang » : celui qui, le pronom relatif","example":"Je prends le grand, pas le petit. — Saya ambil <b>yang</b> besar, bukan <b>yang</b> kecil.","body":"Le petit mot « yang » est l'un des plus utiles de la langue : il veut dire qui, que, ou celui qui. Il relie un nom à une précision, comme dans « kopi yang panas », le café qui est chaud. Mais surtout, on peut l'employer tout seul pour désigner un objet sans le nommer : dans notre exemple, on dit mot à mot je prends celui-qui grand, pas celui-qui petit. Au supermarché, c'est magique : il suffit de montrer et de dire « yang ini », celui-ci, ou « yang merah », le rouge. Pour retenir, pensez que « yang » est votre doigt qui pointe vers la bonne chose.","lit":"je · prendre · celui qui · grand · non · celui qui · petit","say":{"Yang":"Yang","yang":"yang","kopi yang panas":"kopi yang panas","yang ini":"yang ini","yang merah":"yang merah"}}},{"title":"La pluie de l'après-midi","phrases":[{"fr":"Le ciel commence à se couvrir.","tgt":"Langitnya mulai mendung."},{"fr":"À Bandung, il pleut presque tous les après-midi.","tgt":"Di Bandung, hampir setiap sore turun hujan."},{"fr":"Vous avez pris un parapluie ?","tgt":"Anda bawa payung?"},{"fr":"Non, je l'ai oublié à la maison.","tgt":"Tidak, payung saya ketinggalan di rumah."},{"fr":"Attendons ici que la pluie s'arrête.","tgt":"Kita tunggu di sini sampai hujannya berhenti."},{"fr":"Il pleut vraiment très fort aujourd'hui.","tgt":"Hujannya deras sekali hari ini."},{"fr":"Certaines rues sont déjà inondées.","tgt":"Beberapa jalan sudah banjir."},{"fr":"L'air est plus frais après la pluie.","tgt":"Udaranya lebih sejuk setelah hujan."},{"fr":"Un café chaud, ce serait parfait maintenant.","tgt":"Kopi panas pasti enak sekali sekarang."},{"fr":"Ça y est, le soleil revient enfin.","tgt":"Nah, mataharinya akhirnya muncul lagi."}]},{"title":"Le café de Java","phrases":[{"fr":"Ce café vient d'une plantation près de Bandung.","tgt":"Kopi ini berasal dari kebun dekat Bandung."},{"fr":"Les montagnes autour de la ville sont idéales pour le café.","tgt":"Pegunungan di sekitar kota ini cocok untuk kopi."},{"fr":"Vous le préférez noir ou avec du lait ?","tgt":"Anda lebih suka kopi hitam atau kopi susu?"},{"fr":"Noir et sans sucre, s'il vous plaît.","tgt":"Hitam dan tanpa gula, ya."},{"fr":"Le barista prépare le café avec beaucoup de soin.","tgt":"Baristanya membuat kopi dengan sangat teliti."},{"fr":"Ça sent vraiment bon ici.","tgt":"Harum sekali di sini."},{"fr":"On sent un léger goût de fruit dans ce café.","tgt":"Kopi ini ada sedikit rasa buahnya."},{"fr":"Je voudrais acheter un paquet pour mes parents.","tgt":"Saya mau membeli satu bungkus untuk orang tua saya."},{"fr":"Vous le voulez moulu ou en grains ?","tgt":"Mau yang bubuk atau yang biji?"},{"fr":"En grains, ils ont un moulin en France.","tgt":"Biji saja, mereka punya penggiling kopi di Prancis."}]},{"title":"Cuisiner à la maison","phrases":[{"fr":"Ce soir, je fais la cuisine à la maison.","tgt":"Malam ini saya masak di rumah."},{"fr":"Je vais préparer un nasi goreng tout simple.","tgt":"Saya mau membuat nasi goreng yang sederhana."},{"fr":"D'abord, je coupe l'échalote et l'ail.","tgt":"Pertama, saya memotong bawang merah dan bawang putih."},{"fr":"Ensuite, je fais chauffer un peu d'huile.","tgt":"Kemudian saya memanaskan sedikit minyak."},{"fr":"Puis on met le riz de la veille, c'est meilleur.","tgt":"Lalu masukkan nasi sisa kemarin, hasilnya lebih enak."},{"fr":"Un peu de sauce soja sucrée, et c'est presque prêt.","tgt":"Sedikit kecap manis, dan hampir jadi."},{"fr":"Pouvez-vous mettre la table, s'il vous plaît ?","tgt":"Bisa tolong siapkan meja makan?"},{"fr":"Je mets un œuf au plat sur chaque assiette.","tgt":"Saya taruh telur mata sapi di atas setiap piring."},{"fr":"Attention, c'est encore très chaud.","tgt":"Hati-hati, masih panas sekali."},{"fr":"C'est délicieux, vous cuisinez vraiment bien !","tgt":"Enak sekali, Anda pandai memasak!"}]},{"title":"Chez le médecin","phrases":[{"fr":"Depuis hier, je ne me sens pas très bien.","tgt":"Sejak kemarin saya merasa kurang enak badan."},{"fr":"J'ai de la fièvre et mal à la gorge.","tgt":"Saya demam dan sakit tenggorokan."},{"fr":"Asseyez-vous, je vais vous examiner.","tgt":"Silakan duduk, saya periksa dulu."},{"fr":"Ouvrez grand la bouche, s'il vous plaît.","tgt":"Coba buka mulutnya lebar-lebar."},{"fr":"Vous avez une petite infection.","tgt":"Anda kena infeksi ringan."},{"fr":"Est-ce que c'est grave, docteur ?","tgt":"Apakah ini serius, Dok?"},{"fr":"Non, mais vous devez vous reposer trois jours.","tgt":"Tidak, tapi Anda harus istirahat tiga hari."},{"fr":"Buvez beaucoup d'eau et dormez suffisamment.","tgt":"Minum banyak air dan tidur yang cukup."},{"fr":"Pouvez-vous me faire un certificat pour mon travail ?","tgt":"Bisa minta surat keterangan sakit untuk kantor saya?"},{"fr":"Bien sûr, je vous le prépare tout de suite.","tgt":"Tentu, saya buatkan sekarang."}]},{"title":"À la pharmacie","phrases":[{"fr":"Bonjour, j'ai une ordonnance du médecin.","tgt":"Selamat siang, saya punya resep dari dokter."},{"fr":"Voici vos médicaments, madame.","tgt":"Ini obat Anda, Bu."},{"fr":"Prenez un comprimé matin, midi et soir.","tgt":"Minum satu tablet pagi, siang, dan malam."},{"fr":"Avant ou après le repas ?","tgt":"Sebelum atau sesudah makan?"},{"fr":"Après le repas, avec un grand verre d'eau.","tgt":"Sesudah makan, dengan segelas air."},{"fr":"Avez-vous aussi quelque chose contre la toux ?","tgt":"Ada juga obat batuk?"},{"fr":"Ce sirop est efficace et pas trop sucré.","tgt":"Sirup ini manjur dan tidak terlalu manis."},{"fr":"Gardez-le dans un endroit frais.","tgt":"Simpan di tempat yang sejuk."},{"fr":"Est-ce que je peux régler par carte ici ?","tgt":"Di sini bisa bayar pakai kartu?"},{"fr":"Bon rétablissement, madame !","tgt":"Semoga lekas sembuh, Bu!"}]},{"title":"Un dîner pour les collègues","phrases":[{"fr":"Samedi, j'invite mes collègues à la maison.","tgt":"Hari Sabtu saya mengundang rekan kerja ke rumah."},{"fr":"Je vais leur cuisiner un repas sundanais.","tgt":"Saya akan memasakkan mereka masakan Sunda."},{"fr":"Ma voisine m'a acheté des légumes au marché.","tgt":"Tetangga saya membelikan saya sayuran di pasar."},{"fr":"Pouvez-vous me passer le sel, s'il vous plaît ?","tgt":"Bisa tolong ambilkan garam?"},{"fr":"Je dois d'abord nettoyer le salon.","tgt":"Saya harus membersihkan ruang tamu dulu."},{"fr":"Ibu Sari m'a expliqué comment faire le karedok.","tgt":"Ibu Sari sudah menjelaskan cara membuat karedok kepada saya."},{"fr":"Les invités arrivent, pouvez-vous leur ouvrir la porte ?","tgt":"Tamunya datang, tolong bukakan pintu, ya?"},{"fr":"Budi a apporté un gâteau pour tout le monde.","tgt":"Budi membawakan kue untuk semua orang."},{"fr":"Je vous ressers un peu de riz ?","tgt":"Mau saya ambilkan nasi lagi?"},{"fr":"Merci pour cette soirée, c'était vraiment réussi.","tgt":"Terima kasih untuk malam ini, acaranya sukses sekali."}],"tip":{"title":"Le suffixe « -kan » : faire pour quelqu'un, rendre","example":"Ma voisine m'a acheté des légumes au marché. — Tetangga saya <b>membelikan</b> saya sayuran di pasar.","body":"Le suffixe « kan », qui se prononce comme le mot français quand, s'accroche à la fin d'un verbe et lui donne une nouvelle direction. Premier sens : faire quelque chose pour quelqu'un. « Beli », acheter, devient « belikan », acheter pour quelqu'un : dans notre phrase, on dit mot à mot ma voisine acheter-pour moi des légumes au marché. Deuxième sens : rendre quelque chose d'une certaine façon, comme « bersih », propre, qui donne « membersihkan », rendre propre, donc nettoyer. À table, c'est parfait pour demander un service : « tolong ambilkan », prenez-le pour moi, s'il vous plaît. Pour retenir, imaginez que « kan » est un petit paquet cadeau que l'on tend à quelqu'un.","lit":"voisine · ma · acheter pour · moi · légumes · à · marché","say":{"Beli":"Beli","belikan":"belikan","bersih":"bersih","membersihkan":"membersihkan","tolong ambilkan":"tolong ambilkan","-kan":"kan","kan":"kan"}}},{"title":"Le marché du samedi","phrases":[{"fr":"Le marché du quartier ouvre très tôt le matin.","tgt":"Pasar dekat rumah buka pagi-pagi sekali."},{"fr":"Les fruits sont moins chers ici qu'au supermarché.","tgt":"Buah di sini lebih murah daripada di supermarket."},{"fr":"Un kilo de tomates, c'est combien, madame ?","tgt":"Satu kilo tomat berapa, Bu?"},{"fr":"Dix mille roupies le kilo, elles sont toutes fraîches.","tgt":"Sepuluh ribu rupiah sekilo, masih segar semua."},{"fr":"Vous me faites un petit prix, madame ?","tgt":"Bisa kurang sedikit, Bu?"},{"fr":"D'accord, huit mille seulement pour vous.","tgt":"Boleh, delapan ribu saja untuk Anda."},{"fr":"Je prends aussi une botte de liseron d'eau.","tgt":"Saya juga ambil satu ikat kangkung."},{"fr":"Le marchand de poulet est juste à côté.","tgt":"Penjual ayam ada di sebelahnya."},{"fr":"Mon panier est déjà plein !","tgt":"Keranjang saya sudah penuh!"},{"fr":"Je reviendrai la semaine prochaine, c'est promis.","tgt":"Saya akan datang lagi minggu depan, janji."}]},{"title":"Un week-end à Lembang","phrases":[{"fr":"Ce week-end, nous allons à Lembang.","tgt":"Akhir pekan ini kami pergi ke Lembang."},{"fr":"C'est à une heure de Bandung, dans les montagnes.","tgt":"Tempatnya satu jam dari Bandung, di pegunungan."},{"fr":"L'air là-haut est beaucoup plus frais.","tgt":"Udara di atas sana jauh lebih sejuk."},{"fr":"On peut cueillir des fraises dans les champs.","tgt":"Kita bisa memetik stroberi di kebun."},{"fr":"Les enfants adorent nourrir les lapins.","tgt":"Anak-anak senang sekali memberi makan kelinci."},{"fr":"Il y a aussi un volcan à visiter tout près.","tgt":"Di dekat sana juga ada gunung berapi yang bisa dikunjungi."},{"fr":"Il faut partir tôt pour éviter les bouchons.","tgt":"Kita harus berangkat pagi supaya tidak kena macet."},{"fr":"Pensez à prendre une veste chaude.","tgt":"Bawa jaket yang hangat, ya."},{"fr":"Au retour, on mangera du maïs grillé.","tgt":"Waktu pulang, kita makan jagung bakar."},{"fr":"C'était le week-end idéal pour se détendre.","tgt":"Akhir pekan itu sempurna untuk bersantai."}]},{"title":"La moto en panne","phrases":[{"fr":"Ma moto refuse de démarrer ce matin.","tgt":"Motor saya tidak mau hidup pagi ini."},{"fr":"Il y a un garage au bout de la rue.","tgt":"Ada bengkel di ujung jalan."},{"fr":"Le mécanicien va regarder tout de suite.","tgt":"Montirnya akan langsung memeriksa."},{"fr":"Le problème vient de la batterie.","tgt":"Masalahnya ada di aki."},{"fr":"Il faut la changer, elle est trop vieille.","tgt":"Harus diganti, akinya sudah terlalu tua."},{"fr":"Combien de temps dois-je attendre ?","tgt":"Saya harus menunggu berapa lama?"},{"fr":"Environ trente minutes, pas plus.","tgt":"Sekitar tiga puluh menit, tidak lebih."},{"fr":"Pendant que vous y êtes, vérifiez aussi les freins.","tgt":"Sekalian periksa remnya juga, ya."},{"fr":"Voilà, elle roule comme une neuve.","tgt":"Nah, motornya sudah jalan seperti baru lagi."},{"fr":"Merci beaucoup, vous m'avez vraiment rendu service.","tgt":"Terima kasih banyak, Pak, Anda sangat membantu."}]},{"title":"La laverie du quartier","phrases":[{"fr":"Ma machine à laver est en panne.","tgt":"Mesin cuci saya rusak."},{"fr":"Je vais apporter mon linge à la laverie.","tgt":"Saya mau bawa cucian ke laundry."},{"fr":"Ici, on paie au kilo.","tgt":"Di sini bayarnya per kilo."},{"fr":"Ça fait trois kilos, donc vingt et un mille roupies.","tgt":"Tiga kilo, jadi dua puluh satu ribu rupiah."},{"fr":"Quand est-ce que je peux le récupérer ?","tgt":"Kapan bisa diambil?"},{"fr":"Demain après-midi, lavé et repassé.","tgt":"Besok sore, sudah dicuci dan disetrika."},{"fr":"Quand il pleut, le linge sèche mal à la maison.","tgt":"Kalau hujan, cucian susah kering di rumah."},{"fr":"Pouvez-vous laver cette chemise à part ?","tgt":"Kemeja ini bisa dicuci terpisah?"},{"fr":"Oui, je mets une étiquette avec votre nom.","tgt":"Bisa, saya kasih label nama Anda."},{"fr":"Quel service pratique pour les gens occupés !","tgt":"Layanan yang praktis sekali untuk orang sibuk!"}]},{"title":"Les voisins du quartier","phrases":[{"fr":"Notre voisin, Pak Dedi, aime beaucoup rendre service.","tgt":"Tetangga kami, Pak Dedi, suka sekali menolong."},{"fr":"Il tient un petit warung devant chez lui.","tgt":"Dia punya warung kecil di depan rumahnya."},{"fr":"Le soir, les voisins bavardent devant les maisons.","tgt":"Malam hari, para tetangga mengobrol di depan rumah."},{"fr":"Ma voisine m'a apporté des bananes frites.","tgt":"Tetangga saya membawakan saya pisang goreng."},{"fr":"Ici, tout le monde se connaît.","tgt":"Di sini semua orang saling kenal."},{"fr":"Dimanche, il y a un grand nettoyage du quartier.","tgt":"Hari Minggu ada kerja bakti di lingkungan kami."},{"fr":"Chaque famille donne un coup de main.","tgt":"Setiap keluarga ikut membantu."},{"fr":"Après, on partage un repas tous ensemble.","tgt":"Sesudahnya, kami makan bersama-sama."},{"fr":"Je me sens vraiment chez moi dans ce quartier.","tgt":"Saya merasa betah sekali di lingkungan ini."},{"fr":"C'est ce que j'aime le plus à Bandung.","tgt":"Itu yang paling saya suka di Bandung."}]},{"title":"Trouver une chambre","phrases":[{"fr":"Je cherche une chambre près de mon bureau.","tgt":"Saya mencari kamar kos dekat kantor."},{"fr":"Celle-ci est meublée et a sa propre salle de bain.","tgt":"Kamar ini sudah ada perabotnya dan kamar mandi dalam."},{"fr":"Le loyer est d'un million et demi de roupies par mois.","tgt":"Sewanya satu setengah juta rupiah per bulan."},{"fr":"L'électricité est-elle comprise ?","tgt":"Apakah sudah termasuk listrik?"},{"fr":"Oui, mais le wifi est à part.","tgt":"Sudah, tapi wifi bayar sendiri."},{"fr":"Est-ce que je peux voir la chambre maintenant ?","tgt":"Boleh saya lihat kamarnya sekarang?"},{"fr":"Elle est lumineuse et assez calme.","tgt":"Kamarnya terang dan cukup tenang."},{"fr":"Le quartier a l'air sûr et agréable.","tgt":"Lingkungannya kelihatan aman dan nyaman."},{"fr":"Il faut payer deux mois d'avance.","tgt":"Harus bayar dua bulan di muka."},{"fr":"Parfait, je la prends à partir du premier du mois.","tgt":"Baik, saya ambil mulai tanggal satu."}]},{"title":"Les règles de la maison","phrases":[{"fr":"Voici les règles de la maison.","tgt":"Ini peraturan di rumah kos ini."},{"fr":"Ne rentrez pas après onze heures du soir.","tgt":"Jangan pulang lewat jam sebelas malam."},{"fr":"Ne laissez pas vos chaussures dans le couloir.","tgt":"Jangan taruh sepatu di lorong."},{"fr":"Ne faites pas de bruit, le bébé dort.","tgt":"Jangan berisik, ya, bayinya sedang tidur."},{"fr":"Ne mangez pas dans la chambre, s'il vous plaît.","tgt":"Tolong jangan makan di dalam kamar."},{"fr":"La cuisine se trouve au bout du couloir.","tgt":"Dapurnya ada di ujung lorong."},{"fr":"N'oubliez pas d'éteindre la lumière en partant.","tgt":"Jangan lupa mematikan lampu kalau keluar."},{"fr":"Et ne vous inquiétez pas, le quartier est calme.","tgt":"Dan jangan khawatir, lingkungannya tenang."},{"fr":"Si vous avez un problème, appelez-moi.","tgt":"Kalau ada masalah, telepon saya saja."},{"fr":"Merci, je vais tout respecter.","tgt":"Terima kasih, saya akan mematuhi semuanya."}],"tip":{"title":"« Jangan » : l'interdiction","example":"N'oubliez pas d'éteindre la lumière en partant. — <b>Jangan</b> lupa mematikan lampu kalau keluar.","body":"Pour dire ne fais pas ou ne faites pas, l'indonésien utilise un seul mot, « jangan », placé tout au début, juste devant le verbe. Attention à ne pas le confondre avec « tidak », qui constate simplement que quelque chose ne se fait pas, alors que « jangan » interdit ou conseille. Dans notre exemple, on dit mot à mot ne-pas oublier éteindre lampe si sortir. Deux formules reviennent sans cesse à l'oral : « jangan lupa », n'oublie pas, et « jangan khawatir », ne t'inquiète pas. Pour adoucir, on ajoute « tolong » devant, ou le petit « ya » à la fin, et l'interdiction devient une demande aimable. Astuce : « jangan » sonne un peu comme un doigt levé qui dit attention.","lit":"ne pas · oublier · éteindre · lampe · si · sortir","say":{"Jangan":"Jangan","jangan":"jangan","tidak":"tidak","jangan lupa":"jangan lupa","jangan khawatir":"jangan khawatir","tolong":"tolong","ya":"ya"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Vous savez maintenant parler de votre quotidien en indonésien.","tgt":"Sekarang Anda bisa bercerita tentang kehidupan sehari-hari dalam bahasa Indonesia."},{"fr":"Vous pouvez raconter votre journée au bureau.","tgt":"Anda bisa menceritakan hari Anda di kantor."},{"fr":"Vous savez faire vos courses et marchander.","tgt":"Anda bisa berbelanja dan menawar harga."},{"fr":"Vous pouvez expliquer vos symptômes au médecin.","tgt":"Anda bisa menjelaskan keluhan Anda kepada dokter."},{"fr":"Vous connaissez maintenant les préfixes ber et me.","tgt":"Sekarang Anda sudah mengenal awalan ber dan me."},{"fr":"Vous savez aussi utiliser le mot yang pour préciser.","tgt":"Anda juga tahu cara memakai kata yang."},{"fr":"Et vous savez interdire poliment avec le mot jangan.","tgt":"Anda juga bisa melarang dengan sopan memakai kata jangan."},{"fr":"Continuez à vous entraîner un peu chaque jour.","tgt":"Teruslah berlatih sedikit setiap hari."},{"fr":"Le prochain module vous emmène en voyage.","tgt":"Modul berikutnya akan membawa Anda jalan-jalan."},{"fr":"Bravo pour tous vos progrès !","tgt":"Selamat atas semua kemajuan Anda!"}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Lombok","phrases":[{"fr":"Notre avion a atterri à Lombok à l'heure.","tgt":"Pesawat kami mendarat di Lombok tepat waktu."},{"fr":"Il fait bien plus chaud ici qu'à Bali.","tgt":"Di sini jauh lebih panas daripada di Bali."},{"fr":"Où peut-on retirer de l'argent dans cet aéroport ?","tgt":"Di mana kami bisa mengambil uang di bandara ini?"},{"fr":"Je voudrais acheter une carte SIM locale.","tgt":"Saya mau membeli kartu SIM lokal."},{"fr":"Le chauffeur de l'hôtel nous attend déjà dehors.","tgt":"Sopir hotel sudah menunggu kami di luar."},{"fr":"Combien de temps faut-il pour aller à Senggigi ?","tgt":"Berapa lama perjalanan ke Senggigi?"},{"fr":"Environ une heure et demie en voiture.","tgt":"Kira-kira satu setengah jam naik mobil."},{"fr":"La route longe la côte pendant tout le trajet.","tgt":"Jalannya menyusuri pantai sepanjang perjalanan."},{"fr":"Nous restons deux nuits ici avant de partir pour les Gili.","tgt":"Kami menginap dua malam di sini sebelum berangkat ke Gili."},{"fr":"Lombok est plus calme que je ne l'imaginais.","tgt":"Lombok lebih tenang daripada yang saya bayangkan."}]},{"title":"Le bateau public vers les îles Gili","phrases":[{"fr":"Le bateau public part du port de Bangsal.","tgt":"Perahu umum berangkat dari Pelabuhan Bangsal."},{"fr":"Les billets se vendent au guichet près de la plage.","tgt":"Tiketnya dijual di loket dekat pantai."},{"fr":"Il faut attendre que le bateau soit plein.","tgt":"Kita harus menunggu sampai perahunya penuh."},{"fr":"Les porteurs proposent de prendre nos sacs.","tgt":"Para kuli angkut menawarkan diri untuk membawa tas kami."},{"fr":"Enlevez vos chaussures, on aura les pieds mouillés en montant.","tgt":"Lepas sepatu Anda, kaki kita akan basah waktu naik perahu."},{"fr":"La traversée ne dure que vingt minutes.","tgt":"Penyeberangannya hanya dua puluh menit."},{"fr":"Mettez votre sac sous le banc, s'il vous plaît.","tgt":"Tolong taruh tas Anda di bawah bangku."},{"fr":"Près des îles, l'eau devient turquoise.","tgt":"Air lautnya berubah menjadi biru toska di dekat pulau."},{"fr":"Il n'y a pas de voitures sur Gili Trawangan.","tgt":"Tidak ada mobil di Gili Trawangan."},{"fr":"Ici, on marche, on fait du vélo ou on prend la charrette à cheval.","tgt":"Di sini orang berjalan kaki, naik sepeda, atau naik cidomo."}]},{"title":"Explorer Gili Trawangan","phrases":[{"fr":"Nous voulons faire le tour de l'île à vélo.","tgt":"Kami mau mengelilingi pulau ini dengan sepeda."},{"fr":"Faire le tour de l'île ne prend qu'une heure.","tgt":"Mengelilingi pulau ini hanya butuh satu jam."},{"fr":"Demain, nous visiterons aussi Gili Meno.","tgt":"Besok kami juga akan mengunjungi Gili Meno."},{"fr":"Contactez le centre de plongée avant ce soir, s'il vous plaît.","tgt":"Tolong hubungi pusat selam sebelum malam ini."},{"fr":"Le moniteur va nous retrouver au café de la plage.","tgt":"Instruktur akan menemui kami di kafe pantai."},{"fr":"Mieux vaut ne pas s'approcher d'un cheval par derrière.","tgt":"Sebaiknya jangan mendekati kuda dari belakang."},{"fr":"On profite du coucher de soleil depuis la balançoire de la plage.","tgt":"Kami menikmati matahari terbenam dari ayunan di pantai."},{"fr":"Beaucoup de touristes viennent sur cette plage en fin d'après-midi.","tgt":"Banyak turis mendatangi pantai ini pada sore hari."},{"fr":"Le soir, on trouve du poisson grillé au marché de nuit.","tgt":"Pada malam hari, pasar malam menjual ikan bakar."},{"fr":"J'aime vraiment beaucoup cette petite île.","tgt":"Saya sangat menyukai pulau kecil ini."}],"tip":{"title":"Le suffixe « -i » : agir sur un lieu ou une personne","example":"Demain, nous visiterons aussi Gili Meno. — Besok kami juga akan <b>mengunjungi</b> Gili Meno.","body":"Le suffixe « -i », collé au bout d'un mot, fabrique un verbe qui vise directement un lieu ou une personne, sans petit mot de liaison. Prenez « kunjung », l'idée de visite : « mengunjungi Gili Meno » veut dire visiter Gili Meno, mot à mot visiter Gili Meno, sans « ke », qui signifie vers. De même, « dekat » veut dire proche, et « mendekati kuda » signifie s'approcher du cheval ; « keliling », le tour, donne « mengelilingi pulau », faire le tour de l'île. À l'impératif, on laisse tomber le début « me- » et on garde le « -i » : « hubungi saya », contactez-moi. Pour bien le dire, prononcez ce « i » final net et clair, comme dans le mot français ami. Retenez cette image : le « -i » pose le doigt sur la cible de l'action.","lit":"demain · nous · aussi · [futur] · visiter · Gili Meno","say":{"kunjung":"kunjung","mengunjungi Gili Meno":"mengunjungi Gili Meno","ke":"ke","dekat":"dekat","mendekati kuda":"mendekati kuda","keliling":"keliling","mengelilingi pulau":"mengelilingi pulau","hubungi saya":"hubungi saya","-i":"i","i":"i"}}},{"title":"Louer un vélo sur Gili Air","phrases":[{"fr":"Où est-ce qu'on peut louer des vélos par ici ?","tgt":"Di mana kami bisa menyewa sepeda di sekitar sini?"},{"fr":"C'est cinquante mille roupies pour la journée.","tgt":"Harganya lima puluh ribu rupiah untuk satu hari."},{"fr":"Ce vélo a un pneu un peu dégonflé.","tgt":"Ban sepeda ini agak kempes."},{"fr":"Pourriez-vous me donner un autre vélo ?","tgt":"Bisakah Anda memberi saya sepeda yang lain?"},{"fr":"Le chemin du nord est plein de sable.","tgt":"Jalan di sebelah utara penuh pasir."},{"fr":"Parfois, il faut pousser le vélo à côté de soi.","tgt":"Kadang-kadang kita harus menuntun sepeda."},{"fr":"Arrêtons-nous dans ce petit café au bord de l'eau.","tgt":"Mari kita berhenti di kafe kecil di tepi pantai itu."},{"fr":"Je vais prendre une noix de coco fraîche avec des glaçons.","tgt":"Saya pesan es kelapa muda."},{"fr":"Il faut rendre le vélo avant six heures.","tgt":"Sepedanya harus dikembalikan sebelum jam enam."},{"fr":"Gili Air est encore plus tranquille que Gili Trawangan.","tgt":"Gili Air bahkan lebih tenang daripada Gili Trawangan."}]},{"title":"Le baptême de plongée","phrases":[{"fr":"Je viens de m'inscrire pour essayer la plongée.","tgt":"Saya baru saja mendaftar untuk mencoba menyelam."},{"fr":"Le moniteur vient de nous expliquer les signes de la main.","tgt":"Instruktur baru saja menjelaskan isyarat tangan kepada kami."},{"fr":"Je rentre à peine dans cette combinaison.","tgt":"Baju selam ini hampir tidak muat untuk saya."},{"fr":"Nous sommes presque prêts à plonger.","tgt":"Kami hampir siap untuk menyelam."},{"fr":"Nous sommes descendus presque à douze mètres.","tgt":"Kami menyelam sampai hampir dua belas meter."},{"fr":"Je viens de voir une tortue énorme !","tgt":"Saya baru saja melihat penyu yang sangat besar!"},{"fr":"J'ai failli oublier de respirer lentement.","tgt":"Saya hampir lupa bernapas pelan-pelan."},{"fr":"Le bateau vient de revenir au rivage.","tgt":"Perahunya baru saja kembali ke pantai."},{"fr":"Mon masque s'est presque rempli d'eau.","tgt":"Masker saya hampir penuh dengan air."},{"fr":"Je viens de réserver une deuxième plongée pour demain.","tgt":"Saya baru saja memesan penyelaman kedua untuk besok."}],"tip":{"title":"« Hampir » et « baru saja » : presque, et venir de","example":"Je viens de voir une tortue énorme ! — Saya <b>baru saja</b> melihat penyu yang sangat besar!","body":"Pour dire qu'une chose vient tout juste d'arriver, l'indonésien place « baru saja » juste avant le verbe, et le verbe ne change pas. « Saya baru saja melihat penyu » se décompose en je, venir de, voir, tortue : je viens de voir une tortue. À l'oral, on dit souvent simplement « baru », comme dans « baru datang », je viens d'arriver. À l'inverse, « hampir » signifie presque, et devant un verbe il traduit aussi notre j'ai failli : « saya hampir lupa », j'ai failli oublier, ou « hampir siap », presque prêt. Dites « ham-pir » en deux syllabes, avec un « h » bien soufflé au début. Petite astuce : « baru » veut aussi dire neuf, alors une action toute neuve se dit avec « baru ».","lit":"je · venir de · voir · tortue · qui · très · grand","say":{"Hampir":"Hampir","baru saja":"baru saja","Saya baru saja melihat penyu":"Saya baru saja melihat penyu","baru":"baru","baru datang":"baru datang","hampir":"hampir","saya hampir lupa":"saya hampir lupa","hampir siap":"hampir siap"}}},{"title":"Les tortues de Gili Meno","phrases":[{"fr":"On peut nager avec les tortues à Gili Meno.","tgt":"Kita bisa berenang bersama penyu di Gili Meno."},{"fr":"Je loue un masque et un tuba pour l'après-midi.","tgt":"Saya menyewa masker dan snorkel untuk sore ini."},{"fr":"Le courant est assez fort près du récif.","tgt":"Arusnya cukup kuat di dekat karang."},{"fr":"Ne touchez pas le corail, s'il vous plaît.","tgt":"Tolong jangan menyentuh karang."},{"fr":"Il y a des statues sous l'eau, pas loin d'ici.","tgt":"Ada patung-patung di bawah air, tidak jauh dari sini."},{"fr":"Les poissons sont incroyablement colorés.","tgt":"Ikan-ikannya berwarna-warni sekali."},{"fr":"Mettez de la crème solaire avant d'aller dans l'eau.","tgt":"Pakailah tabir surya sebelum masuk ke air."},{"fr":"Portez un tee-shirt pour protéger votre dos.","tgt":"Pakai kaus untuk melindungi punggung Anda."},{"fr":"Une tortue a nagé juste à côté de moi.","tgt":"Seekor penyu berenang tepat di samping saya."},{"fr":"Cette île est parfaite pour se reposer.","tgt":"Pulau ini sempurna untuk beristirahat."}]},{"title":"Louer un scooter à Senggigi","phrases":[{"fr":"Je voudrais louer un scooter pour trois jours.","tgt":"Saya ingin menyewa motor selama tiga hari."},{"fr":"Avez-vous un permis de conduire international ?","tgt":"Apakah Anda punya SIM internasional?"},{"fr":"Le casque est obligatoire, même pour le passager.","tgt":"Helm wajib dipakai, bahkan untuk penumpang."},{"fr":"Faites le plein avant de partir vers le sud.","tgt":"Isi bensin dulu sebelum berangkat ke selatan."},{"fr":"L'essence s'achète en bouteille au bord de la route.","tgt":"Bensinnya dibeli dalam botol di pinggir jalan."},{"fr":"En Indonésie, on roule à gauche.","tgt":"Di Indonesia, kita berkendara di sebelah kiri."},{"fr":"Faites attention aux chiens et aux poules sur la route.","tgt":"Hati-hati dengan anjing dan ayam di jalan."},{"fr":"La route côtière vers le sud est magnifique.","tgt":"Jalan pantai ke arah selatan indah sekali."},{"fr":"Nous allons jusqu'aux plages de Kuta Lombok.","tgt":"Kami pergi sampai ke pantai-pantai di Kuta Lombok."},{"fr":"Dois-je laisser mon passeport en garantie ?","tgt":"Apakah saya harus meninggalkan paspor sebagai jaminan?"}]},{"title":"L'ascension du Rinjani","phrases":[{"fr":"S'il fait beau, nous montons au Rinjani demain.","tgt":"Kalau cuacanya bagus, kami akan mendaki Gunung Rinjani besok."},{"fr":"Si vous êtes fatigué, on peut s'arrêter.","tgt":"Kalau Anda capek, kita bisa berhenti."},{"fr":"Si on part à deux heures du matin, on verra le lever du soleil.","tgt":"Kalau kita berangkat jam dua dini hari, kita akan melihat matahari terbit."},{"fr":"Le guide connaît chaque sentier de ce volcan.","tgt":"Pemandu itu mengenal setiap jalur di gunung ini."},{"fr":"S'il pleut, le sentier devient très glissant.","tgt":"Kalau hujan, jalurnya jadi sangat licin."},{"fr":"Prenez une veste chaude, il fait très froid là-haut.","tgt":"Bawalah jaket tebal, di atas dingin sekali."},{"fr":"Si vous avez peur du vide, ne vous approchez pas trop du bord du cratère.","tgt":"Kalau Anda takut ketinggian, jangan terlalu dekat dengan tepi kawah."},{"fr":"Le lac au fond du cratère s'appelle Segara Anak.","tgt":"Danau di dalam kawah itu namanya Segara Anak."},{"fr":"Si j'avais su, j'aurais apporté plus d'eau.","tgt":"Kalau saya tahu, saya pasti membawa lebih banyak air."},{"fr":"La vue du sommet efface toute notre fatigue.","tgt":"Pemandangan dari puncak menghapus semua rasa lelah kami."}],"tip":{"title":"« Kalau » : si, la condition","example":"S'il pleut, le sentier devient très glissant. — <b>Kalau</b> hujan, jalurnya jadi sangat licin.","body":"Pour exprimer une condition, on commence simplement la phrase par « kalau », qui veut dire si. « Kalau hujan, jalurnya jadi sangat licin » se décompose en si, pleuvoir, le sentier, devenir, très, glissant. Comme le verbe ne se conjugue jamais, la même construction sert pour s'il pleut, s'il pleuvait et même s'il avait plu : c'est le contexte qui fait le travail. Vous pouvez ajouter « pasti », sûrement, dans la deuxième partie pour insister : « kalau saya tahu, saya pasti membawa air », si j'avais su, j'aurais apporté de l'eau. À l'oral, marquez une petite pause après la condition, comme une virgule. Et retenez la formule passe-partout « kalau bisa », si possible, très utile pour demander poliment.","lit":"si · pleuvoir · sentier-le · devenir · très · glissant","say":{"Kalau":"Kalau","kalau":"kalau","Kalau hujan, jalurnya jadi sangat licin":"Kalau hujan, jalurnya jadi sangat licin","pasti":"pasti","kalau saya tahu, saya pasti membawa air":"kalau saya tahu, saya pasti membawa air","kalau bisa":"kalau bisa"}}},{"title":"Les cascades de Tetebatu","phrases":[{"fr":"Tetebatu est un village au pied du volcan.","tgt":"Tetebatu adalah desa di kaki gunung."},{"fr":"Un jeune du village nous guide jusqu'à la cascade.","tgt":"Seorang pemuda desa mengantar kami ke air terjun."},{"fr":"On marche une heure à travers les rizières.","tgt":"Kami berjalan satu jam melewati sawah."},{"fr":"Des singes noirs vivent dans cette forêt.","tgt":"Monyet hitam hidup di hutan ini."},{"fr":"L'eau de la cascade est glacée.","tgt":"Air di air terjun itu sedingin es."},{"fr":"Vous pouvez vous baigner ici sans danger.","tgt":"Anda bisa berenang di sini dengan aman."},{"fr":"Le chemin du retour monte beaucoup.","tgt":"Jalan pulangnya banyak tanjakan."},{"fr":"Ce soir, nous dormons chez l'habitant.","tgt":"Malam ini kami menginap di rumah penduduk."},{"fr":"Notre hôtesse prépare le dîner avec les légumes de son jardin.","tgt":"Ibu pemilik rumah memasak makan malam dengan sayuran dari kebunnya."},{"fr":"Ici, ce sont les coqs qui nous réveillent.","tgt":"Di sini kita terbangun oleh kokok ayam."}]},{"title":"Les tisserandes de Sukarara","phrases":[{"fr":"Le village de Sukarara est connu pour ses tissus tissés.","tgt":"Desa Sukarara terkenal dengan kain tenunnya."},{"fr":"Les femmes tissent à la main devant leur maison.","tgt":"Para perempuan menenun dengan tangan di depan rumah mereka."},{"fr":"Fabriquer un seul tissu peut prendre plusieurs semaines.","tgt":"Membuat satu kain bisa memakan waktu beberapa minggu."},{"fr":"Est-ce que je peux essayer de tisser un peu ?","tgt":"Boleh saya mencoba menenun sedikit?"},{"fr":"Combien coûte cette écharpe rouge ?","tgt":"Berapa harga selendang merah ini?"},{"fr":"Elle coûte trois cent mille roupies.","tgt":"Harganya tiga ratus ribu rupiah."},{"fr":"C'est un peu cher, pouvez-vous faire un petit effort sur le prix ?","tgt":"Agak mahal, bisakah harganya dikurangi sedikit?"},{"fr":"Je prends les deux pour quatre cent cinquante mille.","tgt":"Saya ambil dua-duanya dengan harga empat ratus lima puluh ribu."},{"fr":"Pouvez-vous l'emballer pour offrir ?","tgt":"Bisakah Anda membungkusnya sebagai hadiah?"},{"fr":"Ce tissu fera un beau souvenir de Lombok.","tgt":"Kain ini akan menjadi kenang-kenangan yang indah dari Lombok."}]},{"title":"Réserver le bateau vers Komodo","phrases":[{"fr":"Nous voulons réserver le bateau de Lombok à Komodo.","tgt":"Kami ingin memesan kapal dari Lombok ke Komodo."},{"fr":"Le voyage dure quatre jours et trois nuits.","tgt":"Perjalanannya empat hari tiga malam."},{"fr":"Les repas sont-ils compris dans le prix ?","tgt":"Apakah makanan sudah termasuk dalam harga?"},{"fr":"Oui, et l'équipement de snorkeling aussi.","tgt":"Ya, termasuk juga peralatan snorkeling."},{"fr":"Il reste deux places en cabine privée.","tgt":"Masih ada dua tempat di kabin pribadi."},{"fr":"Sinon, on dort sur le pont avec les autres.","tgt":"Kalau tidak, kita tidur di dek bersama yang lain."},{"fr":"Je préfère payer un peu plus cher pour la cabine.","tgt":"Saya lebih suka membayar sedikit lebih mahal untuk kabin."},{"fr":"Faut-il verser un acompte aujourd'hui ?","tgt":"Apakah saya harus membayar uang muka hari ini?"},{"fr":"Voici votre reçu, gardez-le bien.","tgt":"Ini kuitansi Anda, tolong disimpan baik-baik."},{"fr":"Le bateau part après-demain, très tôt le matin.","tgt":"Kapalnya berangkat lusa, pagi-pagi sekali."}]},{"title":"Les escales du bateau","phrases":[{"fr":"La cascade de l'île de Moyo est l'endroit le plus frais du voyage.","tgt":"Air terjun di Pulau Moyo adalah tempat paling sejuk dalam perjalanan ini."},{"fr":"Notre capitaine est le plus expérimenté de la compagnie.","tgt":"Kapten kami adalah yang paling berpengalaman di perusahaan ini."},{"fr":"Quelle est la plus belle île de la région ?","tgt":"Pulau mana yang paling indah di daerah ini?"},{"fr":"Le lac de Satonda est le plus calme que j'aie jamais vu.","tgt":"Danau Satonda adalah danau paling tenang yang pernah saya lihat."},{"fr":"Le cuisinier du bord fait le meilleur sambal que j'aie goûté.","tgt":"Juru masak kapal membuat sambal paling enak yang pernah saya coba."},{"fr":"La nuit, il y a bien plus d'étoiles qu'en ville.","tgt":"Pada malam hari, bintangnya jauh lebih banyak daripada di kota."},{"fr":"Le moment le plus fort, c'était de voir les dauphins à l'aube.","tgt":"Momen paling seru adalah saat kami melihat lumba-lumba waktu fajar."},{"fr":"Je dors sur le pont, c'est l'endroit le plus aéré.","tgt":"Saya tidur di dek, karena tempat itu paling berangin."},{"fr":"Les vagues sont plus hautes cet après-midi.","tgt":"Ombaknya lebih tinggi sore ini."},{"fr":"Le plus dur, ce sera de quitter ce bateau.","tgt":"Yang paling berat nanti adalah meninggalkan kapal ini."}],"tip":{"title":"« Paling » : le superlatif","example":"Quelle est la plus belle île de la région ? — Pulau mana yang <b>paling</b> indah di daerah ini?","body":"Pour dire le plus, il suffit de placer « paling » devant l'adjectif : « indah » veut dire beau, « paling indah » le plus beau. Dans « pulau mana yang paling indah », on entend île, laquelle, qui, le plus, beau : quelle est l'île la plus belle. Pas d'article ni d'accord à gérer, « paling enak » sert pour le meilleur plat comme pour la meilleure soupe. Pour préciser le cadre, on ajoute « di », dans, ou « yang pernah saya lihat », que j'aie jamais vu. Vous entendrez aussi le préfixe « ter- » collé à l'adjectif, comme dans « terbaik », le meilleur, mais « paling » reste le plus simple à l'oral. Pour retenir, pensez à un escalier : « lebih », plus, c'est une marche, et « paling », c'est le sommet.","lit":"île · laquelle · qui · le plus · beau · dans · région · ce","say":{"Paling":"Paling","paling":"paling","indah":"indah","paling indah":"paling indah","pulau mana yang paling indah":"pulau mana yang paling indah","paling enak":"paling enak","di":"di","yang pernah saya lihat":"yang pernah saya lihat","terbaik":"terbaik","lebih":"lebih","ter-":"ter"}}},{"title":"Arrivée à Labuan Bajo","phrases":[{"fr":"Nous arrivons enfin au port de Labuan Bajo.","tgt":"Akhirnya kami tiba di pelabuhan Labuan Bajo."},{"fr":"La ville est construite sur une colline face à la mer.","tgt":"Kota ini dibangun di atas bukit yang menghadap ke laut."},{"fr":"Notre hôtel est à cinq minutes à pied du port.","tgt":"Hotel kami lima menit jalan kaki dari pelabuhan."},{"fr":"Avez-vous une chambre avec vue sur la baie ?","tgt":"Apakah ada kamar dengan pemandangan ke teluk?"},{"fr":"J'ai réservé au nom de Martin.","tgt":"Saya sudah memesan atas nama Martin."},{"fr":"La climatisation ne marche pas dans notre chambre.","tgt":"AC di kamar kami tidak berfungsi."},{"fr":"J'envoie quelqu'un tout de suite.","tgt":"Saya akan segera mengirim petugas ke sana."},{"fr":"Y a-t-il un distributeur de billets près d'ici ?","tgt":"Apakah ada ATM di dekat sini?"},{"fr":"Le soir, tout le monde se retrouve sur le port.","tgt":"Pada malam hari, semua orang berkumpul di pelabuhan."},{"fr":"On boit un jus de fruits en regardant les bateaux.","tgt":"Kami minum jus buah sambil memandang kapal-kapal."}]},{"title":"Les dragons de Komodo","phrases":[{"fr":"Un ranger nous accompagne pendant toute la visite.","tgt":"Seorang ranger menemani kami selama kunjungan."},{"fr":"Restez toujours derrière moi, s'il vous plaît.","tgt":"Tolong selalu tetap di belakang saya."},{"fr":"Le dragon de Komodo peut courir très vite.","tgt":"Komodo bisa berlari sangat cepat."},{"fr":"Regardez, il y en a un sous cet arbre !","tgt":"Lihat, ada seekor di bawah pohon itu!"},{"fr":"Ces lézards géants ne vivent que dans ces îles.","tgt":"Kadal raksasa ini hanya hidup di pulau-pulau ini."},{"fr":"Ils peuvent rester immobiles pendant des heures.","tgt":"Mereka bisa diam tanpa bergerak selama berjam-jam."},{"fr":"Ne faites pas de bruit et ne courez pas.","tgt":"Jangan berisik dan jangan berlari."},{"fr":"Le ranger tient un long bâton fourchu.","tgt":"Ranger itu memegang tongkat panjang bercabang."},{"fr":"Combien de dragons vivent sur l'île de Rinca ?","tgt":"Berapa ekor komodo yang hidup di Pulau Rinca?"},{"fr":"Environ un millier, d'après le ranger.","tgt":"Sekitar seribu ekor, kata ranger itu."}]},{"title":"Padar et la plage rose","phrases":[{"fr":"Il faut monter tôt pour éviter la chaleur.","tgt":"Kita harus naik pagi-pagi untuk menghindari panas."},{"fr":"L'escalier vers le sommet de Padar est très raide.","tgt":"Tangga ke puncak Pulau Padar sangat curam."},{"fr":"D'en haut, on voit trois baies différentes.","tgt":"Dari atas, kita bisa melihat tiga teluk yang berbeda."},{"fr":"Chaque baie a une plage d'une couleur différente.","tgt":"Setiap teluk punya pantai dengan warna yang berbeda."},{"fr":"Le sable de cette plage est vraiment rose.","tgt":"Pasir di pantai ini benar-benar berwarna merah muda."},{"fr":"Cette couleur vient de petits morceaux de corail rouge.","tgt":"Warna itu berasal dari potongan kecil karang merah."},{"fr":"Prenez-nous en photo tous les deux, s'il vous plaît.","tgt":"Tolong fotokan kami berdua."},{"fr":"Il est interdit de rapporter du sable.","tgt":"Dilarang membawa pulang pasir."},{"fr":"Ensuite, on nage avec les raies manta.","tgt":"Setelah itu, kami berenang bersama ikan pari manta."},{"fr":"C'est l'endroit dont je rêvais depuis longtemps.","tgt":"Inilah tempat yang sudah lama saya impikan."}]},{"title":"Un imprévu : la mer est trop agitée","phrases":[{"fr":"Le capitaine annule la sortie à cause des vagues.","tgt":"Kapten membatalkan perjalanan karena ombak besar."},{"fr":"Bien que le ciel soit bleu, la mer est dangereuse.","tgt":"Walaupun langitnya biru, lautnya berbahaya."},{"fr":"Bien qu'il soit déçu, mon ami garde le sourire.","tgt":"Walaupun kecewa, teman saya tetap tersenyum."},{"fr":"Notre vol de retour part dans deux jours.","tgt":"Pesawat pulang kami berangkat dua hari lagi."},{"fr":"Bien que ce soit cher, nous changeons notre billet.","tgt":"Walaupun mahal, kami mengganti tiket kami."},{"fr":"L'agence nous rembourse la moitié du prix.","tgt":"Agen perjalanan mengembalikan setengah dari biayanya."},{"fr":"On passe la journée à se promener en ville.","tgt":"Kami menghabiskan hari dengan berjalan-jalan di kota."},{"fr":"Bien qu'il bruine, le marché reste animé.","tgt":"Walaupun gerimis, pasarnya tetap ramai."},{"fr":"Ce n'est pas grave, ça fait partie du voyage.","tgt":"Tidak apa-apa, ini bagian dari perjalanan."},{"fr":"Bien qu'on ait raté les raies manta, la journée a été agréable.","tgt":"Walaupun kami tidak melihat ikan pari manta, hari ini tetap menyenangkan."}],"tip":{"title":"« Walaupun » : bien que","example":"Bien que le ciel soit bleu, la mer est dangereuse. — <b>Walaupun</b> langitnya biru, lautnya berbahaya.","body":"« Walaupun » signifie bien que ou même si, et se place en tête de la première partie de la phrase. « Walaupun langitnya biru, lautnya berbahaya » se décompose en bien que, le ciel, bleu, la mer, dangereuse. Bonne nouvelle : pas de subjonctif, pas de verbe être, la phrase reste toute simple. Dans la seconde partie, on ajoute souvent « tetap », qui veut dire quand même : « walaupun gerimis, pasarnya tetap ramai », même s'il bruine, le marché reste animé. On entend aussi « meskipun », qui veut dire exactement la même chose, et la forme courte « walau » dans la conversation. Prononcez « wa-lau-poun », en trois syllabes : en indonésien, la lettre « u » se dit toujours « ou ».","lit":"bien que · ciel-le · bleu · mer-la · dangereux","say":{"Walaupun":"Walaupun","Walaupun langitnya biru, lautnya berbahaya":"Walaupun langitnya biru, lautnya berbahaya","tetap":"tetap","walaupun gerimis, pasarnya tetap ramai":"walaupun gerimis, pasarnya tetap ramai","meskipun":"meskipun","walau":"walau","u":"u"}}},{"title":"Un téléphone oublié","phrases":[{"fr":"Je crois que j'ai oublié mon téléphone sur le bateau.","tgt":"Sepertinya telepon saya ketinggalan di kapal."},{"fr":"Pouvez-vous appeler le capitaine pour moi ?","tgt":"Bisakah Anda menelepon kapten untuk saya?"},{"fr":"Il est noir, avec une coque bleue.","tgt":"Warnanya hitam, dengan casing biru."},{"fr":"Je m'en suis servi pour la dernière fois à Padar.","tgt":"Terakhir kali saya memakainya di Padar."},{"fr":"Un membre de l'équipage l'a retrouvé sous un banc.","tgt":"Salah satu awak kapal menemukannya di bawah bangku."},{"fr":"Il va l'apporter au port ce soir.","tgt":"Dia akan membawanya ke pelabuhan nanti malam."},{"fr":"Je ne sais pas comment vous remercier.","tgt":"Saya tidak tahu bagaimana harus berterima kasih kepada Anda."},{"fr":"Voici un petit pourboire pour l'équipage.","tgt":"Ini sedikit uang tip untuk para awak kapal."},{"fr":"La prochaine fois, je ferai plus attention à mes affaires.","tgt":"Lain kali, saya akan lebih berhati-hati dengan barang-barang saya."},{"fr":"Heureusement, les gens ici sont très honnêtes.","tgt":"Untunglah, orang-orang di sini sangat jujur."}]},{"title":"À la pharmacie : mal de mer et coups de soleil","phrases":[{"fr":"J'ai eu le mal de mer pendant toute la traversée.","tgt":"Saya mabuk laut selama penyeberangan."},{"fr":"Avez-vous quelque chose contre le mal de mer ?","tgt":"Apakah ada obat untuk mabuk laut?"},{"fr":"Prenez ce comprimé une demi-heure avant d'embarquer.","tgt":"Minumlah tablet ini setengah jam sebelum naik kapal."},{"fr":"Mes épaules sont toutes rouges à cause du soleil.","tgt":"Bahu saya merah sekali karena matahari."},{"fr":"Ce gel à l'aloe vera va apaiser la brûlure.","tgt":"Gel lidah buaya ini akan meredakan rasa perihnya."},{"fr":"Je me suis fait piquer à la jambe par une méduse.","tgt":"Kaki saya tersengat ubur-ubur."},{"fr":"Rincez avec du vinaigre, pas avec de l'eau douce.","tgt":"Bilas dengan cuka, jangan dengan air tawar."},{"fr":"Buvez beaucoup d'eau et restez à l'ombre.","tgt":"Minumlah banyak air dan tetaplah di tempat teduh."},{"fr":"Je vous dois combien pour tout ça ?","tgt":"Berapa semuanya?"},{"fr":"Je me sens déjà beaucoup mieux, merci.","tgt":"Saya sudah merasa jauh lebih baik, terima kasih."}]},{"title":"Le poisson grillé du port","phrases":[{"fr":"Chaque soir, des stands de poisson s'installent sur le port.","tgt":"Setiap malam, warung-warung ikan dibuka di pelabuhan."},{"fr":"Choisissez votre poisson directement sur la glace.","tgt":"Silakan pilih ikan Anda langsung dari atas es."},{"fr":"Ce vivaneau rouge a été pêché ce matin.","tgt":"Ikan kakap merah ini ditangkap tadi pagi."},{"fr":"Il se vend au poids : combien le kilo ?","tgt":"Ikan ini dijual per kilo. Berapa harga sekilonya?"},{"fr":"Grillé, avec du sambal, s'il vous plaît.","tgt":"Tolong dibakar, pakai sambal."},{"fr":"Pas trop pimenté pour mon amie.","tgt":"Untuk teman saya, jangan terlalu pedas."},{"fr":"On prend aussi des calamars et du riz blanc.","tgt":"Kami tambah cumi-cumi dan nasi putih juga."},{"fr":"Le poisson est parfaitement grillé, la chair est tendre.","tgt":"Ikannya dibakar dengan sempurna dan dagingnya lembut."},{"fr":"On mange sur des tables en plastique face aux bateaux.","tgt":"Kami makan di meja plastik sambil menghadap kapal-kapal."},{"fr":"Ce dîner tout simple restera mon meilleur souvenir.","tgt":"Makan malam sederhana ini akan menjadi kenangan terbaik saya."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"De Lombok à Komodo, quel voyage incroyable !","tgt":"Dari Lombok sampai Komodo, perjalanan yang luar biasa!"},{"fr":"Maintenant, je sais réserver un bateau en indonésien.","tgt":"Sekarang saya bisa memesan kapal dalam bahasa Indonesia."},{"fr":"Je peux aussi louer un scooter et négocier un prix.","tgt":"Saya juga bisa menyewa motor dan menawar harga."},{"fr":"J'ose maintenant poser des questions aux gens du coin.","tgt":"Sekarang saya berani bertanya kepada orang setempat."},{"fr":"Quand je ne comprends pas, je demande qu'on répète.","tgt":"Kalau saya tidak mengerti, saya minta orang mengulanginya."},{"fr":"Les gens sont ravis quand on parle leur langue.","tgt":"Orang-orang sangat senang kalau kita berbicara dalam bahasa mereka."},{"fr":"Mon indonésien est encore loin d'être parfait.","tgt":"Bahasa Indonesia saya masih jauh dari sempurna."},{"fr":"Mais je me débrouille de mieux en mieux.","tgt":"Tetapi saya makin lama makin lancar."},{"fr":"Je suis prêt à discuter encore plus.","tgt":"Saya sudah siap untuk mengobrol lebih banyak."},{"fr":"À bientôt pour la suite du voyage !","tgt":"Sampai jumpa di perjalanan berikutnya!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Une soirée chez Dimas","phrases":[{"fr":"Entre, fais comme chez toi !","tgt":"Masuk, anggap saja rumah sendiri!"},{"fr":"Merci de m'avoir invité ce soir.","tgt":"Terima kasih sudah mengundang aku malam ini."},{"fr":"Tout le monde est déjà arrivé ?","tgt":"Semua orang sudah datang?"},{"fr":"Rini arrive un peu plus tard, elle est encore au bureau.","tgt":"Rini datang agak terlambat, dia masih di kantor."},{"fr":"Tu veux boire quelque chose de frais ?","tgt":"Kamu mau minum yang dingin?"},{"fr":"J'ai apporté des beignets de banane pour tout le monde.","tgt":"Aku membawa pisang goreng untuk semua."},{"fr":"Oh, c'est gentil, justement j'ai faim !","tgt":"Wah, baik sekali, kebetulan aku lapar!"},{"fr":"Assieds-toi ici, près du ventilateur.","tgt":"Duduk di sini saja, dekat kipas angin."},{"fr":"Il fait vraiment chaud ce soir à Surabaya.","tgt":"Malam ini Surabaya panas sekali."},{"fr":"On commence à manger dès que Rini arrive.","tgt":"Kita mulai makan kalau Rini sudah datang."}]},{"title":"Les potins entre amis","phrases":[{"fr":"Pourquoi tu ne m'as rien raconté ?","tgt":"Kok kamu tidak cerita ke aku?"},{"fr":"Raconte-moi, allez !","tgt":"Cerita dong!"},{"fr":"Au fait, c'est qui, son nouveau copain ?","tgt":"Pacar barunya siapa sih?"},{"fr":"Il est gentil, je t'assure.","tgt":"Dia baik kok."},{"fr":"Mais c'est évident, tout le monde le sait !","tgt":"Ya jelas dong, semua orang tahu!"},{"fr":"Comment ça, tu ne le connais pas ?","tgt":"Kok kamu tidak kenal dia?"},{"fr":"Ils se sont rencontrés où, au fait ?","tgt":"Mereka bertemu di mana sih?"},{"fr":"Dans un petit café près du campus.","tgt":"Di kafe kecil dekat kampus."},{"fr":"Ne le répète à personne, d'accord ?","tgt":"Jangan bilang siapa-siapa, ya?"},{"fr":"Bien sûr, tu me connais !","tgt":"Tentu dong, kamu kenal aku!"}],"tip":{"title":"Les petits mots de fin entre amis : « kok », « dong », « sih »","example":"Raconte-moi, allez ! — Cerita <b>dong</b>!","body":"Entre amis, les Indonésiens colorent leurs phrases avec de tout petits mots, un peu comme nos « allez », « hein » ou « au fait ». « Dong » ajoute une insistance amicale : « cerita dong », mot à mot « raconter allez », veut dire « raconte-moi, allez ! ». « Kok » exprime la surprise, comme « comment ça ? », en début de phrase : « kok kamu tidak kenal dia ? », et en fin de phrase il rassure : « dia baik kok », il est gentil, je t'assure. « Sih » adoucit une question, comme notre « au fait » : « siapa sih ? », c'est qui, au fait ? Dites-les courts et légers, sans les accentuer, c'est la mélodie de la phrase qui porte l'émotion. Pour retenir : « dong » pousse, « kok » s'étonne ou rassure, « sih » arrondit.","lit":"raconter · [insistance]","say":{"kok":"kok","dong":"dong","sih":"sih","Dong":"Dong","cerita dong":"cerita dong","Kok":"Kok","kok kamu tidak kenal dia ?":"kok kamu tidak kenal dia?","dia baik kok":"dia baik kok","Sih":"Sih","siapa sih ?":"siapa sih?"}}},{"title":"Choisir une sortie du samedi","phrases":[{"fr":"On va où samedi soir ?","tgt":"Sabtu malam kita mau ke mana?"},{"fr":"On pourrait se promener au bord de la rivière Kalimas.","tgt":"Kita bisa jalan-jalan di tepi Kali Mas."},{"fr":"Je préfère aller au centre commercial, il y fait frais.","tgt":"Aku lebih suka ke mal, di sana sejuk."},{"fr":"Le week-end, il y a toujours une foule énorme là-bas.","tgt":"Kalau akhir pekan, di sana selalu ramai sekali."},{"fr":"Et si on allait plutôt au cinéma ?","tgt":"Bagaimana kalau kita menonton film di bioskop saja?"},{"fr":"Bonne idée, il y a un nouveau film d'horreur.","tgt":"Ide bagus, ada film horor baru."},{"fr":"Moi, les films d'horreur me font trop peur !","tgt":"Aku terlalu takut menonton film horor!"},{"fr":"Alors c'est toi qui choisis le film.","tgt":"Kalau begitu, kamu yang memilih filmnya."},{"fr":"Je réserve les places sur mon téléphone.","tgt":"Aku memesan tiketnya lewat ponsel."},{"fr":"Rendez-vous devant le cinéma à sept heures.","tgt":"Kita bertemu di depan bioskop jam tujuh."}]},{"title":"Les séries du moment","phrases":[{"fr":"Tu suis quelle série depuis quelques semaines ?","tgt":"Beberapa minggu ini kamu menonton serial apa?"},{"fr":"Une série indonésienne sur une famille de Surabaya.","tgt":"Serial Indonesia tentang sebuah keluarga di Surabaya."},{"fr":"Hier soir, j'ai regardé trois épisodes d'un coup.","tgt":"Tadi malam aku menonton tiga episode sekaligus."},{"fr":"Surtout, ne me dévoile pas la fin !","tgt":"Jangan ceritakan akhirnya, ya!"},{"fr":"Celle qui joue le rôle principal est excellente.","tgt":"Pemeran utamanya bagus sekali."},{"fr":"L'histoire devient de plus en plus captivante.","tgt":"Ceritanya makin lama makin menarik."},{"fr":"La deuxième saison sort le mois prochain.","tgt":"Musim keduanya keluar bulan depan."},{"fr":"Tu as une série drôle à me conseiller ?","tgt":"Ada serial lucu yang bisa kamu sarankan?"},{"fr":"Je regarde toujours un épisode avant de dormir.","tgt":"Aku selalu menonton satu episode sebelum tidur."},{"fr":"On pourrait la regarder ensemble ce week-end.","tgt":"Kita bisa menontonnya bersama akhir pekan ini."}]},{"title":"Un concert à Surabaya","phrases":[{"fr":"Tu viens au concert samedi ?","tgt":"Kamu ikut ke konser hari Sabtu?"},{"fr":"Peut-être, je dois d'abord finir mon travail.","tgt":"Mungkin, aku harus menyelesaikan pekerjaanku dulu."},{"fr":"Le groupe va peut-être jouer jusqu'à minuit.","tgt":"Band itu mungkin bermain sampai tengah malam."},{"fr":"Il y aura peut-être énormément de monde.","tgt":"Mungkin nanti ramai sekali."},{"fr":"Les billets coûtent cent cinquante mille roupies.","tgt":"Tiketnya seratus lima puluh ribu rupiah."},{"fr":"C'est un peu cher, mais on ne le regrettera pas.","tgt":"Agak mahal, tapi tidak rugi."},{"fr":"Budi pourra peut-être nous emmener en voiture.","tgt":"Mungkin Budi bisa mengantar kita naik mobil."},{"fr":"Sinon, on prend simplement un taxi.","tgt":"Kalau tidak, kita naik taksi saja."},{"fr":"J'adore chanter avec tout le public.","tgt":"Aku suka sekali bernyanyi bersama semua penonton."},{"fr":"J'arriverai peut-être un peu en retard.","tgt":"Mungkin aku datang agak terlambat."}],"tip":{"title":"« Mungkin » : peut-être","example":"Peut-être, je dois d'abord finir mon travail. — <b>Mungkin</b>, aku harus menyelesaikan pekerjaanku dulu.","body":"Pour dire « peut-être », on utilise « mungkin », qui se prononce « moung-kine », en appuyant doucement sur la première syllabe. Il peut répondre tout seul à une question, comme en français : « Kamu ikut ? Mungkin ! », tu viens ? Peut-être ! Il se place aussi en tête de phrase, sans aucun « que » : « mungkin aku datang agak terlambat », mot à mot « peut-être je arriver un peu en retard ». On peut même le glisser juste avant le verbe : « Budi mungkin bisa », Budi pourra peut-être. Comme le verbe ne change jamais, « mungkin » suffit à rendre la phrase hésitante, au présent comme au futur. Astuce : pensez à « mon kine », mon kiné viendra peut-être.","lit":"peut-être · je · devoir · finir · travail-mon · d'abord","say":{"Mungkin":"Mungkin","mungkin":"mungkin","Kamu ikut ? Mungkin !":"Kamu ikut? Mungkin!","mungkin aku datang agak terlambat":"mungkin aku datang agak terlambat","Budi mungkin bisa":"Budi mungkin bisa"}}},{"title":"Le rawon du warung","phrases":[{"fr":"Tu as déjà goûté le rawon ?","tgt":"Kamu pernah mencoba rawon?"},{"fr":"C'est une soupe de bœuf toute noire, typique de Surabaya.","tgt":"Itu sup daging sapi berwarna hitam, khas Surabaya."},{"fr":"Sa couleur vient d'une noix spéciale, le kluwek.","tgt":"Warnanya berasal dari buah kluwek."},{"fr":"Le meilleur rawon se trouve dans les petits warungs.","tgt":"Rawon paling enak ada di warung kecil."},{"fr":"On le sert avec du riz et des germes de soja.","tgt":"Rawon disajikan dengan nasi dan tauge."},{"fr":"N'oublie pas le sambal, mais attention, ça pique !","tgt":"Jangan lupa sambalnya, tapi hati-hati, pedas!"},{"fr":"J'ajoute juste un tout petit peu de sambal.","tgt":"Aku menambahkan sedikit sambal saja."},{"fr":"Ce rawon est encore meilleur que celui de ma mère.","tgt":"Rawon ini lebih enak daripada buatan ibuku."},{"fr":"Surtout, ne le dis pas à ta mère !","tgt":"Jangan bilang ke ibumu, ya!"},{"fr":"On revient ici la semaine prochaine.","tgt":"Minggu depan kita kembali ke sini."}]},{"title":"Le jus d'avocat","phrases":[{"fr":"Il fait trop chaud, allons boire un jus d'avocat !","tgt":"Panas sekali, ayo minum jus alpukat!"},{"fr":"En France, l'avocat se mange plutôt salé.","tgt":"Di Prancis, alpukat biasanya dimakan asin."},{"fr":"Ici, on le boit sucré, avec du chocolat.","tgt":"Di sini, alpukat diminum manis dengan cokelat."},{"fr":"Le vendeur mixe l'avocat avec du lait et de la glace.","tgt":"Penjualnya memblender alpukat dengan susu dan es."},{"fr":"Tu en veux un petit ou un grand ?","tgt":"Kamu mau yang kecil atau yang besar?"},{"fr":"Un grand, s'il te plaît, pas trop sucré.","tgt":"Yang besar, tolong jangan terlalu manis."},{"fr":"C'est plus épais qu'un jus de fruits normal.","tgt":"Ini lebih kental daripada jus biasa."},{"fr":"Je n'ai jamais rien bu d'aussi bon.","tgt":"Aku belum pernah minum yang seenak ini."},{"fr":"Je te dois combien pour les deux jus ?","tgt":"Aku harus bayar berapa untuk dua jus ini?"},{"fr":"Laisse, c'est moi qui t'invite aujourd'hui.","tgt":"Biar aku yang traktir hari ini."}]},{"title":"Une soirée annulée","phrases":[{"fr":"Désolé, je ne pourrai pas venir ce soir.","tgt":"Maaf, aku tidak bisa datang malam ini."},{"fr":"Qu'est-ce qui se passe ? Tout va bien ?","tgt":"Ada apa? Semuanya baik-baik saja?"},{"fr":"Mon chef m'a demandé de travailler tard.","tgt":"Bosku memintaku bekerja sampai malam."},{"fr":"Dommage, on avait tout préparé.","tgt":"Sayang sekali, kita sudah menyiapkan semuanya."},{"fr":"Je suis vraiment navré de vous décevoir.","tgt":"Aku benar-benar minta maaf sudah mengecewakan kalian."},{"fr":"Ce n'est pas grave, ce sera pour une prochaine fois.","tgt":"Tidak apa-apa, lain kali saja."},{"fr":"On peut repousser la soirée à vendredi.","tgt":"Kita bisa mengundurkan acaranya ke hari Jumat."},{"fr":"Vendredi, ça me va parfaitement.","tgt":"Hari Jumat cocok sekali untukku."},{"fr":"Je t'envoie un message demain pour confirmer.","tgt":"Besok aku mengirim pesan untuk memastikan."},{"fr":"Ne travaille pas trop, repose-toi un peu.","tgt":"Jangan terlalu banyak bekerja, istirahatlah sebentar."}]},{"title":"Des nouvelles d'un ancien camarade","phrases":[{"fr":"Devine qui j'ai croisé au marché hier !","tgt":"Tebak, kemarin aku bertemu siapa di pasar!"},{"fr":"Andi, notre camarade du lycée !","tgt":"Andi, teman SMA kita!"},{"fr":"Ça fait plus de dix ans que je ne l'ai pas vu.","tgt":"Sudah lebih dari sepuluh tahun aku tidak bertemu dia."},{"fr":"Il a beaucoup changé ?","tgt":"Dia banyak berubah?"},{"fr":"Il porte des lunettes et il a maintenant une barbe.","tgt":"Dia memakai kacamata dan sekarang berjenggot."},{"fr":"Il travaille comme cuisinier dans un grand hôtel.","tgt":"Dia bekerja sebagai koki di hotel besar."},{"fr":"Il s'est marié l'année dernière.","tgt":"Dia menikah tahun lalu."},{"fr":"Il m'a demandé de tes nouvelles.","tgt":"Dia menanyakan kabarmu."},{"fr":"Tu lui as donné mon numéro ?","tgt":"Kamu memberikan nomorku kepadanya?"},{"fr":"On devrait organiser un dîner avec lui.","tgt":"Sebaiknya kita mengadakan makan malam dengan dia."}]},{"title":"Préparer le mariage de ma cousine","phrases":[{"fr":"Ma cousine Dewi se marie le mois prochain.","tgt":"Sepupuku Dewi menikah bulan depan."},{"fr":"Toute la famille aide à préparer la fête.","tgt":"Seluruh keluarga membantu menyiapkan pestanya."},{"fr":"La réception aura lieu dans une grande salle.","tgt":"Resepsinya diadakan di gedung besar."},{"fr":"Ils ont invité presque mille personnes !","tgt":"Mereka mengundang hampir seribu orang!"},{"fr":"En Indonésie, les mariages sont souvent immenses.","tgt":"Di Indonesia, pesta pernikahan sering sangat besar."},{"fr":"Ma tante s'occupe du repas et des gâteaux.","tgt":"Tanteku mengurus makanan dan kuenya."},{"fr":"Tous les cousins porteront le même batik.","tgt":"Semua sepupu akan memakai batik yang sama."},{"fr":"Tu veux bien m'aider à choisir mon batik ?","tgt":"Kamu mau membantuku memilih batik?"},{"fr":"Celui-ci est plus élégant que l'autre.","tgt":"Yang ini lebih elegan daripada yang itu."},{"fr":"Toi aussi, tu es invité, bien sûr.","tgt":"Kamu juga diundang, tentu saja."}]},{"title":"Le jour du mariage","phrases":[{"fr":"Les mariés portent des habits traditionnels javanais.","tgt":"Pengantinnya memakai pakaian adat Jawa."},{"fr":"Ils vont vraiment bien ensemble !","tgt":"Mereka serasi sekali!"},{"fr":"Les invités font la queue pour féliciter les mariés.","tgt":"Para tamu antre untuk memberi selamat kepada pengantin."},{"fr":"Il faut aussi se faire photographier avec eux sur l'estrade.","tgt":"Kita juga harus berfoto dengan mereka di panggung."},{"fr":"Le buffet est énorme, il y a de tout.","tgt":"Prasmanannya besar sekali, ada macam-macam."},{"fr":"Goûte les brochettes de chèvre, elles sont délicieuses.","tgt":"Coba sate kambingnya, enak sekali."},{"fr":"Un chanteur interprète des chansons d'amour.","tgt":"Seorang penyanyi membawakan lagu-lagu cinta."},{"fr":"Même ma grand-mère s'est mise à danser !","tgt":"Nenekku pun mulai berjoget!"},{"fr":"Je n'ai jamais vu un mariage avec autant de monde.","tgt":"Aku belum pernah melihat pesta pernikahan seramai ini."},{"fr":"Quelle belle journée pour toute la famille !","tgt":"Hari yang indah untuk seluruh keluarga!"}]},{"title":"Les rumeurs du quartier","phrases":[{"fr":"Il paraît qu'un nouveau café va ouvrir dans notre rue.","tgt":"Katanya akan ada kafe baru di jalan kita."},{"fr":"Il paraît que leur café glacé est excellent.","tgt":"Katanya es kopinya enak sekali."},{"fr":"Qui t'a dit ça ?","tgt":"Siapa yang bilang begitu?"},{"fr":"C'est la voisine du bout de la rue qui me l'a raconté.","tgt":"Tetangga di ujung jalan yang menceritakannya."},{"fr":"Il paraît aussi que le patron est un ancien chanteur.","tgt":"Katanya pemiliknya juga bekas penyanyi."},{"fr":"Tu crois tout ce qu'elle raconte ?","tgt":"Kamu percaya semua yang dia ceritakan?"},{"fr":"Selon elle, Rina va déménager à Bali.","tgt":"Katanya Rina mau pindah ke Bali."},{"fr":"Ah bon ? Rina ne m'a rien dit.","tgt":"Oh ya? Rina tidak bilang apa-apa ke aku."},{"fr":"Il vaut mieux lui poser la question directement.","tgt":"Lebih baik kita tanya langsung kepadanya."},{"fr":"Les rumeurs se répandent vite dans ce quartier !","tgt":"Gosip cepat sekali menyebar di kampung ini!"}],"tip":{"title":"« Katanya » : il paraît que","example":"Il paraît que leur café glacé est excellent. — <b>Katanya</b> es kopinya enak sekali.","body":"Pour rapporter une information qu'on a entendue sans en être sûr, on commence la phrase par « katanya », qui se dit « ka-ta-nia ». Il vient de « kata », le mot, la parole, avec « nya » qui veut dire « son » ou « sa » : littéralement « sa parole », donc « il paraît que » ou « d'après lui ». On le pose simplement devant la phrase, sans rien changer d'autre : « katanya es kopinya enak sekali », mot à mot « il paraît glace café-leur bon très ». Selon le contexte, il peut aussi vouloir dire « selon elle » : « katanya Rina mau pindah », d'après elle, Rina va déménager. C'est le mot parfait pour les potins, car il vous protège : ce n'est pas vous qui le dites !","lit":"il paraît · glace · café-leur · bon · très","say":{"Katanya":"Katanya","katanya":"katanya","kata":"kata","katanya es kopinya enak sekali":"katanya es kopinya enak sekali","katanya Rina mau pindah":"katanya Rina mau pindah","nya":"nya"}}},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais près du port.","tgt":"Waktu aku kecil, aku tinggal di dekat pelabuhan."},{"fr":"Tous les après-midi, je regardais passer les bateaux.","tgt":"Setiap sore aku melihat kapal-kapal lewat."},{"fr":"Mon grand-père me racontait des histoires de pêcheurs.","tgt":"Kakekku sering menceritakan kisah para nelayan."},{"fr":"On faisait voler des cerfs-volants dans les rizières.","tgt":"Kami bermain layang-layang di sawah."},{"fr":"Tu te souviens de notre première école ?","tgt":"Kamu ingat sekolah pertama kita?"},{"fr":"Bien sûr, la maîtresse était très sévère.","tgt":"Tentu, ibu gurunya galak sekali."},{"fr":"Mais le vendredi, elle nous donnait des bonbons.","tgt":"Tapi setiap hari Jumat dia memberi kami permen."},{"fr":"Repenser à tout ça me rend un peu nostalgique.","tgt":"Mengingat semua itu membuatku agak rindu masa kecil."},{"fr":"L'enfance passe tellement vite.","tgt":"Masa kecil cepat sekali berlalu."},{"fr":"On devrait retourner voir notre ancienne école.","tgt":"Kita harus mengunjungi sekolah lama kita lagi."}]},{"title":"Une soirée karaoké","phrases":[{"fr":"Ce soir, c'est karaoké !","tgt":"Malam ini kita karaoke!"},{"fr":"Je chante toujours en dansant.","tgt":"Aku selalu bernyanyi sambil berjoget."},{"fr":"Rina lit les paroles tout en buvant son thé.","tgt":"Rina membaca liriknya sambil minum teh."},{"fr":"On choisit les chansons en grignotant des chips.","tgt":"Kita memilih lagu sambil makan keripik."},{"fr":"Qui chante la première chanson ?","tgt":"Siapa yang menyanyikan lagu pertama?"},{"fr":"Toi, tu as la plus belle voix de la bande !","tgt":"Suaramu paling bagus di antara kita!"},{"fr":"Arrête, je chante faux !","tgt":"Ah, jangan begitu, suaraku sumbang!"},{"fr":"Budi éclate de rire en tenant le micro.","tgt":"Budi tertawa sambil memegang mikrofon."},{"fr":"Impossible de chanter en riant !","tgt":"Tidak bisa bernyanyi sambil tertawa!"},{"fr":"On prend encore une heure ?","tgt":"Kita pesan satu jam lagi?"}],"tip":{"title":"« Sambil » : faire deux choses à la fois","example":"Je chante toujours en dansant. — Aku selalu bernyanyi <b>sambil</b> berjoget.","body":"Quand on fait deux choses en même temps, le français dit « en » ou « tout en » : je chante en dansant. L'indonésien utilise « sambil », qui se prononce « sam-bil », placé entre les deux actions. On dit d'abord l'action principale, puis « sambil », puis l'action secondaire : « aku bernyanyi sambil berjoget », mot à mot « je chanter tout en danser ». Les verbes ne changent pas, il suffit de les poser de part et d'autre : « makan sambil menonton », manger en regardant la télé, « tertawa sambil memegang mikrofon », rire en tenant le micro. Astuce : imaginez « sambil » comme un pont entre deux gestes, ce qu'on fait avant le pont est le plus important.","lit":"je · toujours · chanter · tout en · danser","say":{"Sambil":"Sambil","sambil":"sambil","aku bernyanyi sambil berjoget":"aku bernyanyi sambil berjoget","makan sambil menonton":"makan sambil menonton","tertawa sambil memegang mikrofon":"tertawa sambil memegang mikrofon"}}},{"title":"Les rêves de voyage","phrases":[{"fr":"Si j'avais assez d'argent, je ferais le tour de l'Indonésie.","tgt":"Kalau punya cukup uang, aku mau keliling seluruh Indonesia."},{"fr":"Moi, je rêve de voir les dragons de Komodo.","tgt":"Aku ingin sekali melihat komodo."},{"fr":"On pourrait faire de la plongée ensemble à Lombok.","tgt":"Kita bisa menyelam bersama di Lombok."},{"fr":"J'aimerais voir le lever du soleil au mont Bromo.","tgt":"Aku ingin melihat matahari terbit di Gunung Bromo."},{"fr":"C'est à seulement quelques heures de Surabaya.","tgt":"Tempatnya hanya beberapa jam dari Surabaya."},{"fr":"Un jour, j'aimerais aussi découvrir Paris.","tgt":"Suatu hari, aku juga ingin mengunjungi Paris."},{"fr":"Tu me feras visiter ta ville, en France ?","tgt":"Kamu mau mengajakku keliling kotamu di Prancis?"},{"fr":"Avec plaisir, je te montrerai les meilleures boulangeries.","tgt":"Dengan senang hati, aku akan menunjukkan toko roti terbaik."},{"fr":"Il faut commencer à économiser dès maintenant.","tgt":"Kita harus mulai menabung dari sekarang."},{"fr":"Rêver de voyages, ça donne de l'énergie.","tgt":"Bermimpi jalan-jalan membuat kita bersemangat."}]},{"title":"Parler de son travail","phrases":[{"fr":"Alors, ça se passe comment, ton nouveau boulot ?","tgt":"Jadi, bagaimana pekerjaan barumu?"},{"fr":"Mes collègues sont sympas, mais les journées sont longues.","tgt":"Rekan kerjaku ramah, tapi jam kerjanya panjang."},{"fr":"Je commence à huit heures et je finis souvent à six heures.","tgt":"Aku mulai jam delapan dan sering selesai jam enam."},{"fr":"Tu gagnes mieux ta vie qu'avant ?","tgt":"Gajimu lebih besar daripada dulu?"},{"fr":"Un peu, mais je dépense plus pour l'essence.","tgt":"Sedikit, tapi aku menghabiskan lebih banyak uang untuk bensin."},{"fr":"Le bureau est loin de chez moi.","tgt":"Kantornya jauh dari rumahku."},{"fr":"Les embouteillages m'épuisent complètement.","tgt":"Kemacetan membuatku sangat lelah."},{"fr":"Tu pourrais demander à travailler depuis chez toi.","tgt":"Kamu bisa minta bekerja dari rumah."},{"fr":"Bonne idée, j'en parlerai à mon chef.","tgt":"Ide bagus, aku akan membicarakannya dengan atasanku."},{"fr":"L'essentiel, c'est que tu te plaises là-bas.","tgt":"Yang penting kamu senang di sana."}]},{"title":"Se réconcilier après une dispute","phrases":[{"fr":"Tu m'en veux encore ?","tgt":"Kamu masih marah padaku?"},{"fr":"Un peu, tu as oublié mon anniversaire.","tgt":"Sedikit, kamu lupa ulang tahunku."},{"fr":"Je suis vraiment désolé, j'étais débordé.","tgt":"Aku benar-benar minta maaf, aku sibuk sekali."},{"fr":"Ce n'est pas une excuse.","tgt":"Itu bukan alasan."},{"fr":"Tu as raison, je n'aurais pas dû oublier.","tgt":"Kamu benar, seharusnya aku tidak lupa."},{"fr":"Laisse-moi me faire pardonner.","tgt":"Biar aku menebus kesalahanku."},{"fr":"Je t'invite à manger un rawon où tu veux.","tgt":"Aku traktir kamu makan rawon di mana pun kamu mau."},{"fr":"D'accord, mais c'est toi qui conduis !","tgt":"Oke, tapi kamu yang menyetir!"},{"fr":"Je suis content qu'on se soit réconciliés.","tgt":"Aku senang kita sudah berbaikan."},{"fr":"Notre amitié est plus forte qu'une petite dispute.","tgt":"Persahabatan kita lebih kuat daripada pertengkaran kecil."}]},{"title":"Chez les parents de Dimas","phrases":[{"fr":"Bonsoir Monsieur, je suis un ami de Dimas.","tgt":"Selamat malam, Pak, saya teman Dimas."},{"fr":"Bonsoir Madame, merci de me recevoir chez vous.","tgt":"Selamat malam, Bu, terima kasih sudah menerima saya di rumah."},{"fr":"Sari, c'est ta grande sœur ?","tgt":"Mbak Sari itu kakakmu?"},{"fr":"Oui, et voici mon grand frère, Agus.","tgt":"Ya, dan ini kakakku, Mas Agus."},{"fr":"Ravi de te rencontrer, Agus !","tgt":"Senang berkenalan, Mas Agus!"},{"fr":"Madame, votre rawon est délicieux.","tgt":"Bu, rawonnya enak sekali."},{"fr":"Et vous, Monsieur, vous travaillez encore ?","tgt":"Bapak masih bekerja?"},{"fr":"Mademoiselle, deux jus d'avocat, s'il vous plaît !","tgt":"Mbak, jus alpukat dua, ya!"},{"fr":"Excusez-moi, on peut payer ici ?","tgt":"Mas, bisa bayar di sini?"},{"fr":"Monsieur, Madame, je vais rentrer, merci pour tout.","tgt":"Pak, Bu, saya pamit dulu, terima kasih atas semuanya."}],"tip":{"title":"« Mas », « Mbak », « Bapak », « Ibu » : s'adresser aux gens","example":"Madame, votre rawon est délicieux. — <b>Bu</b>, rawonnya enak sekali.","body":"En Indonésie, on n'appelle presque jamais quelqu'un par son seul prénom ou par « tu » : on utilise un petit titre. Pour un homme plus âgé, on dit « Bapak », souvent raccourci en « Pak », et pour une femme plus âgée « Ibu », raccourci en « Bu » : « Bu, rawonnya enak sekali », mot à mot « madame, rawon-le bon très ». Pour quelqu'un de votre âge ou un peu plus âgé, on dit « Mas » pour un homme et « Mbak » pour une femme, deux mots venus du javanais, très courants à Surabaya. Ces titres remplacent même le « vous » : « Bapak masih bekerja ? », mot à mot « monsieur encore travailler ». Pour interpeller un serveur ou une vendeuse, « Mas ! » ou « Mbak ! » est poli et chaleureux. Astuce : dans le doute, choisissez le titre qui vieillit un peu la personne, c'est une marque de respect.","lit":"madame · rawon-le · bon · très","say":{"Mas":"Mas","Mbak":"Mbak","Bapak":"Bapak","Ibu":"Ibu","Pak":"Pak","Bu":"Bu","Bu, rawonnya enak sekali":"Bu, rawonnya enak sekali","Bapak masih bekerja ?":"Bapak masih bekerja?","Mas !":"Mas!","Mbak !":"Mbak!"}}},{"title":"Les projets de l'année prochaine","phrases":[{"fr":"Qu'est-ce que tu as envie de faire l'année prochaine ?","tgt":"Tahun depan kamu mau melakukan apa?"},{"fr":"J'aimerais apprendre à jouer de la guitare.","tgt":"Aku ingin belajar bermain gitar."},{"fr":"Moi, je veux enfin passer mon permis.","tgt":"Kalau aku, akhirnya aku mau membuat SIM."},{"fr":"Si tout va bien, je changerai de travail.","tgt":"Kalau semuanya lancar, aku akan pindah kerja."},{"fr":"Rini veut ouvrir son propre petit warung.","tgt":"Rini ingin membuka warung kecilnya sendiri."},{"fr":"Elle cuisine si bien, ça va forcément marcher !","tgt":"Masakannya enak sekali, pasti berhasil!"},{"fr":"On devrait se fixer un objectif commun.","tgt":"Sebaiknya kita menentukan satu tujuan bersama."},{"fr":"Par exemple, partir tous ensemble à Bali en août.","tgt":"Misalnya, liburan bersama ke Bali bulan Agustus."},{"fr":"Je note tout ça dans mon téléphone.","tgt":"Aku mencatat semuanya di ponselku."},{"fr":"Dans un an, on verra qui a tenu ses promesses !","tgt":"Setahun lagi, kita lihat siapa yang menepati janjinya!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a emmenés dans les soirées de Surabaya.","tgt":"Modul ini membawa kita ke malam-malam di Surabaya."},{"fr":"On sait maintenant raconter des potins avec « kok » et « dong ».","tgt":"Sekarang kita bisa bergosip dengan \"kok\" dan \"dong\"."},{"fr":"Avec « katanya », on rapporte ce qu'on a entendu dire.","tgt":"Dengan \"katanya\", kita menyampaikan apa yang kita dengar."},{"fr":"Avec « sambil », on fait deux choses en même temps.","tgt":"Dengan \"sambil\", kita melakukan dua hal sekaligus."},{"fr":"On sait aussi saluer poliment les parents de nos amis.","tgt":"Kita juga tahu cara menyapa orang tua teman dengan sopan."},{"fr":"Parler indonésien entre amis devient plus naturel.","tgt":"Berbicara bahasa Indonesia dengan teman menjadi lebih alami."},{"fr":"Voilà, ce deuxième niveau touche à sa fin.","tgt":"Nah, tingkat kedua ini hampir selesai."},{"fr":"Le troisième niveau sera plus riche et plus formel.","tgt":"Tingkat ketiga akan lebih kaya dan lebih formal."},{"fr":"Bravo pour tout le chemin parcouru !","tgt":"Selamat atas kemajuanmu sejauh ini!"},{"fr":"Repose-toi bien, et à très vite !","tgt":"Istirahat yang cukup, sampai jumpa lagi!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Indonésie, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"La réunion du lundi","phrases":[{"fr":"La réunion a été déplacée à dix heures.","tgt":"Rapatnya dipindahkan ke jam sepuluh."},{"fr":"Le rapport doit être envoyé avant midi.","tgt":"Laporannya harus dikirim sebelum jam dua belas siang."},{"fr":"Ce sujet sera discuté à la fin de la réunion.","tgt":"Topik ini akan dibahas di akhir rapat."},{"fr":"Le compte rendu a déjà été rédigé par Dewi.","tgt":"Notulanya sudah ditulis oleh Dewi."},{"fr":"Toutes les questions ont été notées par le directeur.","tgt":"Semua pertanyaan sudah dicatat oleh direktur."},{"fr":"Le projet a été approuvé hier après-midi.","tgt":"Proyek itu sudah disetujui kemarin sore."},{"fr":"Qui va présenter les chiffres aujourd'hui ?","tgt":"Siapa yang akan mempresentasikan angka-angkanya hari ini?"},{"fr":"Le budget sera vérifié encore une fois la semaine prochaine.","tgt":"Anggarannya akan diperiksa sekali lagi minggu depan."},{"fr":"Merci à tous, la séance est levée.","tgt":"Terima kasih semuanya, rapat ditutup."},{"fr":"Franchement, cette réunion aurait pu tenir dans un simple courriel.","tgt":"Saya rasa rapat ini sebenarnya cukup lewat email saja."}],"tip":{"title":"Le passif en « di- » : l'objet passe devant","example":"Le projet a été approuvé hier après-midi. — Proyek itu sudah <b>disetujui</b> kemarin sore.","body":"Pour dire qu'une chose a été faite, l'indonésien met cette chose en tête de phrase et colle « di » devant le verbe : « kirim », envoyer, devient « dikirim », envoyé. À l'oral, on l'emploie beaucoup plus que notre passif français, surtout au bureau : « rapatnya dipindahkan », la réunion a été déplacée. Décomposons « Proyek itu sudah disetujui » : projet, ce, déjà, approuvé. Pour dire par qui, on ajoute « oleh », par : « ditulis oleh Dewi », écrit par Dewi. Astuce : dès que la chose compte plus que la personne, commencez par la chose et pensez « di ».","lit":"projet · ce · [accompli] · approuvé · hier · après-midi","say":{"kirim":"kirim","dikirim":"dikirim","rapatnya dipindahkan":"rapatnya dipindahkan","Proyek itu sudah disetujui":"Proyek itu sudah disetujui","oleh":"oleh","ditulis oleh Dewi":"ditulis oleh Dewi"}}},{"title":"Les courriels du matin","phrases":[{"fr":"J'ai reçu une trentaine de courriels ce matin.","tgt":"Pagi ini saya menerima sekitar tiga puluh email."},{"fr":"Ce message n'a pas encore été lu.","tgt":"Pesan ini belum dibaca."},{"fr":"Pense à me mettre en copie de ce courriel.","tgt":"Tolong cc saya juga di email itu, ya."},{"fr":"La pièce jointe est trop lourde pour être envoyée.","tgt":"Lampirannya terlalu besar untuk dikirim."},{"fr":"Je vous réponds dès que possible.","tgt":"Saya akan membalas secepatnya."},{"fr":"Mon courriel a atterri dans les indésirables.","tgt":"Email saya masuk ke folder spam."},{"fr":"Désolé pour ma réponse tardive.","tgt":"Maaf atas keterlambatan balasan saya."},{"fr":"J'ai oublié de joindre le document.","tgt":"Saya lupa melampirkan dokumennya."},{"fr":"Pourriez-vous confirmer la bonne réception de ce message ?","tgt":"Bisakah Anda mengonfirmasi bahwa pesan ini sudah diterima?"},{"fr":"Je vais ranger ma boîte de réception avant la réunion.","tgt":"Saya mau merapikan kotak masuk dulu sebelum rapat."}]},{"title":"Préparer un rendez-vous client","phrases":[{"fr":"Le directeur m'a demandé de réserver une salle.","tgt":"Direktur menyuruh saya memesan ruang rapat."},{"fr":"J'ai fait imprimer les documents par l'assistante.","tgt":"Saya menyuruh asisten mencetak dokumennya."},{"fr":"Ne faisons pas attendre le client.","tgt":"Jangan membuat klien menunggu."},{"fr":"Ce retard m'a vraiment rendu nerveux.","tgt":"Keterlambatan ini benar-benar membuat saya gugup."},{"fr":"Il a envoyé le chauffeur chercher le client à l'aéroport.","tgt":"Dia menyuruh sopir menjemput klien di bandara."},{"fr":"Qui vous a demandé de modifier le planning ?","tgt":"Siapa yang menyuruh Anda mengubah jadwalnya?"},{"fr":"Sa présentation a fini par convaincre tout le monde.","tgt":"Presentasinya akhirnya membuat semua orang yakin."},{"fr":"Le bruit du chantier voisin m'empêche de me concentrer.","tgt":"Suara proyek di sebelah membuat saya susah berkonsentrasi."},{"fr":"Nous servirons du thé et des petits gâteaux.","tgt":"Kita akan menyajikan teh dan kue-kue kecil."},{"fr":"Tout est prêt, il ne reste plus qu'à attendre le client.","tgt":"Semuanya sudah siap, tinggal menunggu klien datang."}],"tip":{"title":"Faire faire : « suruh » et « membuat »","example":"Ne faisons pas attendre le client. — Jangan <b>membuat</b> klien menunggu.","body":"Pour faire faire quelque chose à quelqu'un, on emploie « menyuruh », demander ou ordonner, suivi de la personne puis de l'action, sans aucun petit mot entre les deux : « Direktur menyuruh saya memesan ruang rapat », le directeur m'a demandé de réserver une salle. À l'oral, on entend souvent la forme courte « suruh ». Quand c'est une situation qui provoque un effet, on prend « membuat », faire ou rendre : « membuat saya gugup », me rend nerveux. Décomposons « Jangan membuat klien menunggu » : ne pas, faire, client, attendre. Astuce : « suruh » pour une personne qui donne une consigne, « membuat » pour un effet que l'on provoque.","lit":"ne pas · faire · client · attendre","say":{"suruh":"suruh","membuat":"membuat","menyuruh":"menyuruh","Direktur menyuruh saya memesan ruang rapat":"Direktur menyuruh saya memesan ruang rapat","membuat saya gugup":"membuat saya gugup","Jangan membuat klien menunggu":"Jangan membuat klien menunggu"}}},{"title":"Le loyer et le propriétaire","phrases":[{"fr":"Le loyer se paie au début de chaque mois.","tgt":"Uang sewanya dibayar setiap awal bulan."},{"fr":"Ici, beaucoup de propriétaires demandent un an de loyer d'avance.","tgt":"Di sini banyak pemilik rumah meminta sewa setahun di muka."},{"fr":"Le propriétaire habite juste à côté.","tgt":"Pemilik rumahnya tinggal persis di sebelah."},{"fr":"La climatisation de la chambre ne marche plus.","tgt":"AC di kamar sudah tidak berfungsi."},{"fr":"J'ai appelé le propriétaire pour signaler la fuite.","tgt":"Saya menelepon pemilik rumah untuk melaporkan kebocoran."},{"fr":"Il a promis d'envoyer un réparateur demain.","tgt":"Dia berjanji akan mengirim tukang besok."},{"fr":"L'eau et l'électricité ne sont pas comprises dans le loyer.","tgt":"Biaya air dan listrik tidak termasuk dalam uang sewa."},{"fr":"Le loyer va augmenter l'année prochaine.","tgt":"Sewanya akan naik tahun depan."},{"fr":"Le bail se termine en décembre.","tgt":"Kontrak sewanya berakhir bulan Desember."},{"fr":"Dans l'ensemble, c'est un propriétaire plutôt arrangeant.","tgt":"Secara keseluruhan, pemilik rumahnya cukup pengertian."}]},{"title":"Renouveler le bail","phrases":[{"fr":"Je veux bien rester, à condition que le loyer n'augmente pas trop.","tgt":"Saya mau tetap tinggal, asal sewanya tidak naik terlalu banyak."},{"fr":"Vous pouvez payer tous les six mois, pourvu que ce soit à l'heure.","tgt":"Anda boleh membayar setiap enam bulan, asal tepat waktu."},{"fr":"Vous pouvez avoir un chat, du moment que la maison reste propre.","tgt":"Boleh memelihara kucing, asal rumahnya tetap bersih."},{"fr":"Je repeins moi-même, à condition que vous achetiez la peinture.","tgt":"Saya akan mengecat sendiri, asal Bapak yang membeli catnya."},{"fr":"Le propriétaire est d'accord, à condition de signer pour deux ans.","tgt":"Pemilik rumah setuju, asal kontraknya untuk dua tahun."},{"fr":"Peu importe le quartier, du moment que c'est près du bureau.","tgt":"Daerahnya tidak masalah, asal dekat dengan kantor."},{"fr":"Le prix pourrait-il baisser un peu, monsieur ?","tgt":"Bisakah harganya diturunkan sedikit, Pak?"},{"fr":"Nous avons trouvé un accord qui convient à tout le monde.","tgt":"Kami sudah mencapai kesepakatan yang cocok untuk semua pihak."},{"fr":"Le nouveau contrat sera signé samedi.","tgt":"Kontrak barunya akan ditandatangani hari Sabtu."},{"fr":"Tout ira bien, tant qu'on se parle franchement.","tgt":"Semuanya akan baik-baik saja, asal kita saling terbuka."}],"tip":{"title":"« Asal » : à condition que","example":"Peu importe le quartier, du moment que c'est près du bureau. — Daerahnya tidak masalah, <b>asal</b> dekat dengan kantor.","body":"« Asal », ou sa forme un peu plus soutenue « asalkan », veut dire à condition que, pourvu que, du moment que. Il se place au milieu de la phrase, juste devant la condition, et le verbe ne change pas du tout, alors qu'en français il faut un subjonctif. Décomposons « Daerahnya tidak masalah, asal dekat dengan kantor » : le quartier, pas problème, à condition que, près avec bureau. C'est un mot parfait pour négocier en douceur : « boleh, asal tepat waktu », c'est possible, pourvu que ce soit à l'heure. Astuce : dites d'abord votre oui, puis glissez « asal » pour poser votre condition.","lit":"quartier · pas · problème · à condition que · près · avec · bureau","say":{"Asal":"Asal","asalkan":"asalkan","Daerahnya tidak masalah, asal dekat dengan kantor":"Daerahnya tidak masalah, asal dekat dengan kantor","boleh, asal tepat waktu":"boleh, asal tepat waktu","asal":"asal"}}},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je voudrais ouvrir un compte dans cette banque.","tgt":"Saya ingin membuka rekening di bank ini."},{"fr":"Quels documents faut-il apporter ?","tgt":"Dokumen apa saja yang perlu dibawa?"},{"fr":"Il faut une copie du passeport et du permis de séjour.","tgt":"Diperlukan fotokopi paspor dan izin tinggal."},{"fr":"Prenez un ticket et attendez votre tour.","tgt":"Silakan ambil nomor antrean dan tunggu giliran Anda."},{"fr":"Le formulaire doit être rempli en entier.","tgt":"Formulirnya harus diisi lengkap."},{"fr":"La carte bancaire sera prête dans une semaine.","tgt":"Kartu debitnya akan jadi dalam seminggu."},{"fr":"Ce compte a-t-il des frais mensuels ?","tgt":"Apakah ada biaya bulanan untuk rekening ini?"},{"fr":"Je signe ici, et encore ici ?","tgt":"Saya tanda tangan di sini, lalu di sini juga?"},{"fr":"Avec l'application de la banque, on peut payer par code QR.","tgt":"Dengan aplikasi banknya, kita bisa bayar pakai kode QR."},{"fr":"L'employé de la banque a été très patient avec moi.","tgt":"Petugas bank itu sangat sabar melayani saya."}]},{"title":"Un souci de carte bancaire","phrases":[{"fr":"Ma carte a été avalée par le distributeur.","tgt":"Kartu saya tertelan mesin ATM."},{"fr":"J'ai tapé le mauvais code trois fois de suite.","tgt":"Saya salah memasukkan PIN tiga kali berturut-turut."},{"fr":"Ma carte est bloquée depuis ce matin.","tgt":"Kartu saya terblokir sejak tadi pagi."},{"fr":"Il faut appeler le service client tout de suite.","tgt":"Kita harus segera menelepon layanan pelanggan."},{"fr":"Un paiement suspect apparaît sur mon relevé.","tgt":"Ada transaksi mencurigakan di mutasi rekening saya."},{"fr":"Je n'ai jamais fait cet achat.","tgt":"Saya tidak pernah melakukan pembelian ini."},{"fr":"La somme sera remboursée sous quatorze jours.","tgt":"Dananya akan dikembalikan dalam waktu empat belas hari."},{"fr":"Une nouvelle carte sera envoyée chez moi.","tgt":"Kartu baru akan dikirim ke rumah saya."},{"fr":"En attendant, je retire de l'argent au guichet.","tgt":"Sementara itu, saya mengambil uang tunai di teller."},{"fr":"Quelle matinée ! Heureusement, tout s'est arrangé.","tgt":"Pagi yang melelahkan! Untungnya semuanya beres."}]},{"title":"Les démarches administratives","phrases":[{"fr":"Le dossier est incomplet, il manque même la photo.","tgt":"Berkasnya belum lengkap, bahkan fotonya juga belum ada."},{"fr":"J'ai attendu trois heures, et même plus.","tgt":"Saya menunggu tiga jam, bahkan lebih."},{"fr":"Il faut des copies de tout, même de l'acte de naissance.","tgt":"Semuanya harus difotokopi, bahkan akta kelahiran juga."},{"fr":"Il y a foule au guichet : même avant huit heures, la file est déjà longue.","tgt":"Loketnya selalu ramai, bahkan sebelum jam delapan antreannya sudah panjang."},{"fr":"Personne ne savait répondre, pas même le chef de service.","tgt":"Tidak ada yang bisa menjawab, bahkan kepala bagiannya pun tidak tahu."},{"fr":"Le formulaire peut être téléchargé sur internet.","tgt":"Formulirnya bisa diunduh lewat internet."},{"fr":"Mon rendez-vous a été confirmé par courriel.","tgt":"Janji temu saya sudah dikonfirmasi lewat email."},{"fr":"Le fonctionnaire était aimable, il m'a même aidé à remplir le formulaire.","tgt":"Petugasnya ramah, bahkan dia membantu saya mengisi formulirnya."},{"fr":"Ce tampon est indispensable pour la suite.","tgt":"Cap ini sangat penting untuk proses selanjutnya."},{"fr":"C'était long, mais c'est enfin terminé.","tgt":"Prosesnya lama, tapi akhirnya selesai juga."}],"tip":{"title":"« Bahkan » : même","example":"Le fonctionnaire était aimable, il m'a même aidé à remplir le formulaire. — Petugasnya ramah, <b>bahkan</b> dia membantu saya mengisi formulirnya.","body":"« Bahkan » signifie même, au sens de et en plus, voire. On le place en tête de la partie de phrase qui ajoute la surprise : « Petugasnya ramah, bahkan dia membantu saya », l'employé était aimable, il m'a même aidé. En français, « même » se glisse après le verbe ; en indonésien, il passe devant tout le reste. Il marche aussi avec un nombre : « tiga jam, bahkan lebih », trois heures, et même plus. Pour insister encore, on ajoute souvent « pun » ou « juga » juste après le mot visé : « bahkan kepala bagiannya pun », même le chef de service. Astuce : voyez « bahkan » comme une marche de plus dans votre récit.","lit":"employé · aimable · même · il · aider · moi · remplir · formulaire","say":{"Bahkan":"Bahkan","Petugasnya ramah, bahkan dia membantu saya":"Petugasnya ramah, bahkan dia membantu saya","tiga jam, bahkan lebih":"tiga jam, bahkan lebih","pun":"pun","juga":"juga","bahkan kepala bagiannya pun":"bahkan kepala bagiannya pun","bahkan":"bahkan"}}},{"title":"Renouveler le permis de séjour","phrases":[{"fr":"Mon permis de séjour expire dans deux mois.","tgt":"Izin tinggal saya habis dua bulan lagi."},{"fr":"La demande doit être déposée bien à l'avance.","tgt":"Permohonannya harus diajukan jauh-jauh hari."},{"fr":"L'entreprise s'occupe de la plupart des papiers.","tgt":"Perusahaan mengurus sebagian besar dokumennya."},{"fr":"On a pris mes empreintes digitales et ma photo.","tgt":"Sidik jari dan foto saya diambil."},{"fr":"Le traitement prend environ trois semaines.","tgt":"Prosesnya memakan waktu sekitar tiga minggu."},{"fr":"Pendant ce temps, mon passeport reste au bureau de l'immigration.","tgt":"Selama itu, paspor saya disimpan di kantor imigrasi."},{"fr":"Je recevrai une notification quand ce sera prêt.","tgt":"Saya akan mendapat pemberitahuan kalau sudah selesai."},{"fr":"Surtout, n'oubliez pas de garder le reçu.","tgt":"Jangan lupa menyimpan tanda terimanya."},{"fr":"Chaque année, c'est exactement la même procédure.","tgt":"Setiap tahun prosedurnya sama saja."},{"fr":"Avec l'habitude, ça devient presque une formalité.","tgt":"Kalau sudah terbiasa, ini hampir jadi formalitas saja."}]},{"title":"Le déjeuner d'affaires","phrases":[{"fr":"On m'a invité à déjeuner avec un partenaire.","tgt":"Saya diundang makan siang bersama seorang mitra bisnis."},{"fr":"Le restaurant a été réservé pour midi et demi.","tgt":"Restorannya sudah dipesan untuk jam setengah satu."},{"fr":"Ici, on parle rarement affaires dès le début du repas.","tgt":"Di sini, orang jarang langsung membicarakan bisnis di awal makan."},{"fr":"On commence plutôt par prendre des nouvelles de la famille.","tgt":"Biasanya kita mulai dengan menanyakan kabar keluarga."},{"fr":"Que me conseillez-vous sur la carte ?","tgt":"Apa yang Bapak sarankan dari menu ini?"},{"fr":"En général, c'est celui qui invite qui règle l'addition.","tgt":"Biasanya tuan rumah yang membayar tagihannya."},{"fr":"Permettez-moi de vous inviter la prochaine fois.","tgt":"Izinkan saya yang mentraktir lain kali."},{"fr":"Ce partenariat pourrait profiter à nos deux sociétés.","tgt":"Kerja sama ini bisa menguntungkan kedua perusahaan kita."},{"fr":"Nous en reparlerons au bureau la semaine prochaine.","tgt":"Kita lanjutkan pembicaraannya di kantor minggu depan."},{"fr":"Merci pour ce repas et pour cet échange agréable.","tgt":"Terima kasih atas makan siang dan obrolan yang menyenangkan ini."}]},{"title":"Un soto betawi entre collègues","phrases":[{"fr":"Il y a un excellent warung de soto betawi près du bureau.","tgt":"Ada warung soto betawi yang enak sekali dekat kantor."},{"fr":"Le soto betawi est préparé avec du lait de coco.","tgt":"Soto betawi dibuat dengan santan."},{"fr":"Certains y ajoutent aussi du lait frais.","tgt":"Ada juga yang menambahkan susu segar."},{"fr":"Je le prends avec du riz et des chips de crevettes.","tgt":"Saya pesan pakai nasi dan kerupuk udang."},{"fr":"Avec un filet de citron vert, c'est parfait.","tgt":"Diberi sedikit perasan jeruk nipis, rasanya jadi sempurna."},{"fr":"Attention, le sambal est très fort ici.","tgt":"Hati-hati, sambalnya pedas sekali di sini."},{"fr":"Ce plat est typique de Jakarta.","tgt":"Makanan ini khas Jakarta."},{"fr":"À midi, il faut arriver tôt pour avoir une place.","tgt":"Kalau siang, kita harus datang lebih awal supaya dapat tempat."},{"fr":"Avec un thé glacé, le repas coûte seulement trente mille roupies.","tgt":"Dengan es teh, makan siangnya cuma tiga puluh ribu rupiah."},{"fr":"C'est devenu notre petit rituel du jeudi.","tgt":"Ini sudah jadi kebiasaan kami setiap hari Kamis."}]},{"title":"Un courrier officiel","phrases":[{"fr":"Madame, Monsieur, nous avons bien reçu votre demande.","tgt":"Dengan hormat, kami telah menerima permohonan Anda."},{"fr":"Merci de bien vouloir patienter un instant.","tgt":"Mohon ditunggu sebentar."},{"fr":"Veuillez remplir ce formulaire.","tgt":"Mohon isi formulir ini."},{"fr":"Nous vous prions de nous excuser pour ce désagrément.","tgt":"Kami mohon maaf atas ketidaknyamanan ini."},{"fr":"Merci de joindre une copie de votre passeport.","tgt":"Mohon lampirkan fotokopi paspor Anda."},{"fr":"Votre attention, s'il vous plaît, la réunion va commencer.","tgt":"Mohon perhatiannya sebentar, rapat akan segera dimulai."},{"fr":"Madame, Monsieur, je me permets de vous relancer au sujet de ma candidature.","tgt":"Dengan hormat, saya ingin menanyakan perkembangan lamaran saya."},{"fr":"Nous vous remercions de votre attention.","tgt":"Atas perhatian Anda, kami ucapkan terima kasih."},{"fr":"Merci de nous répondre au plus tard vendredi.","tgt":"Mohon balasannya paling lambat hari Jumat."},{"fr":"Je vous prie d'agréer mes salutations respectueuses.","tgt":"Hormat saya."}],"tip":{"title":"« Mohon » et « dengan hormat » : le langage du bureau","example":"Veuillez remplir ce formulaire. — <b>Mohon</b> isi formulir ini.","body":"Au bureau, on entend sans cesse « mohon », qui signifie je vous prie, merci de. On le met tout simplement devant le verbe : « Mohon isi formulir ini », veuillez remplir ce formulaire, mot à mot prier, remplir, formulaire, ce. C'est plus respectueux que « tolong », s'il vous plaît, et on l'entend dans les annonces, au téléphone et en réunion : « mohon ditunggu », merci de patienter. « Dengan hormat », avec respect, ouvre une lettre ou une prise de parole officielle, un peu comme notre Madame, Monsieur. Pour s'excuser poliment, on dit « mohon maaf », je vous prie de m'excuser. Astuce : « mohon » devant un verbe, et vous passez aussitôt au registre du bureau.","lit":"prier · remplir · formulaire · ce","say":{"Mohon":"Mohon","dengan hormat":"dengan hormat","mohon":"mohon","Mohon isi formulir ini":"Mohon isi formulir ini","tolong":"tolong","mohon ditunggu":"mohon ditunggu","Dengan hormat":"Dengan hormat","mohon maaf":"mohon maaf"}}},{"title":"Les embouteillages de Jakarta","phrases":[{"fr":"Ce matin, la route était complètement bouchée.","tgt":"Tadi pagi jalanannya macet total."},{"fr":"Je suis parti à six heures pour éviter les bouchons.","tgt":"Saya berangkat jam enam supaya tidak kena macet."},{"fr":"Quand il pleut, la circulation devient infernale.","tgt":"Kalau hujan, lalu lintasnya jadi parah sekali."},{"fr":"L'ojek est souvent plus rapide que la voiture.","tgt":"Naik ojek sering lebih cepat daripada naik mobil."},{"fr":"Le métro m'a beaucoup simplifié la vie.","tgt":"MRT sangat memudahkan hidup saya."},{"fr":"Désolé, je suis coincé dans les bouchons.","tgt":"Maaf, saya terjebak macet."},{"fr":"J'arrive dans une vingtaine de minutes.","tgt":"Saya sampai sekitar dua puluh menit lagi."},{"fr":"La réunion a été reportée à cause de la pluie.","tgt":"Rapatnya ditunda karena hujan."},{"fr":"Certains collègues habitent à deux heures du bureau.","tgt":"Ada rekan kerja yang tinggal dua jam dari kantor."},{"fr":"À Jakarta, on ne mesure pas les distances en kilomètres, mais en heures.","tgt":"Di Jakarta, jarak tidak diukur dengan kilometer, tapi dengan jam."}]},{"title":"Travailler depuis la maison","phrases":[{"fr":"Aujourd'hui, je travaille depuis chez moi.","tgt":"Hari ini saya bekerja dari rumah."},{"fr":"La connexion internet est un peu lente ce matin.","tgt":"Koneksi internetnya agak lambat pagi ini."},{"fr":"La réunion aura lieu en ligne à neuf heures.","tgt":"Rapatnya diadakan secara daring jam sembilan."},{"fr":"Pourriez-vous partager votre écran ?","tgt":"Bisakah Anda membagikan layar Anda?"},{"fr":"Je n'entends plus rien, votre micro est coupé.","tgt":"Saya tidak mendengar apa-apa, mikrofon Anda mati."},{"fr":"On entend le marchand ambulant dans mon micro.","tgt":"Suara pedagang keliling terdengar di mikrofon saya."},{"fr":"Le télétravail me fait gagner deux heures par jour.","tgt":"Bekerja dari rumah menghemat dua jam setiap hari."},{"fr":"Mais parfois, l'ambiance du bureau me manque.","tgt":"Tapi kadang saya rindu suasana kantor."},{"fr":"Je fais une petite pause pour boire un café.","tgt":"Saya istirahat sebentar untuk minum kopi."},{"fr":"J'éteins l'ordinateur à cinq heures pile.","tgt":"Saya mematikan komputer tepat jam lima."}]},{"title":"Accueillir un nouveau collègue","phrases":[{"fr":"Je vous présente notre nouveau collègue, monsieur Rizal.","tgt":"Perkenalkan, ini rekan kerja baru kita, Pak Rizal."},{"fr":"Il a été muté depuis notre bureau de Surabaya.","tgt":"Beliau pindahan dari kantor kita di Surabaya."},{"fr":"N'hésitez pas à me poser des questions.","tgt":"Jangan ragu untuk bertanya kepada saya."},{"fr":"Votre bureau se trouve près de la fenêtre.","tgt":"Meja Anda ada di dekat jendela."},{"fr":"La cantine est au rez-de-chaussée.","tgt":"Kantinnya ada di lantai dasar."},{"fr":"Votre badge vous sera remis cet après-midi.","tgt":"Kartu akses Anda akan diberikan sore ini."},{"fr":"Il faudra vous présenter aux autres services.","tgt":"Anda perlu berkenalan dengan bagian-bagian lain."},{"fr":"Ici, on appelle les collègues plus âgés « monsieur » ou « madame ».","tgt":"Di sini, rekan yang lebih senior dipanggil Bapak atau Ibu."},{"fr":"La première semaine est toujours un peu chargée.","tgt":"Minggu pertama memang selalu agak padat."},{"fr":"Bienvenue parmi nous, et bon courage pour vos débuts.","tgt":"Selamat bergabung, semoga awal kerjanya lancar."}]},{"title":"Présenter devant la direction","phrases":[{"fr":"Ma présentation est prévue jeudi matin.","tgt":"Presentasi saya dijadwalkan hari Kamis pagi."},{"fr":"Les supports ont été préparés par toute l'équipe.","tgt":"Bahan presentasinya disiapkan oleh seluruh tim."},{"fr":"Parler devant la direction me rend un peu nerveux.","tgt":"Saya agak gugup berbicara di depan pimpinan."},{"fr":"Je vais d'abord résumer les résultats de l'année.","tgt":"Pertama, saya akan merangkum hasil tahun ini."},{"fr":"Comme vous pouvez le voir, les ventes ont augmenté.","tgt":"Seperti yang terlihat, penjualannya meningkat."},{"fr":"Cette baisse s'explique par la hausse des prix.","tgt":"Penurunan ini disebabkan oleh kenaikan harga."},{"fr":"Avez-vous des questions à ce stade ?","tgt":"Apakah ada pertanyaan sampai di sini?"},{"fr":"Excellente question, je vous remercie.","tgt":"Pertanyaan yang sangat bagus, terima kasih."},{"fr":"Je vous enverrai les chiffres détaillés demain.","tgt":"Angka-angka rincinya akan saya kirim besok."},{"fr":"Le directeur a salué le travail de l'équipe.","tgt":"Direktur menghargai kerja keras tim kami."}]},{"title":"Le départ d'une collègue","phrases":[{"fr":"Madame Sari quitte l'entreprise à la fin du mois.","tgt":"Bu Sari akan meninggalkan perusahaan akhir bulan ini."},{"fr":"Elle a travaillé ici pendant douze ans.","tgt":"Beliau sudah bekerja di sini selama dua belas tahun."},{"fr":"Nous lui organisons un petit pot de départ cette semaine.","tgt":"Kami mengadakan acara perpisahan kecil untuk beliau minggu ini."},{"fr":"Nous nous sommes cotisés pour lui acheter un cadeau.","tgt":"Kami patungan membeli hadiah untuk beliau."},{"fr":"Elle va énormément nous manquer.","tgt":"Kami pasti akan sangat merindukan beliau."},{"fr":"C'est elle qui m'a tout appris à mon arrivée.","tgt":"Beliaulah yang mengajari saya semuanya waktu saya baru datang."},{"fr":"Son poste sera repris par Andi.","tgt":"Posisinya akan digantikan oleh Andi."},{"fr":"Elle part s'installer à Yogyakarta avec sa famille.","tgt":"Beliau akan pindah ke Yogyakarta bersama keluarganya."},{"fr":"On reste en contact, d'accord ?","tgt":"Kita tetap berhubungan, ya?"},{"fr":"Bonne continuation et merci pour tout.","tgt":"Sukses selalu, dan terima kasih atas segalanya."}]},{"title":"Trop d'heures supplémentaires","phrases":[{"fr":"Cette semaine, je suis rentré tard tous les soirs.","tgt":"Minggu ini saya pulang larut setiap malam."},{"fr":"Le projet doit être bouclé avant la fin du mois.","tgt":"Proyeknya harus diselesaikan sebelum akhir bulan."},{"fr":"Je suis épuisé, je manque de sommeil.","tgt":"Saya kelelahan, kurang tidur."},{"fr":"Mon chef ne se rend pas compte de la charge de travail.","tgt":"Atasan saya tidak menyadari beratnya beban kerja."},{"fr":"Je devrais lui en parler franchement.","tgt":"Sebaiknya saya bicara terus terang dengannya."},{"fr":"Les heures supplémentaires sont-elles payées ?","tgt":"Apakah lembur dibayar?"},{"fr":"Il faut savoir dire non de temps en temps.","tgt":"Kita harus bisa menolak sesekali."},{"fr":"Ma santé compte plus que ce dossier.","tgt":"Kesehatan saya lebih penting daripada proyek ini."},{"fr":"J'ai demandé deux jours de congé.","tgt":"Saya sudah mengajukan cuti dua hari."},{"fr":"Un peu de repos me fera le plus grand bien.","tgt":"Istirahat sebentar pasti akan sangat bermanfaat buat saya."}]},{"title":"Souffler un week-end à Bandung","phrases":[{"fr":"Ce week-end, on part se reposer à Bandung.","tgt":"Akhir pekan ini kami pergi ke Bandung untuk beristirahat."},{"fr":"Le train part de la gare de Gambir à sept heures.","tgt":"Keretanya berangkat dari Stasiun Gambir jam tujuh."},{"fr":"Là-haut, l'air est bien plus frais qu'à Jakarta.","tgt":"Di sana udaranya jauh lebih sejuk daripada di Jakarta."},{"fr":"Nous avons loué une petite maison au milieu des plantations de thé.","tgt":"Kami menyewa rumah kecil di tengah kebun teh."},{"fr":"Ni courriels ni réunions pendant deux jours.","tgt":"Tidak ada email maupun rapat selama dua hari."},{"fr":"Le matin, on se promène dans la brume.","tgt":"Pagi-pagi kami berjalan-jalan di tengah kabut."},{"fr":"Le soir, on mange des brochettes au bord de la route.","tgt":"Malamnya kami makan sate di pinggir jalan."},{"fr":"Samedi, j'ai volontairement éteint mon téléphone toute la journée.","tgt":"Hari Sabtu, ponsel saya sengaja saya matikan seharian."},{"fr":"Ça fait vraiment du bien de quitter la ville.","tgt":"Rasanya enak sekali bisa keluar dari kota."},{"fr":"Lundi, je reprends le travail plein d'énergie.","tgt":"Senin nanti saya kembali bekerja dengan semangat baru."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Je comprends mieux la vie professionnelle à Jakarta.","tgt":"Sekarang saya lebih memahami kehidupan kerja di Jakarta."},{"fr":"Le passif en « di- » me semble maintenant naturel.","tgt":"Bentuk pasif dengan di- sekarang terasa alami bagi saya."},{"fr":"Je peux suivre une réunion en indonésien.","tgt":"Saya bisa mengikuti rapat dalam bahasa Indonesia."},{"fr":"Je discute avec mon propriétaire sans difficulté.","tgt":"Saya bisa berbicara dengan pemilik rumah tanpa kesulitan."},{"fr":"À la banque, je me débrouille tout seul maintenant.","tgt":"Di bank, sekarang saya bisa mengurus semuanya sendiri."},{"fr":"« Mohon » et « dengan hormat » n'ont plus de secret pour moi.","tgt":"Ungkapan mohon dan dengan hormat sudah tidak asing lagi bagi saya."},{"fr":"Mes collègues disent que mon indonésien a beaucoup progressé.","tgt":"Rekan-rekan kerja bilang bahasa Indonesia saya sudah jauh lebih lancar."},{"fr":"Il me reste encore beaucoup de vocabulaire à apprendre.","tgt":"Masih banyak kosakata yang harus saya pelajari."},{"fr":"Mais je n'ai plus peur de parler au bureau.","tgt":"Tapi saya sudah tidak takut lagi berbicara di kantor."},{"fr":"Prochaine étape : parcourir toute l'Indonésie !","tgt":"Langkah berikutnya: berkeliling seluruh Indonesia!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Medan","phrases":[{"fr":"Nous venons d'atterrir à Medan après un long vol.","tgt":"Kami baru saja mendarat di Medan setelah penerbangan yang panjang."},{"fr":"L'air est beaucoup plus humide que je ne l'imaginais.","tgt":"Udaranya jauh lebih lembap daripada yang saya bayangkan."},{"fr":"Un chauffeur nous attendait déjà à la sortie de l'aéroport.","tgt":"Seorang sopir sudah menunggu kami di pintu keluar bandara."},{"fr":"La circulation à Medan est vraiment chaotique.","tgt":"Lalu lintas di Medan benar-benar semrawut."},{"fr":"Les gens d'ici parlent fort, mais ils sont très chaleureux.","tgt":"Orang sini bicaranya keras, tetapi mereka sangat ramah."},{"fr":"Notre hôtel se trouve tout près du palais Maimun.","tgt":"Hotel kami terletak tidak jauh dari Istana Maimun."},{"fr":"Nous passerons deux nuits ici avant de partir vers la jungle.","tgt":"Kami akan menginap dua malam di sini sebelum berangkat ke hutan."},{"fr":"J'ai changé un peu d'argent pour les premiers jours.","tgt":"Saya sudah menukar sedikit uang untuk beberapa hari pertama."},{"fr":"Nous préparons ce voyage à Sumatra depuis des mois.","tgt":"Kami sudah mempersiapkan perjalanan ke Sumatra ini selama berbulan-bulan."},{"fr":"Jusqu'ici, tout se passe sans le moindre problème.","tgt":"Sejauh ini, semuanya berjalan dengan lancar."}]},{"title":"Les petites mésaventures du voyage","phrases":[{"fr":"Nous avons raté le dernier bus pour Bukit Lawang.","tgt":"Kami ketinggalan bus terakhir ke Bukit Lawang."},{"fr":"Hier soir, la pluie nous a surpris en pleine rue.","tgt":"Tadi malam kami kehujanan di tengah jalan."},{"fr":"Mon ami a perdu son portefeuille au marché.","tgt":"Teman saya kehilangan dompetnya di pasar."},{"fr":"Sans climatisation, on a eu terriblement chaud toute la nuit.","tgt":"Tanpa AC, kami kepanasan sepanjang malam."},{"fr":"Dans le bus, j'ai eu froid à cause de la clim trop forte.","tgt":"Di dalam bus, saya kedinginan karena AC-nya terlalu dingin."},{"fr":"La sécurité des voyageurs est la priorité du guide.","tgt":"Keselamatan para wisatawan adalah prioritas utama pemandu."},{"fr":"La beauté de ce paysage nous a coupé le souffle.","tgt":"Keindahan pemandangan ini membuat kami terpukau."},{"fr":"Nous avons eu du mal à trouver une chambre libre.","tgt":"Kami kesulitan mencari kamar yang masih kosong."},{"fr":"Heureusement, cet incident s'est bien terminé.","tgt":"Untungnya, kejadian ini berakhir dengan baik."},{"fr":"Malgré la fatigue, on garde le sourire.","tgt":"Meskipun kelelahan, kami tetap tersenyum."}],"tip":{"title":"Le circonfixe « ke-an » : les noms abstraits et les mésaventures","example":"Mon ami a perdu son portefeuille au marché. — Teman saya <b>kehilangan</b> dompetnya di pasar.","body":"En indonésien, on peut envelopper un mot entre « ke » au début et « an » à la fin, un peu comme dans un sandwich. Premier usage : fabriquer un nom abstrait, comme nos terminaisons « -té » ou « -ité ». Ainsi « indah », beau, devient « keindahan », la beauté, et « selamat », sain et sauf, devient « keselamatan », la sécurité. Deuxième usage, très vivant à l'oral : dire qu'une chose désagréable vous tombe dessus sans que vous l'ayez voulu. « Hujan », la pluie, donne « kehujanan », se faire surprendre par la pluie, et « hilang », disparaître, donne « kehilangan », perdre quelque chose. Dans « Teman saya kehilangan dompetnya », on a mot à mot : ami, moi, perdu malgré lui, son portefeuille. Pour retenir : « ke-an », c'est la petite voix qui dit « ça m'est arrivé ».","lit":"ami · je · [ke-an] perdre · portefeuille-son · à · marché","say":{"indah":"indah","keindahan":"keindahan","selamat":"selamat","keselamatan":"keselamatan","Hujan":"Hujan","kehujanan":"kehujanan","hilang":"hilang","kehilangan":"kehilangan","Teman saya kehilangan dompetnya":"Teman saya kehilangan dompetnya"}}},{"title":"Une journée à Medan","phrases":[{"fr":"Ce matin, nous avons visité le palais Maimun.","tgt":"Tadi pagi kami mengunjungi Istana Maimun."},{"fr":"Ce palais a été construit à la fin du dix-neuvième siècle.","tgt":"Istana ini dibangun pada akhir abad kesembilan belas."},{"fr":"Un guide nous a raconté l'histoire de ce palais.","tgt":"Seorang pemandu menceritakan sejarah istana ini kepada kami."},{"fr":"L'après-midi, on s'est perdus dans le grand marché du centre.","tgt":"Sore harinya, kami tersesat di pasar besar di pusat kota."},{"fr":"Les étals débordent de fruits tropicaux que je n'avais jamais vus.","tgt":"Lapak-lapaknya penuh dengan buah-buahan tropis yang belum pernah saya lihat."},{"fr":"La vendeuse m'a fait goûter un durian bien mûr.","tgt":"Ibu penjual itu memberi saya durian matang untuk dicicipi."},{"fr":"Son odeur est forte, mais son goût est étonnamment doux.","tgt":"Baunya menyengat, tetapi rasanya ternyata manis dan lembut."},{"fr":"Le soir, on a mangé dans une rue pleine de petits stands.","tgt":"Malam harinya, kami makan di jalan yang penuh dengan warung kaki lima."},{"fr":"Medan est une ville très animée, même tard le soir.","tgt":"Medan adalah kota yang sangat ramai, bahkan sampai larut malam."},{"fr":"Demain, nous partons tôt pour éviter les embouteillages.","tgt":"Besok kami berangkat pagi-pagi untuk menghindari kemacetan."}]},{"title":"Préparer le départ vers la jungle","phrases":[{"fr":"On part très tôt pour ne pas être coincés dans les bouchons.","tgt":"Kami berangkat pagi-pagi sekali supaya tidak terjebak macet."},{"fr":"Prenez une veste pour ne pas avoir froid dans le bus.","tgt":"Bawalah jaket supaya Anda tidak kedinginan di dalam bus."},{"fr":"J'ai acheté de l'anti-moustique pour qu'on ne se fasse pas piquer.","tgt":"Saya membeli obat nyamuk supaya kita tidak digigit nyamuk."},{"fr":"Le guide parle lentement afin que tout le monde comprenne.","tgt":"Pemandu berbicara pelan-pelan agar semua orang mengerti."},{"fr":"Réservez vos places la veille afin d'être sûrs de partir.","tgt":"Pesanlah tempat duduk sehari sebelumnya agar Anda pasti bisa berangkat."},{"fr":"Il faut boire beaucoup d'eau pour rester en forme.","tgt":"Kita harus banyak minum air supaya tetap bugar."},{"fr":"Gardez votre sac devant vous pour pouvoir le surveiller.","tgt":"Simpan tas Anda di depan supaya bisa terus diawasi."},{"fr":"J'ai noté le numéro du chauffeur pour pouvoir l'appeler en cas de problème.","tgt":"Saya mencatat nomor sopir agar bisa menghubunginya kalau ada masalah."},{"fr":"Nous avons retiré de l'argent, car il n'y a pas de distributeur là-bas.","tgt":"Kami menarik uang tunai karena di sana tidak ada ATM."},{"fr":"Dormez un peu pour être reposés à l'arrivée.","tgt":"Tidurlah sebentar supaya Anda segar saat tiba nanti."}],"tip":{"title":"« Supaya » et « agar » : pour que","example":"Le guide parle lentement afin que tout le monde comprenne. — Pemandu berbicara pelan-pelan <b>agar</b> semua orang mengerti.","body":"Pour dire « pour que » ou « afin de », l'indonésien a deux mots qui veulent dire exactement la même chose : « supaya », le plus courant à l'oral, et « agar », un peu plus soutenu. Grande différence avec le français : pas de subjonctif à apprendre, on pose simplement la phrase normale juste après. « Pemandu berbicara pelan-pelan agar semua orang mengerti » se dit mot à mot : le guide parle lentement, afin que, tout le monde comprend. On peut aussi l'employer sans répéter le sujet : « supaya tidak kedinginan », pour ne pas avoir froid, ou « supaya tetap bugar », pour rester en forme. Astuce : quand vous donnez un conseil en voyage, terminez-le par « supaya » suivi de la raison, cela sonne tout de suite très naturel.","lit":"guide · parler · lentement · afin que · tous · personnes · comprendre","say":{"Supaya":"Supaya","agar":"agar","supaya":"supaya","Pemandu berbicara pelan-pelan agar semua orang mengerti":"Pemandu berbicara pelan-pelan agar semua orang mengerti","supaya tidak kedinginan":"supaya tidak kedinginan","supaya tetap bugar":"supaya tetap bugar"}}},{"title":"En route vers Bukit Lawang","phrases":[{"fr":"La route vers Bukit Lawang traverse d'immenses plantations de palmiers à huile.","tgt":"Jalan menuju Bukit Lawang melewati perkebunan kelapa sawit yang sangat luas."},{"fr":"Le chauffeur évite les nids-de-poule avec une habileté impressionnante.","tgt":"Sopirnya menghindari jalan berlubang dengan sangat lihai."},{"fr":"Le village est niché au bord d'une rivière claire.","tgt":"Desa itu terletak di tepi sungai yang jernih."},{"fr":"Notre bungalow donne directement sur la jungle.","tgt":"Pondok kami langsung menghadap ke hutan."},{"fr":"Dès le matin, on entend des singes crier dans les arbres.","tgt":"Sejak pagi, kami mendengar monyet berteriak di pepohonan."},{"fr":"Ici, le réseau téléphonique est très faible.","tgt":"Di sini, sinyal telepon sangat lemah."},{"fr":"Ça fait du bien de se déconnecter quelques jours.","tgt":"Rasanya menyenangkan bisa lepas dari internet selama beberapa hari."},{"fr":"Les habitants vivent surtout du tourisme et de l'agriculture.","tgt":"Penduduk di sini kebanyakan hidup dari pariwisata dan pertanian."},{"fr":"Le soir, on dîne à la lueur des bougies.","tgt":"Malam harinya, kami makan malam diterangi cahaya lilin."},{"fr":"Demain matin, nous partons à la recherche des orangs-outans.","tgt":"Besok pagi, kami akan berangkat mencari orang utan."}]},{"title":"Rencontre avec les orangs-outans","phrases":[{"fr":"Notre guide a repéré une femelle avec son petit.","tgt":"Pemandu kami melihat seekor orang utan betina bersama anaknya."},{"fr":"Elle nous observait calmement du haut d'un arbre.","tgt":"Dia memperhatikan kami dengan tenang dari atas pohon."},{"fr":"Il est interdit de nourrir ou de toucher les animaux.","tgt":"Dilarang memberi makan atau menyentuh binatang."},{"fr":"Il faut toujours garder une distance d'au moins dix mètres.","tgt":"Kita harus selalu menjaga jarak setidaknya sepuluh meter."},{"fr":"Leurs gestes ressemblent étonnamment aux nôtres.","tgt":"Gerak-gerik mereka ternyata sangat mirip dengan kita."},{"fr":"À l'état sauvage, l'orang-outan ne vit qu'à Sumatra et à Kalimantan.","tgt":"Orang utan liar hanya ada di Sumatra dan Kalimantan."},{"fr":"Malheureusement, leur habitat disparaît à toute vitesse.","tgt":"Sayangnya, habitat mereka cepat sekali menghilang."},{"fr":"Ce centre aide les orangs-outans orphelins à retourner dans la forêt.","tgt":"Pusat ini membantu orang utan yatim piatu kembali ke hutan."},{"fr":"Je n'oublierai jamais le regard de ce jeune mâle.","tgt":"Saya tidak akan pernah melupakan tatapan orang utan jantan muda itu."},{"fr":"Cette rencontre valait vraiment ces heures de marche.","tgt":"Pertemuan ini benar-benar sepadan dengan perjalanan berjam-jam."}]},{"title":"Randonnée dans la jungle","phrases":[{"fr":"Tous les visiteurs doivent être accompagnés d'un guide officiel.","tgt":"Semua pengunjung harus didampingi oleh pemandu resmi."},{"fr":"L'inscription se fait à l'entrée du parc national.","tgt":"Pendaftaran dilakukan di pintu masuk taman nasional."},{"fr":"La montée a été plus difficile que prévu.","tgt":"Pendakiannya lebih berat daripada yang kami kira."},{"fr":"Les marcheurs expérimentés choisissent souvent le trek de trois jours.","tgt":"Para pendaki yang berpengalaman sering memilih trek tiga hari."},{"fr":"La vue depuis le sommet de cette colline est extraordinaire.","tgt":"Pemandangan dari puncak bukit ini luar biasa."},{"fr":"Pendant la marche, le guide nous montre des plantes médicinales.","tgt":"Selama perjalanan, pemandu menunjukkan tanaman obat kepada kami."},{"fr":"Ce sentier est déconseillé aux débutants.","tgt":"Jalur ini tidak disarankan untuk pemula."},{"fr":"Les randonneurs doivent remporter tous leurs déchets.","tgt":"Para pendaki harus membawa pulang semua sampah mereka."},{"fr":"Ce soir, notre hébergement sera un simple campement au bord de la rivière.","tgt":"Penginapan kami malam ini hanyalah perkemahan sederhana di tepi sungai."},{"fr":"Notre guide était agriculteur avant de travailler dans le tourisme.","tgt":"Pemandu kami dulunya petani sebelum bekerja di bidang pariwisata."}],"tip":{"title":"Les préfixes « pe- » et « pe-an » : celui qui fait, et l'action","example":"Tous les visiteurs doivent être accompagnés d'un guide officiel. — Semua <b>pengunjung</b> harus didampingi oleh <b>pemandu</b> resmi.","body":"Ces deux préfixes fonctionnent comme une petite usine à mots. Avec « pe » devant un verbe, on obtient la personne qui fait l'action, comme notre terminaison « -eur » : « kunjung », visiter, donne « pengunjung », le visiteur, et « pandu », guider, donne « pemandu », le guide. Avec « pe » au début et « an » à la fin, on obtient l'action elle-même ou son résultat, comme notre « -tion » : « daki », grimper, donne « pendakian », la montée, et « inap », passer la nuit, donne « penginapan », l'hébergement. À l'oral, le début change selon la première lettre du mot, exactement comme avec « me » : on entend « peng », « pem » ou « pen ». Dans « Semua pengunjung harus didampingi oleh pemandu resmi », on a mot à mot : tous, visiteurs, doivent, être accompagnés, par, guide, officiel. Pour retenir : une personne avec « pe », une action avec « pe-an ».","lit":"tous · visiteurs · devoir · [passif] accompagner · par · guide · officiel","say":{"kunjung":"kunjung","pengunjung":"pengunjung","pandu":"pandu","pemandu":"pemandu","daki":"daki","pendakian":"pendakian","inap":"inap","penginapan":"penginapan","Semua pengunjung harus didampingi oleh pemandu resmi":"Semua pengunjung harus didampingi oleh pemandu resmi","pe-":"pe","pe":"pe","peng":"peng","pem":"pem","pen":"pen"}}},{"title":"Une nuit au cœur de la jungle","phrases":[{"fr":"Nous dormons sous une bâche tendue entre deux arbres.","tgt":"Kami tidur di bawah terpal yang dibentangkan di antara dua pohon."},{"fr":"Le guide a allumé un feu pour cuire le riz.","tgt":"Pemandu menyalakan api untuk memasak nasi."},{"fr":"Ici, la nuit tombe extrêmement vite.","tgt":"Di sini, hari cepat sekali menjadi gelap."},{"fr":"Les bruits de la forêt sont encore plus forts dans l'obscurité.","tgt":"Suara hutan terdengar lebih keras lagi dalam kegelapan."},{"fr":"J'ai cru entendre un animal tout près de la tente.","tgt":"Sepertinya saya mendengar ada binatang di dekat tenda."},{"fr":"En fait, ce n'était qu'un gros lézard inoffensif.","tgt":"Ternyata itu hanya seekor kadal besar yang tidak berbahaya."},{"fr":"Le guide nous a raconté des légendes de son village.","tgt":"Pemandu bercerita tentang legenda-legenda dari desanya."},{"fr":"Des lucioles brillaient tout le long de la rivière.","tgt":"Kunang-kunang berkelap-kelip di sepanjang sungai."},{"fr":"Je n'ai pas beaucoup dormi, mais je ne regrette rien.","tgt":"Saya tidak banyak tidur, tetapi saya sama sekali tidak menyesal."},{"fr":"Au réveil, une brume épaisse couvrait toute la vallée.","tgt":"Saat bangun, kabut tebal menyelimuti seluruh lembah."}]},{"title":"Descendre la rivière en bouée","phrases":[{"fr":"Pour rentrer au village, on descend la rivière sur des chambres à air.","tgt":"Untuk kembali ke desa, kami menyusuri sungai dengan ban dalam."},{"fr":"Les guides attachent plusieurs bouées ensemble.","tgt":"Para pemandu mengikat beberapa ban menjadi satu."},{"fr":"Il faut tenir son sac au-dessus de l'eau.","tgt":"Tas harus dipegang di atas permukaan air."},{"fr":"Le courant est plus fort qu'il n'en a l'air.","tgt":"Arusnya lebih deras daripada kelihatannya."},{"fr":"On a été trempés dès les premiers rapides.","tgt":"Kami langsung basah kuyup di jeram pertama."},{"fr":"Heureusement, mon téléphone était dans un sac étanche.","tgt":"Untungnya, ponsel saya ada di dalam tas kedap air."},{"fr":"Des enfants nous saluaient depuis la rive.","tgt":"Anak-anak melambaikan tangan kepada kami dari tepi sungai."},{"fr":"On a croisé des villageois qui se baignaient.","tgt":"Kami berpapasan dengan warga desa yang sedang mandi di sungai."},{"fr":"C'est la façon la plus amusante de rentrer d'une randonnée.","tgt":"Ini cara paling seru untuk pulang dari pendakian."},{"fr":"J'ai crié et ri pendant tout le trajet.","tgt":"Saya berteriak dan tertawa sepanjang perjalanan."}]},{"title":"Le long trajet vers le lac Toba","phrases":[{"fr":"Le trajet jusqu'au lac Toba dure presque toute la journée.","tgt":"Perjalanan ke Danau Toba memakan waktu hampir seharian."},{"fr":"Nous avons pris un minibus partagé avec d'autres voyageurs.","tgt":"Kami naik minibus bersama beberapa wisatawan lain."},{"fr":"Le chauffeur s'arrête dans chaque village pour prendre des passagers.","tgt":"Sopirnya berhenti di setiap desa untuk menaikkan penumpang."},{"fr":"La route serpente à travers des collines couvertes de forêt.","tgt":"Jalannya berkelok-kelok melewati bukit-bukit yang tertutup hutan."},{"fr":"Plusieurs passagers ont eu le mal des transports à cause des virages.","tgt":"Beberapa penumpang mabuk darat karena banyak tikungan."},{"fr":"On a fait une pause pour boire un café local très parfumé.","tgt":"Kami berhenti sebentar untuk minum kopi lokal yang sangat harum."},{"fr":"Soudain, le lac immense est apparu au fond de la vallée.","tgt":"Tiba-tiba, danau yang sangat luas itu muncul di bawah sana."},{"fr":"C'est le plus grand lac volcanique du monde.","tgt":"Ini danau vulkanik terbesar di dunia."},{"fr":"Il s'est formé après une éruption gigantesque, il y a des dizaines de milliers d'années.","tgt":"Danau ini terbentuk setelah letusan dahsyat puluhan ribu tahun yang lalu."},{"fr":"Le ferry pour l'île de Samosir part dans une heure.","tgt":"Feri ke Pulau Samosir berangkat satu jam lagi."}]},{"title":"Sur l'île de Samosir","phrases":[{"fr":"Samosir est une île au milieu du lac Toba.","tgt":"Samosir adalah pulau di tengah Danau Toba."},{"fr":"Nous avons loué un scooter pour faire le tour de l'île.","tgt":"Kami menyewa motor untuk berkeliling pulau."},{"fr":"Les maisons traditionnelles bataks ont des toits en forme de bateau.","tgt":"Rumah adat Batak memiliki atap yang berbentuk seperti perahu."},{"fr":"Ici, les gens se saluent en disant « horas ».","tgt":"Di sini, orang saling menyapa dengan mengucapkan horas."},{"fr":"Le soir, des jeunes jouent de la guitare et chantent au bord de l'eau.","tgt":"Malam hari, anak-anak muda bermain gitar dan bernyanyi di tepi danau."},{"fr":"L'eau du lac est assez fraîche pour se baigner.","tgt":"Air danaunya cukup sejuk untuk berenang."},{"fr":"Notre chambre d'hôte est tenue par une famille batak.","tgt":"Penginapan kami dikelola oleh sebuah keluarga Batak."},{"fr":"La propriétaire nous a appris quelques mots de batak.","tgt":"Ibu pemilik penginapan mengajari kami beberapa kata dalam bahasa Batak."},{"fr":"Les journées passent lentement, et c'est très agréable.","tgt":"Hari-hari berlalu dengan pelan, dan itu sangat menyenangkan."},{"fr":"On pourrait facilement rester ici une semaine de plus.","tgt":"Kami bisa saja tinggal di sini seminggu lagi."}]},{"title":"Une panne en pleine route","phrases":[{"fr":"Normalement, le bus aurait dû partir à huit heures.","tgt":"Seharusnya busnya sudah berangkat pukul delapan."},{"fr":"Le bus est tombé en panne au milieu de nulle part.","tgt":"Busnya mogok di tengah jalan yang sepi."},{"fr":"Normalement, on devrait arriver à la gare routière avant la nuit.","tgt":"Seharusnya kami sampai di terminal sebelum malam."},{"fr":"Le chauffeur dit que ça devrait être réparé en une heure.","tgt":"Kata sopirnya, seharusnya bus ini bisa diperbaiki dalam satu jam."},{"fr":"Il aurait dû vérifier le moteur avant le départ.","tgt":"Seharusnya dia memeriksa mesinnya sebelum berangkat."},{"fr":"Finalement, la réparation a pris toute la matinée.","tgt":"Ternyata, perbaikannya memakan waktu sepanjang pagi."},{"fr":"Nous n'aurions pas dû prendre le bus le moins cher.","tgt":"Seharusnya kami tidak naik bus yang paling murah."},{"fr":"Les passagers attendent patiemment à l'ombre d'un arbre.","tgt":"Para penumpang menunggu dengan sabar di bawah pohon yang rindang."},{"fr":"Un vendeur de boissons est apparu comme par magie.","tgt":"Seorang penjual minuman tiba-tiba muncul entah dari mana."},{"fr":"Normalement, cela ne devrait plus arriver.","tgt":"Seharusnya hal ini tidak terjadi lagi."}],"tip":{"title":"« Seharusnya » : normalement, ça devrait","example":"Normalement, le bus aurait dû partir à huit heures. — <b>Seharusnya</b> busnya sudah berangkat pukul delapan.","body":"« Seharusnya » se place tout simplement en début de phrase et veut dire « normalement », « on devrait » ou « on aurait dû ». Il vient de « harus », devoir, que vous connaissez déjà. Comme le verbe ne se conjugue pas, c'est le contexte qui dit s'il s'agit d'une attente ou d'un regret : « Seharusnya kami sampai sebelum malam », normalement on devrait arriver avant la nuit, mais « Seharusnya dia memeriksa mesinnya », il aurait dû vérifier le moteur. Dans « Seharusnya busnya sudah berangkat pukul delapan », on a mot à mot : normalement, le bus, déjà, partir, heure huit, et le petit « sudah » souligne que c'est raté. Astuce : en cas de panne ou de retard, « seharusnya » est le mot que vous entendrez le plus souvent autour de vous.","lit":"normalement · bus-le · [accompli] · partir · heure · huit","say":{"Seharusnya":"Seharusnya","harus":"harus","Seharusnya kami sampai sebelum malam":"Seharusnya kami sampai sebelum malam","Seharusnya dia memeriksa mesinnya":"Seharusnya dia memeriksa mesinnya","Seharusnya busnya sudah berangkat pukul delapan":"Seharusnya busnya sudah berangkat pukul delapan","sudah":"sudah","seharusnya":"seharusnya"}}},{"title":"Le bus de nuit vers Bukittinggi","phrases":[{"fr":"Nous avons réservé deux places dans un bus de nuit.","tgt":"Kami memesan dua kursi di bus malam."},{"fr":"Les sièges s'inclinent presque comme des lits.","tgt":"Kursinya bisa direbahkan hampir seperti tempat tidur."},{"fr":"Le chauffeur met la musique très fort toute la nuit.","tgt":"Sopirnya memutar musik keras-keras sepanjang malam."},{"fr":"Heureusement, j'avais apporté des bouchons d'oreilles.","tgt":"Untungnya, saya membawa penyumbat telinga."},{"fr":"Vers minuit, le bus s'arrête dans un restaurant au bord de la route.","tgt":"Sekitar tengah malam, bus berhenti di sebuah rumah makan di pinggir jalan."},{"fr":"On a mangé une soupe chaude avant de repartir.","tgt":"Kami makan sup panas sebelum melanjutkan perjalanan."},{"fr":"La route de montagne est pleine de virages serrés.","tgt":"Jalan pegunungannya penuh dengan tikungan tajam."},{"fr":"Je me suis réveillé plusieurs fois à cause des secousses.","tgt":"Saya terbangun beberapa kali karena guncangan."},{"fr":"Au lever du soleil, on traversait des rizières en terrasses.","tgt":"Saat matahari terbit, kami melewati sawah-sawah terasering."},{"fr":"On est arrivés épuisés, mais avec seulement une heure de retard.","tgt":"Kami tiba dalam keadaan lelah, tetapi hanya terlambat satu jam."}]},{"title":"Bukittinggi, au pays minangkabau","phrases":[{"fr":"Bukittinggi est une ville fraîche perchée dans les montagnes.","tgt":"Bukittinggi adalah kota sejuk yang terletak di pegunungan."},{"fr":"Depuis notre hôtel, on voit très bien le volcan Marapi.","tgt":"Dari hotel kami, Gunung Marapi terlihat jelas."},{"fr":"Le canyon de Sianok est spectaculaire au petit matin.","tgt":"Ngarai Sianok sangat menakjubkan pada pagi hari."},{"fr":"Les Minangkabau sont réputés pour leur sens du commerce.","tgt":"Orang Minangkabau terkenal pandai berdagang."},{"fr":"Chez eux, la maison et les terres se transmettent par les femmes.","tgt":"Di sini, rumah dan tanah diwariskan melalui garis perempuan."},{"fr":"Leurs maisons ont des toits pointus en forme de cornes de buffle.","tgt":"Rumah mereka beratap runcing seperti tanduk kerbau."},{"fr":"Nous avons visité un ancien palais royal entièrement en bois.","tgt":"Kami mengunjungi istana kerajaan lama yang seluruhnya terbuat dari kayu."},{"fr":"La grande horloge du centre-ville est le symbole de Bukittinggi.","tgt":"Jam Gadang di pusat kota adalah simbol Bukittinggi."},{"fr":"Le marché du samedi attire les gens de tous les villages voisins.","tgt":"Pasar hari Sabtu menarik orang dari semua desa di sekitarnya."},{"fr":"Cette région est très différente du pays batak.","tgt":"Daerah ini sangat berbeda dengan tanah Batak."}]},{"title":"Une randonnée autour du lac Maninjau","phrases":[{"fr":"Aujourd'hui, nous descendons vers le lac Maninjau.","tgt":"Hari ini kami turun ke Danau Maninjau."},{"fr":"La route compte quarante-quatre virages en épingle.","tgt":"Jalan ini memiliki empat puluh empat kelokan."},{"fr":"Chaque virage porte un numéro sur un petit panneau.","tgt":"Setiap kelokan diberi nomor pada papan kecil."},{"fr":"Le lac occupe l'ancien cratère d'un volcan.","tgt":"Danau ini mengisi bekas kawah gunung berapi."},{"fr":"Nous avons marché le long du lac pendant trois heures.","tgt":"Kami berjalan menyusuri tepi danau selama tiga jam."},{"fr":"Le sentier passe au milieu des rizières et des cocotiers.","tgt":"Jalan setapaknya melewati sawah dan pohon kelapa."},{"fr":"Un pêcheur nous a montré comment il élève ses poissons dans le lac.","tgt":"Seorang nelayan menunjukkan cara dia memelihara ikan di danau."},{"fr":"J'ai mal aux jambes, mais la vue m'a fait tout oublier.","tgt":"Kaki saya pegal, tetapi pemandangannya membuat saya lupa segalanya."},{"fr":"On s'est baignés dans l'eau calme du lac.","tgt":"Kami berenang di air danau yang tenang."},{"fr":"Le retour en montée nous a semblé interminable.","tgt":"Perjalanan pulang yang menanjak terasa tidak ada habisnya."}]},{"title":"La cuisine de Padang","phrases":[{"fr":"Dans un restaurant de Padang, on ne commande pas vraiment.","tgt":"Di rumah makan Padang, kita tidak benar-benar memesan makanan."},{"fr":"Le serveur pose directement une dizaine de plats sur la table.","tgt":"Pelayan langsung menaruh sekitar sepuluh piring lauk di meja."},{"fr":"On ne paie que ce qu'on a mangé.","tgt":"Kita hanya membayar apa yang kita makan."},{"fr":"Beaucoup de gens mangent avec la main droite.","tgt":"Banyak orang makan dengan tangan kanan."},{"fr":"Un bol d'eau est posé sur la table pour se rincer les doigts.","tgt":"Semangkuk air disediakan di meja untuk mencuci jari."},{"fr":"La plupart des plats sont très épicés.","tgt":"Sebagian besar hidangannya sangat pedas."},{"fr":"Je vous conseille le poulet pop et le sambal vert.","tgt":"Saya sarankan Anda mencoba ayam pop dan sambal hijau."},{"fr":"Le lait de coco se retrouve dans presque tous les plats.","tgt":"Santan ada di hampir semua masakan."},{"fr":"La cuisine minang est célèbre dans tout l'archipel.","tgt":"Masakan Minang terkenal di seluruh Nusantara."},{"fr":"J'ai mangé bien plus que je ne l'avais prévu.","tgt":"Saya makan jauh lebih banyak daripada yang saya rencanakan."}]},{"title":"Apprendre à préparer le rendang","phrases":[{"fr":"Une dame du quartier nous a invités à cuisiner le rendang avec elle.","tgt":"Seorang ibu di kampung ini mengajak kami memasak rendang bersamanya."},{"fr":"D'abord, on coupe la viande de bœuf en gros morceaux.","tgt":"Pertama, daging sapi dipotong besar-besar."},{"fr":"On mélange le lait de coco avec des épices pilées.","tgt":"Santan dicampur dengan bumbu yang sudah dihaluskan."},{"fr":"Le piment, le gingembre et la citronnelle lui donnent tout son parfum.","tgt":"Cabai, jahe, dan serai memberikan aroma yang khas."},{"fr":"Le rendang doit mijoter au moins quatre heures.","tgt":"Rendang harus dimasak dengan api kecil setidaknya selama empat jam."},{"fr":"Il faut remuer sans arrêt pour que ça n'attache pas.","tgt":"Kita harus terus mengaduk supaya tidak gosong."},{"fr":"Peu à peu, la sauce devient épaisse et sombre.","tgt":"Lama-kelamaan, kuahnya menjadi kental dan berwarna gelap."},{"fr":"Autrefois, ce plat permettait de conserver la viande pendant les longs voyages.","tgt":"Dulu, masakan ini dibuat supaya daging bisa tahan lama selama perjalanan jauh."},{"fr":"Bien préparé, le rendang se garde plusieurs semaines.","tgt":"Kalau dimasak dengan benar, rendang bisa tahan berminggu-minggu."},{"fr":"C'est sans doute le meilleur plat que j'aie goûté ici.","tgt":"Ini mungkin masakan paling enak yang pernah saya coba di sini."}]},{"title":"Le voyage touche à sa fin","phrases":[{"fr":"Plus on avance dans le voyage, plus on se sent à l'aise.","tgt":"Semakin lama kami bepergian, semakin kami merasa nyaman."},{"fr":"Plus on monte, plus il fait frais.","tgt":"Semakin tinggi kita naik, semakin sejuk udaranya."},{"fr":"Mon indonésien devient plus fluide de jour en jour.","tgt":"Bahasa Indonesia saya semakin hari semakin lancar."},{"fr":"Plus le rendang mijote, meilleur il est.","tgt":"Semakin lama rendang dimasak, semakin enak rasanya."},{"fr":"Plus on va vers le sud, plus les routes sont mauvaises.","tgt":"Semakin ke selatan, jalannya semakin rusak."},{"fr":"Plus je découvre Sumatra, plus j'ai envie d'y revenir.","tgt":"Semakin saya mengenal Sumatra, semakin saya ingin kembali."},{"fr":"Mon sac à dos me semble de plus en plus lourd.","tgt":"Ransel saya terasa semakin berat."},{"fr":"Il ne nous reste plus que trois jours avant le retour.","tgt":"Kami hanya punya tiga hari lagi sebelum pulang."},{"fr":"Nous avons déjà parcouru plus de mille kilomètres.","tgt":"Kami sudah menempuh lebih dari seribu kilometer."},{"fr":"Plus le départ approche, plus on a du mal à partir.","tgt":"Semakin dekat hari keberangkatan, semakin berat rasanya untuk pergi."}],"tip":{"title":"« Semakin... semakin... » : de plus en plus","example":"Plus on monte, plus il fait frais. — <b>Semakin</b> tinggi kita naik, <b>semakin</b> sejuk udaranya.","body":"Pour dire « plus..., plus... », l'indonésien répète simplement « semakin » au début de chaque partie de la phrase. « Semakin tinggi kita naik, semakin sejuk udaranya » se dit mot à mot : plus haut, nous montons, plus frais, l'air. Employé seul devant un adjectif, « semakin » signifie « de plus en plus » : « semakin berat », de plus en plus lourd, ou « semakin lancar », de plus en plus fluide. Une jolie formule à retenir : « semakin hari semakin », qui veut dire de jour en jour. À l'oral, vous entendrez aussi très souvent « makin », la version courte et familière, qui a exactement le même sens.","lit":"de plus en plus · haut · nous · monter · de plus en plus · frais · air-le","say":{"Semakin... semakin...":"Semakin... semakin...","semakin":"semakin","Semakin tinggi kita naik, semakin sejuk udaranya":"Semakin tinggi kita naik, semakin sejuk udaranya","semakin berat":"semakin berat","semakin lancar":"semakin lancar","semakin hari semakin":"semakin hari semakin","makin":"makin"}}},{"title":"Un vol retardé à Padang","phrases":[{"fr":"Notre vol pour Jakarta a trois heures de retard.","tgt":"Penerbangan kami ke Jakarta terlambat tiga jam."},{"fr":"La compagnie n'a donné aucune explication.","tgt":"Maskapainya tidak memberikan penjelasan apa pun."},{"fr":"On nous a distribué un repas et une bouteille d'eau.","tgt":"Kami diberi sekotak makanan dan sebotol air."},{"fr":"Excusez-moi, à quelle heure pourra-t-on embarquer maintenant ?","tgt":"Permisi, jam berapa kami bisa naik ke pesawat sekarang?"},{"fr":"J'ai peur de rater ma correspondance à Jakarta.","tgt":"Saya khawatir ketinggalan penerbangan lanjutan di Jakarta."},{"fr":"Pourriez-vous me mettre sur le vol suivant ?","tgt":"Bisakah Anda memindahkan saya ke penerbangan berikutnya?"},{"fr":"Veuillez montrer votre billet au comptoir.","tgt":"Silakan tunjukkan tiket Anda di konter."},{"fr":"Ce genre de retard arrive souvent pendant la saison des pluies.","tgt":"Keterlambatan seperti ini sering terjadi pada musim hujan."},{"fr":"On a profité de l'attente pour trier nos photos.","tgt":"Kami memanfaatkan waktu menunggu untuk memilah foto-foto."},{"fr":"Finalement, l'avion a décollé juste avant minuit.","tgt":"Akhirnya, pesawat lepas landas tepat sebelum tengah malam."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait traverser Sumatra du nord au sud.","tgt":"Modul ini membawa kami menjelajahi Sumatra dari utara ke selatan."},{"fr":"Jungle, lacs, volcans et bus de nuit : on a tout vécu.","tgt":"Hutan, danau, gunung berapi, dan bus malam: semuanya sudah kami alami."},{"fr":"Avec « ke-an », on sait raconter ce qui nous arrive malgré nous.","tgt":"Dengan ke-an, kita bisa menceritakan hal yang terjadi tanpa sengaja."},{"fr":"Les mots « supaya » et « seharusnya » nous viennent maintenant tout seuls.","tgt":"Kata supaya dan seharusnya sekarang keluar dengan sendirinya."},{"fr":"Plus on pratique l'indonésien, plus il devient naturel.","tgt":"Semakin sering kita berlatih bahasa Indonesia, semakin alami rasanya."},{"fr":"On sait faire face à une panne ou à un retard sans paniquer.","tgt":"Kita sudah bisa menghadapi kendaraan mogok atau penerbangan terlambat tanpa panik."},{"fr":"On peut même manger dans un restaurant de Padang comme un habitué.","tgt":"Kita bahkan bisa makan di rumah makan Padang seperti pelanggan tetap."},{"fr":"Bravo, vos progrès sont vraiment impressionnants.","tgt":"Selamat, kemajuan Anda benar-benar mengesankan."},{"fr":"Prenez le temps de réécouter les leçons qui vous ont plu.","tgt":"Luangkan waktu untuk mendengarkan lagi pelajaran yang Anda sukai."},{"fr":"Rendez-vous au prochain module pour des conversations plus personnelles.","tgt":"Sampai jumpa di modul berikutnya untuk percakapan yang lebih pribadi."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Retrouvailles à Yogyakarta","phrases":[{"fr":"Ça fait tellement longtemps, je suis ravi de te revoir !","tgt":"Sudah lama sekali, aku senang sekali bisa bertemu kamu lagi!"},{"fr":"Je t'ai apporté un petit souvenir de France.","tgt":"Aku bawa buah tangan kecil dari Prancis untukmu."},{"fr":"Il ne fallait pas te donner tant de peine pour un cadeau !","tgt":"Aduh, kamu tidak perlu repot-repot membawa buah tangan!"},{"fr":"Surveille bien ton sac, beaucoup de pickpockets traînent au marché.","tgt":"Jaga tasmu baik-baik, di pasar banyak orang panjang tangan."},{"fr":"Ta mère a vraiment le cœur sur la main, elle aide tout le monde.","tgt":"Ibumu memang ringan tangan, dia selalu mau membantu siapa saja."},{"fr":"Mon grand frère est une vraie tête de mule, il n'écoute jamais personne.","tgt":"Kakakku keras kepala, dia tidak pernah mau mendengarkan orang lain."},{"fr":"Depuis sa promotion, il a vraiment pris la grosse tête.","tgt":"Sejak naik jabatan, dia jadi besar kepala."},{"fr":"Rina est devenue le bras droit de la propriétaire de la galerie.","tgt":"Rina sudah menjadi tangan kanan pemilik galeri itu."},{"fr":"Ces petits gâteaux de Yogyakarta sont le cadeau parfait à rapporter.","tgt":"Bakpia dari Yogyakarta ini buah tangan yang paling pas."},{"fr":"On a tant de choses à se raconter depuis la dernière fois !","tgt":"Banyak sekali yang harus kita ceritakan sejak terakhir kali bertemu!"}],"tip":{"title":"Les expressions imagées : « buah tangan », « panjang tangan »","example":"Je t'ai apporté un petit souvenir de France. — Aku bawa <b>buah tangan</b> kecil dari Prancis untukmu.","body":"L'indonésien adore les images tirées du corps. « Buah tangan », mot à mot « le fruit de la main », c'est le petit cadeau qu'on apporte quand on rend visite à quelqu'un. À l'inverse, « panjang tangan », « la main longue », désigne quelqu'un qui vole : c'est un peu nos doigts crochus. Sur le même modèle, « ringan tangan », « la main légère », se dit d'une personne serviable, et « keras kepala », « la tête dure », d'un têtu, exactement comme notre tête de mule. À l'oral, on prononce chaque paire d'un seul souffle, comme un seul mot. Astuce : la main qui donne porte un fruit, la main qui prend s'allonge.","lit":"je · apporter · fruit · main · petit · de · France · pour toi","say":{"buah tangan":"buah tangan","panjang tangan":"panjang tangan","Buah tangan":"Buah tangan","ringan tangan":"ringan tangan","keras kepala":"keras kepala"}}},{"title":"Un débat d'idées au café","phrases":[{"fr":"À mon avis, le progrès technique ne rend pas forcément les gens plus heureux.","tgt":"Menurutku, kemajuan teknologi belum tentu membuat orang lebih bahagia."},{"fr":"Je ne suis pas tout à fait d'accord avec toi sur ce point.","tgt":"Aku kurang setuju denganmu soal yang satu ini."},{"fr":"Tu peux développer un peu ton idée ?","tgt":"Bisa kamu jelaskan sedikit lebih jauh maksudmu?"},{"fr":"C'est un argument intéressant, mais il a aussi ses limites.","tgt":"Argumen itu menarik, tapi ada batasnya juga."},{"fr":"Je pense que la vérité se situe quelque part entre les deux.","tgt":"Kurasa kebenarannya ada di antara keduanya."},{"fr":"On peut ne pas être d'accord et rester de bons amis.","tgt":"Kita bisa berbeda pendapat dan tetap berteman baik."},{"fr":"Cette discussion me fait voir le problème sous un autre angle.","tgt":"Diskusi ini membuatku melihat masalahnya dari sudut pandang lain."},{"fr":"Tu as changé d'avis depuis notre dernière conversation ?","tgt":"Pendapatmu sudah berubah sejak obrolan kita yang terakhir?"},{"fr":"Avoue que mon raisonnement tient la route !","tgt":"Akui saja, alasanku masuk akal, kan?"},{"fr":"Commandons encore un café, ce débat n'est pas terminé.","tgt":"Ayo pesan kopi lagi, perdebatan ini belum selesai."}]},{"title":"Encourager et prendre congé","phrases":[{"fr":"Bon courage pour ton entretien de demain !","tgt":"Semangat untuk wawancaramu besok, ya!"},{"fr":"Fais attention sur la route, il pleut beaucoup ce soir.","tgt":"Hati-hati di jalan, malam ini hujannya deras sekali."},{"fr":"Bon voyage, et donne-moi des nouvelles en arrivant !","tgt":"Selamat jalan, kabari aku kalau sudah sampai, ya!"},{"fr":"Courage, tu touches presque au but !","tgt":"Semangat, sedikit lagi kamu berhasil!"},{"fr":"Attention, le sol du marché est très glissant.","tgt":"Hati-hati, lantai pasarnya licin sekali."},{"fr":"Je dois y aller, au revoir et prenez soin de vous.","tgt":"Aku pamit dulu, selamat tinggal dan jaga diri baik-baik."},{"fr":"Pendant les examens, mes amis m'envoient toujours des messages d'encouragement.","tgt":"Waktu ujian, teman-temanku selalu mengirim pesan semangat."},{"fr":"Prends soin de ta santé et ne travaille pas trop.","tgt":"Jaga kesehatan, jangan kerja terlalu keras."},{"fr":"Bon voyage, et que tu arrives bien en France !","tgt":"Selamat jalan, semoga selamat sampai di Prancis!"},{"fr":"Allez, on garde le moral, il ne reste qu'une semaine de travail !","tgt":"Ayo semangat, kerjanya tinggal seminggu lagi!"}],"tip":{"title":"Les expressions du quotidien : « hati-hati », « selamat jalan », « semangat »","example":"Fais attention sur la route, il pleut beaucoup ce soir. — <b>Hati-hati</b> di jalan, malam ini hujannya deras sekali.","body":"Ces trois formules reviennent sans cesse dans la bouche des Indonésiens. « Hati-hati », « fais attention », s'adresse à quelqu'un qui part, surtout dans « hati-hati di jalan », mot à mot « attention sur la route » : c'est une façon affectueuse de dire au revoir. « Selamat jalan », « bonne route », se dit à celui qui s'en va, tandis que celui qui part répond « selamat tinggal », « bon séjour à toi qui restes ». Enfin « semangat », « l'énergie », s'emploie seul comme un cri d'encouragement, un peu comme notre « courage ! » ou « allez ! ». Dans « semangat », le premier « e » est très bref, comme dans « le ». Astuce : celui qui marche reçoit « jalan », la route, celui qui reste reçoit « tinggal », rester.","lit":"attention · sur · route · nuit · ce · sa pluie · forte · très","say":{"hati-hati":"hati-hati","selamat jalan":"selamat jalan","semangat":"semangat","Hati-hati":"Hati-hati","hati-hati di jalan":"hati-hati di jalan","Selamat jalan":"Selamat jalan","selamat tinggal":"selamat tinggal","jalan":"jalan","tinggal":"tinggal"}}},{"title":"L'art du batik","phrases":[{"fr":"Le batik est bien plus qu'un tissu, c'est un art à part entière.","tgt":"Batik itu bukan sekadar kain, batik adalah sebuah seni."},{"fr":"Chaque motif raconte une histoire et possède sa propre signification.","tgt":"Setiap motif punya cerita dan maknanya sendiri."},{"fr":"Les motifs sont dessinés à la cire chaude avec un petit outil en cuivre.","tgt":"Motifnya digambar dengan lilin panas memakai alat kecil dari tembaga."},{"fr":"Cet outil s'appelle le canting, et il demande une main très sûre.","tgt":"Alat itu disebut canting, dan memakainya butuh tangan yang sangat mantap."},{"fr":"Un batik dessiné à la main peut demander plusieurs semaines de travail.","tgt":"Batik tulis bisa dikerjakan selama beberapa minggu."},{"fr":"Le batik fait au tampon coûte moins cher, mais il n'a pas la même âme.","tgt":"Batik cap lebih murah, tapi jiwanya tidak sama."},{"fr":"Dans cet atelier, ce sont surtout des dames âgées qui travaillent.","tgt":"Di sanggar batik ini, kebanyakan perajinnya ibu-ibu yang sudah sepuh."},{"fr":"Le brun et l'indigo sont les couleurs typiques du batik de Yogyakarta.","tgt":"Warna cokelat dan nila adalah ciri khas batik Yogyakarta."},{"fr":"J'ai essayé de dessiner un motif, mais la cire a coulé partout.","tgt":"Aku mencoba menggambar motif, tapi lilinnya menetes ke mana-mana."},{"fr":"Je vais rapporter ce tissu pour en faire une chemise.","tgt":"Kain ini akan kubawa pulang untuk dijahit menjadi kemeja."}]},{"title":"Premières impressions à Prambanan","phrases":[{"fr":"On dirait qu'il va pleuvoir cet après-midi.","tgt":"Sepertinya sore ini akan hujan."},{"fr":"Le site a l'air encore plus grand que sur les photos.","tgt":"Kelihatannya kompleks candi ini lebih besar daripada di foto."},{"fr":"On dirait que tout le monde vient ici pour le coucher du soleil.","tgt":"Sepertinya semua orang datang ke sini untuk melihat matahari terbenam."},{"fr":"Ces bas-reliefs ont l'air très anciens, mais ils sont bien conservés.","tgt":"Relief ini kelihatannya sangat tua, tapi masih terawat dengan baik."},{"fr":"Ton guide a l'air de bien connaître l'histoire du lieu.","tgt":"Pemandumu kelihatannya paham sekali sejarah tempat ini."},{"fr":"J'ai l'impression que ces tours ont été restaurées récemment.","tgt":"Sepertinya menara-menara itu baru saja dipugar."},{"fr":"Le spectacle de danse de ce soir a l'air complet.","tgt":"Kelihatannya pertunjukan tari malam ini sudah penuh."},{"fr":"Tu as l'air fatigué, on fait une petite pause ?","tgt":"Kamu kelihatannya capek, mau istirahat dulu?"},{"fr":"Prambanan est peut-être le plus bel endroit que j'aie jamais visité.","tgt":"Prambanan mungkin tempat paling indah yang pernah kukunjungi."},{"fr":"Il vaut mieux venir tôt le matin, quand il fait encore frais.","tgt":"Lebih baik datang pagi-pagi, selagi udaranya masih sejuk."}],"tip":{"title":"« Sepertinya » et « kelihatannya » : on dirait que","example":"On dirait qu'il va pleuvoir cet après-midi. — <b>Sepertinya</b> sore ini akan hujan.","body":"Pour donner une impression sans rien affirmer, on place en tête de phrase « sepertinya », qui vient de « seperti », « comme ». C'est notre « on dirait que » ou « j'ai l'impression que ». « Kelihatannya » vient de « lihat », « voir », et veut dire « à ce qu'on voit » : on l'emploie surtout pour ce qui saute aux yeux, comme dans « kamu kelihatannya capek », « tu as l'air fatigué ». Les deux se placent en début de phrase ou juste après le sujet, et le reste ne change pas. Décomposons « sepertinya sore ini akan hujan » : « on dirait, après-midi, ce, futur, pleuvoir ». Astuce : « seperti » pour ce qu'on sent, « lihat » pour ce qu'on voit.","lit":"on dirait que · après-midi · ce · [futur] · pleuvoir","say":{"Sepertinya":"Sepertinya","kelihatannya":"kelihatannya","sepertinya":"sepertinya","seperti":"seperti","Kelihatannya":"Kelihatannya","lihat":"lihat","kamu kelihatannya capek":"kamu kelihatannya capek","sepertinya sore ini akan hujan":"sepertinya sore ini akan hujan"}}},{"title":"Souvenirs de Sumatra","phrases":[{"fr":"Tu te souviens de notre voyage au lac Toba ?","tgt":"Kamu masih ingat perjalanan kita ke Danau Toba?"},{"fr":"On avait pris un bus de nuit qui n'en finissait pas.","tgt":"Kita naik bus malam yang rasanya tidak sampai-sampai."},{"fr":"Le paysage autour du lac m'avait complètement coupé le souffle.","tgt":"Pemandangan di sekitar danau itu benar-benar membuatku terpukau."},{"fr":"Nous avions logé chez une famille très accueillante sur l'île de Samosir.","tgt":"Kita menginap di rumah keluarga yang sangat ramah di Pulau Samosir."},{"fr":"La cuisine de Padang était beaucoup trop épicée pour moi.","tgt":"Masakan Padang waktu itu terlalu pedas buatku."},{"fr":"Je me rappelle encore le goût du rendang dans cette petite gargote.","tgt":"Aku masih ingat rasa rendang di warung kecil itu."},{"fr":"À Bukittinggi, il faisait étonnamment froid le soir.","tgt":"Di Bukittinggi, udaranya ternyata dingin sekali kalau malam."},{"fr":"On avait vu des orangs-outans dans la forêt près de Bukit Lawang.","tgt":"Kita melihat orang utan di hutan dekat Bukit Lawang."},{"fr":"C'était épuisant, mais je referais ce voyage sans hésiter.","tgt":"Memang melelahkan, tapi aku mau mengulang perjalanan itu tanpa ragu."},{"fr":"Ces souvenirs me rendent un peu nostalgique.","tgt":"Kenangan-kenangan itu membuatku agak rindu masa lalu."}]},{"title":"De Lombok à Komodo","phrases":[{"fr":"Après Bali, nous avions pris le bateau pour Lombok.","tgt":"Setelah dari Bali, kita naik kapal ke Lombok."},{"fr":"À l'époque, les plages de Lombok étaient presque désertes.","tgt":"Waktu itu pantai-pantai di Lombok hampir sepi."},{"fr":"Grimper le Rinjani a été l'expérience la plus dure de ma vie.","tgt":"Mendaki Gunung Rinjani adalah pengalaman paling berat dalam hidupku."},{"fr":"Au sommet, le lever du soleil nous a fait oublier la fatigue.","tgt":"Di puncak, matahari terbit membuat kita lupa rasa capek."},{"fr":"Ensuite, nous avons navigué plusieurs jours jusqu'à Komodo.","tgt":"Setelah itu, kita berlayar beberapa hari sampai ke Komodo."},{"fr":"Le guide nous avait demandé de rester derrière lui face aux dragons.","tgt":"Pemandunya meminta kita tetap di belakangnya waktu ada komodo."},{"fr":"J'avais un peu peur, mais je n'avais jamais rien vu d'aussi impressionnant.","tgt":"Aku agak takut, tapi belum pernah melihat sesuatu yang begitu mengesankan."},{"fr":"La plage rose était encore plus belle que ce que j'imaginais.","tgt":"Pantai Merah Muda itu bahkan lebih indah daripada yang kubayangkan."},{"fr":"Le soir, on dormait sur le pont du bateau, sous les étoiles.","tgt":"Malamnya, kita tidur di dek kapal di bawah bintang-bintang."},{"fr":"Ce voyage m'a appris à partir avec très peu de bagages.","tgt":"Perjalanan itu mengajariku bepergian dengan barang yang sangat sedikit."}]},{"title":"Quand le voyage ne se passe pas comme prévu","phrases":[{"fr":"Notre vol a été annulé, nous avons été obligés de dormir à l'aéroport.","tgt":"Penerbangan kami dibatalkan, jadi kami terpaksa tidur di bandara."},{"fr":"Il n'y avait plus de bus, j'ai dû prendre un ojek sous la pluie.","tgt":"Sudah tidak ada bus, aku terpaksa naik ojek di tengah hujan."},{"fr":"Le bateau était en panne, on a été forcés d'attendre jusqu'au lendemain.","tgt":"Kapalnya rusak, kita terpaksa menunggu sampai keesokan harinya."},{"fr":"Je suis tombé malade et j'ai dû renoncer à l'ascension du volcan.","tgt":"Aku jatuh sakit dan terpaksa membatalkan pendakian gunung berapi itu."},{"fr":"L'hôtel était complet, alors on a été obligés de chercher ailleurs.","tgt":"Hotelnya penuh, jadi kita terpaksa mencari penginapan lain."},{"fr":"Je n'avais pas envie de partir, mais j'y étais bien obligé.","tgt":"Sebenarnya aku tidak mau pergi, tapi aku terpaksa."},{"fr":"Le guide a été contraint de changer d'itinéraire à cause de la boue.","tgt":"Pemandunya terpaksa mengganti rute karena jalannya berlumpur."},{"fr":"Nos valises ont été perdues et il a fallu tout racheter à Bandung.","tgt":"Koper kami hilang, dan kami terpaksa membeli semuanya lagi di Bandung."},{"fr":"Finalement, ces imprévus donnent les meilleures histoires.","tgt":"Akhirnya, kejadian tak terduga seperti itu justru jadi cerita paling seru."},{"fr":"Avec le recul, aujourd'hui, on en rit beaucoup.","tgt":"Sekarang kalau diingat-ingat, kita malah menertawakannya."}],"tip":{"title":"« Terpaksa » : être obligé de","example":"Il n'y avait plus de bus, j'ai dû prendre un ojek sous la pluie. — Sudah tidak ada bus, aku <b>terpaksa</b> naik ojek di tengah hujan.","body":"« Terpaksa » se forme sur « paksa », « la force », avec le préfixe « ter », qui marque ce qui nous arrive sans qu'on l'ait voulu. On le place simplement devant le verbe : « aku terpaksa naik ojek », mot à mot « je, forcé, monter, ojek », c'est-à-dire « j'ai dû prendre un ojek ». Pas besoin de « de » comme en français, ni de conjugaison. Il peut aussi rester seul en fin de phrase : « aku terpaksa », « j'y étais bien obligé ». Il exprime une contrainte subie, avec une pointe de regret, alors que « harus », « devoir », reste une obligation neutre. Astuce : entendez « forcé » dans « terpaksa », la force de « paksa » vous pousse malgré vous.","lit":"[accompli] · ne pas · il y a · bus · je · obligé · monter · ojek · à · milieu · pluie","say":{"Terpaksa":"Terpaksa","paksa":"paksa","aku terpaksa naik ojek":"aku terpaksa naik ojek","aku terpaksa":"aku terpaksa","harus":"harus","terpaksa":"terpaksa","ter":"ter"}}},{"title":"Débat : la grande ville ou la campagne","phrases":[{"fr":"Moi, je ne pourrais jamais quitter l'agitation de Jakarta.","tgt":"Kalau aku, aku tidak akan pernah bisa meninggalkan hiruk-pikuk Jakarta."},{"fr":"Pourtant, les embouteillages te volent des heures chaque jour.","tgt":"Tapi kemacetan mencuri berjam-jam waktumu setiap hari."},{"fr":"À la campagne, la vie paraît plus lente et plus paisible.","tgt":"Di desa, hidup terasa lebih lambat dan lebih tenang."},{"fr":"Oui, mais il y a moins d'emplois et moins de services.","tgt":"Iya, tapi lapangan kerja dan fasilitasnya lebih sedikit."},{"fr":"Beaucoup de jeunes quittent leur village pour tenter leur chance en ville.","tgt":"Banyak anak muda meninggalkan kampungnya untuk mengadu nasib di kota."},{"fr":"Avec le travail à distance, on peut vivre loin et travailler quand même.","tgt":"Dengan kerja jarak jauh, kita bisa tinggal jauh dan tetap bekerja."},{"fr":"Je rêve d'une petite maison au milieu des rizières près d'Ubud.","tgt":"Aku bermimpi punya rumah kecil di tengah sawah dekat Ubud."},{"fr":"Tu dis ça maintenant, mais tu t'ennuierais au bout d'un mois.","tgt":"Kamu bilang begitu sekarang, tapi sebulan kemudian kamu pasti bosan."},{"fr":"Chacun doit trouver l'équilibre qui lui convient.","tgt":"Setiap orang harus menemukan keseimbangan yang cocok untuknya."},{"fr":"Bon, on dirait qu'on ne tombera pas d'accord ce soir !","tgt":"Ya sudahlah, sepertinya malam ini kita tidak akan sepakat!"}]},{"title":"Rencontre avec un artisan","phrases":[{"fr":"Ce sculpteur sur bois travaille dans le même atelier depuis quarante ans.","tgt":"Pemahat kayu ini sudah bekerja di sanggar yang sama selama empat puluh tahun."},{"fr":"Il a appris le métier en regardant travailler son grand-père.","tgt":"Dia belajar keahlian ini dengan melihat kakeknya bekerja."},{"fr":"Aujourd'hui, c'est lui qui forme les apprentis du village.","tgt":"Sekarang dia sendiri yang melatih para murid dari desanya."},{"fr":"Selon lui, la patience compte davantage que le talent.","tgt":"Menurutnya, kesabaran lebih penting daripada bakat."},{"fr":"Les jeunes préfèrent souvent des métiers mieux payés.","tgt":"Anak muda sering lebih memilih pekerjaan yang gajinya lebih besar."},{"fr":"Il a peur que ce savoir-faire disparaisse un jour.","tgt":"Dia khawatir keahlian ini suatu hari akan hilang."},{"fr":"Chaque pièce est unique, aucune n'est exactement pareille.","tgt":"Setiap karya itu unik, tidak ada yang sama persis."},{"fr":"Il m'a laissé essayer, et j'ai failli me couper le doigt.","tgt":"Dia membiarkanku mencoba, dan jariku hampir teriris."},{"fr":"Acheter directement aux artisans les aide vraiment à vivre.","tgt":"Membeli langsung dari perajin benar-benar membantu kehidupan mereka."},{"fr":"Je suis reparti avec un petit masque et beaucoup de respect.","tgt":"Aku pulang membawa topeng kecil dan rasa hormat yang besar."}]},{"title":"Les projets d'avenir","phrases":[{"fr":"Comment est-ce que tu t'imagines dans cinq ans ?","tgt":"Lima tahun lagi, kamu membayangkan dirimu sedang apa?"},{"fr":"J'aimerais ouvrir une petite maison d'hôtes à Lombok.","tgt":"Aku ingin membuka penginapan kecil di Lombok."},{"fr":"Mon rêve, ce serait de vivre entre la France et l'Indonésie.","tgt":"Mimpiku adalah tinggal bergantian di Prancis dan Indonesia."},{"fr":"Il faudrait d'abord que j'économise pas mal d'argent.","tgt":"Tapi aku harus menabung cukup banyak uang dulu."},{"fr":"Mes parents trouvent ce projet un peu fou.","tgt":"Orang tuaku menganggap rencana ini agak gila."},{"fr":"Moi, je compte reprendre mes études l'année prochaine.","tgt":"Kalau aku, aku berencana kuliah lagi tahun depan."},{"fr":"Je voudrais me spécialiser dans la protection des récifs coralliens.","tgt":"Aku ingin mendalami bidang perlindungan terumbu karang."},{"fr":"Rien n'est encore décidé, tout peut changer.","tgt":"Belum ada yang pasti, semuanya masih bisa berubah."},{"fr":"L'essentiel, c'est de garder un cap tout en restant souple.","tgt":"Yang penting punya tujuan dan tetap fleksibel."},{"fr":"Promettons-nous d'en reparler dans quelques années.","tgt":"Ayo kita berjanji akan membahas ini lagi beberapa tahun ke depan."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Comme dit le proverbe, petit à petit, l'oiseau fait son nid.","tgt":"Seperti kata peribahasa, sedikit demi sedikit, lama-lama menjadi bukit."},{"fr":"« Après l'effort, le réconfort », répétait souvent ma grand-mère.","tgt":"Nenekku sering bilang, “Bersakit-sakit dahulu, bersenang-senang kemudian.”"},{"fr":"Il n'y a pas de fumée sans feu, cette rumeur est peut-être vraie.","tgt":"Tak ada asap tanpa api, jadi gosip itu mungkin ada benarnya."},{"fr":"Ceux qui font le plus de bruit sont souvent ceux qui en savent le moins.","tgt":"Air beriak tanda tak dalam, orang yang banyak bicara biasanya sedikit ilmunya."},{"fr":"Toi et ton frère, vous vous ressemblez comme deux gouttes d'eau.","tgt":"Kamu dan kakakmu seperti pinang dibelah dua."},{"fr":"Les proverbes indonésiens parlent souvent de la nature et des rivières.","tgt":"Peribahasa Indonesia sering berbicara tentang alam dan sungai."},{"fr":"Là où l'on vit, il faut respecter les coutumes locales, dit le proverbe.","tgt":"Di mana bumi dipijak, di situ langit dijunjung: kita harus menghormati adat setempat."},{"fr":"Il change d'avis sans arrêt, comme l'eau sur une feuille de taro.","tgt":"Pendiriannya seperti air di daun talas, selalu berubah-ubah."},{"fr":"Citer un proverbe au bon moment impressionne toujours les Indonésiens.","tgt":"Mengutip peribahasa pada saat yang tepat selalu membuat orang Indonesia kagum."},{"fr":"Qui a honte de demander se perd en chemin : n'hésite pas à poser des questions !","tgt":"Malu bertanya sesat di jalan, jadi jangan ragu untuk bertanya!"}],"tip":{"title":"Les proverbes indonésiens : les « peribahasa »","example":"Qui a honte de demander se perd en chemin : n'hésite pas à poser des questions ! — <b>Malu bertanya sesat di jalan</b>, jadi jangan ragu untuk bertanya!","body":"Les Indonésiens adorent glisser un « peribahasa », un proverbe, dans la conversation, et en placer un au bon moment fait toujours sourire. Beaucoup sont bâtis en deux moitiés qui se répondent, avec un rythme presque musical : « malu bertanya, sesat di jalan », mot à mot « honte de demander, égaré sur la route ». Dites-les avec une petite pause au milieu, comme un vers de poésie. Certains ressemblent aux nôtres, comme « tak ada asap tanpa api », « pas de fumée sans feu ». D'autres sont des images bien locales, comme « seperti pinang dibelah dua », « comme une noix d'arec coupée en deux », pour deux personnes qui se ressemblent. Astuce : apprenez-en un seul par cœur et ressortez-le dès que possible, l'effet est garanti.","lit":"honte · demander · égaré · sur · route · donc · ne pas · hésiter · pour · demander","say":{"peribahasa":"peribahasa","malu bertanya, sesat di jalan":"malu bertanya, sesat di jalan","tak ada asap tanpa api":"tak ada asap tanpa api","seperti pinang dibelah dua":"seperti pinang dibelah dua"}}},{"title":"Une soirée sur Malioboro","phrases":[{"fr":"Le soir, la rue Malioboro s'anime complètement.","tgt":"Kalau malam, Jalan Malioboro jadi ramai sekali."},{"fr":"On s'est assis sur une natte pour manger au bord de la rue.","tgt":"Kita makan lesehan di warung pinggir jalan."},{"fr":"Le gudeg est un plat sucré à base de jacquier vert.","tgt":"Gudeg adalah masakan manis dari nangka muda."},{"fr":"Des musiciens de rue jouaient de vieilles chansons à la guitare.","tgt":"Para pengamen memainkan lagu-lagu lama dengan gitar."},{"fr":"Le café servi avec un morceau de charbon brûlant a un goût étonnant.","tgt":"Kopi yang dicampur arang panas itu rasanya mengejutkan."},{"fr":"Ici, on peut discuter pendant des heures sans que personne nous presse.","tgt":"Di sini kita bisa mengobrol berjam-jam tanpa ada yang menyuruh kita pergi."},{"fr":"Le vendeur a insisté pour qu'on goûte ses beignets.","tgt":"Penjualnya memaksa kita mencicipi gorengannya."},{"fr":"J'ai négocié le prix d'un sac en batik avec le sourire.","tgt":"Aku menawar harga tas batik sambil tersenyum."},{"fr":"Cette ambiance chaleureuse va beaucoup me manquer.","tgt":"Aku pasti akan sangat merindukan suasana hangat ini."},{"fr":"On rentre en becak ou à pied ?","tgt":"Kita pulang naik becak atau jalan kaki?"}]},{"title":"Débat : le tourisme et ses effets","phrases":[{"fr":"Le tourisme fait vivre des milliers de familles à Bali.","tgt":"Pariwisata menghidupi ribuan keluarga di Bali."},{"fr":"Mais certaines plages sont devenues méconnaissables.","tgt":"Tapi beberapa pantai sudah berubah sampai tidak bisa dikenali lagi."},{"fr":"Les déchets en plastique sont un vrai problème sur les îles.","tgt":"Sampah plastik menjadi masalah serius di pulau-pulau."},{"fr":"Je pense qu'il faudrait limiter le nombre de visiteurs sur certains sites.","tgt":"Menurutku, jumlah pengunjung di beberapa tempat perlu dibatasi."},{"fr":"Ce serait injuste pour ceux qui économisent toute leur vie pour voyager.","tgt":"Itu tidak adil bagi orang yang menabung seumur hidup untuk berwisata."},{"fr":"Un tourisme plus lent et plus respectueux, c'est possible.","tgt":"Wisata yang lebih santai dan lebih menghargai lingkungan itu mungkin."},{"fr":"Dormir chez l'habitant permet de mieux comprendre la vie locale.","tgt":"Menginap di rumah penduduk membantu kita memahami kehidupan setempat."},{"fr":"Les touristes devraient apprendre quelques mots de la langue locale.","tgt":"Wisatawan seharusnya belajar beberapa kata dalam bahasa setempat."},{"fr":"Il faut l'admettre, nous aussi, nous faisons partie du problème.","tgt":"Harus diakui, kita juga bagian dari masalahnya."},{"fr":"Ce débat est loin d'être tranché.","tgt":"Perdebatan ini masih jauh dari selesai."}]},{"title":"Oser changer de vie","phrases":[{"fr":"J'ai démissionné l'an dernier pour me consacrer à la photo.","tgt":"Tahun lalu aku mengundurkan diri untuk menekuni fotografi."},{"fr":"Tout le monde m'a dit que c'était beaucoup trop risqué.","tgt":"Semua orang bilang itu terlalu berisiko."},{"fr":"Les premiers mois ont été vraiment durs financièrement.","tgt":"Bulan-bulan pertama sangat berat dari segi keuangan."},{"fr":"Pourtant, je ne me suis jamais senti aussi vivant.","tgt":"Tapi aku belum pernah merasa sehidup ini."},{"fr":"Il faut parfois oser sauter dans le vide pour avancer.","tgt":"Kadang kita harus berani melompat untuk maju."},{"fr":"Ma plus grande peur était de décevoir mes proches.","tgt":"Ketakutan terbesarku adalah mengecewakan orang-orang terdekat."},{"fr":"Finalement, aujourd'hui, ils sont fiers de moi.","tgt":"Ternyata sekarang mereka bangga padaku."},{"fr":"Je ne dis pas que c'est la bonne voie pour tout le monde.","tgt":"Aku tidak bilang ini jalan yang tepat untuk semua orang."},{"fr":"Mais si l'envie est forte, ça vaut la peine d'essayer.","tgt":"Tapi kalau keinginannya kuat, layak dicoba."},{"fr":"Et toi, qu'est-ce qui t'empêche de changer ?","tgt":"Kalau kamu, apa yang membuatmu ragu untuk berubah?"}]},{"title":"L'amitié malgré la distance","phrases":[{"fr":"On s'est rencontrés à Bandung, il y a presque dix ans.","tgt":"Kita berkenalan di Bandung hampir sepuluh tahun yang lalu."},{"fr":"Depuis, des milliers de kilomètres nous séparent.","tgt":"Sejak itu, ribuan kilometer memisahkan kita."},{"fr":"Pourtant, j'ai l'impression qu'on s'est quittés hier.","tgt":"Tapi rasanya seperti baru kemarin kita berpisah."},{"fr":"Nos appels vidéo du dimanche sont devenus un rituel.","tgt":"Panggilan video kita setiap hari Minggu sudah menjadi kebiasaan."},{"fr":"Le décalage horaire nous oblige à nous parler très tôt ou très tard.","tgt":"Karena perbedaan waktu, kita harus mengobrol pagi-pagi sekali atau larut malam."},{"fr":"Tu as toujours su trouver les mots quand ça n'allait pas.","tgt":"Kamu selalu tahu harus bilang apa waktu aku sedang susah."},{"fr":"Une vraie amitié n'a pas besoin de se voir tous les jours.","tgt":"Persahabatan sejati tidak perlu bertemu setiap hari."},{"fr":"Chaque visite à Yogyakarta est une petite fête pour moi.","tgt":"Setiap kunjungan ke Yogyakarta adalah pesta kecil bagiku."},{"fr":"Merci d'être resté le même malgré les années.","tgt":"Terima kasih sudah tetap sama walaupun bertahun-tahun berlalu."},{"fr":"La prochaine fois, c'est toi qui viens me voir en France !","tgt":"Lain kali, giliranmu yang datang mengunjungiku di Prancis!"}]},{"title":"La musique et la danse javanaises","phrases":[{"fr":"Le son du gamelan me donne toujours des frissons.","tgt":"Suara gamelan selalu membuatku merinding."},{"fr":"Les instruments sont surtout en bronze et se jouent tous ensemble.","tgt":"Alat musiknya kebanyakan dari perunggu dan dimainkan bersama-sama."},{"fr":"Il n'y a pas de soliste, c'est l'harmonie du groupe qui compte.","tgt":"Tidak ada pemain tunggal, yang penting keselarasan kelompok."},{"fr":"Les danseuses bougent leurs mains avec une lenteur incroyable.","tgt":"Para penari menggerakkan tangan mereka dengan sangat pelan."},{"fr":"Chaque geste des doigts demande des années d'apprentissage.","tgt":"Setiap gerakan jari dipelajari selama bertahun-tahun."},{"fr":"Hier soir, nous avons vu un spectacle de danse en plein air devant Prambanan.","tgt":"Tadi malam kami menonton pertunjukan tari di udara terbuka di depan Candi Prambanan."},{"fr":"Toute l'histoire était racontée sans un seul mot.","tgt":"Seluruh ceritanya disampaikan tanpa satu kata pun."},{"fr":"Un spectacle de marionnettes en cuir peut durer toute la nuit.","tgt":"Pertunjukan wayang kulit bisa berlangsung semalam suntuk."},{"fr":"J'aimerais prendre quelques cours de danse avant de rentrer.","tgt":"Aku ingin ikut beberapa kelas tari sebelum pulang."},{"fr":"Avec la musique, pas besoin de parler la même langue pour se comprendre.","tgt":"Lewat musik, kita tidak perlu berbicara bahasa yang sama untuk saling memahami."}]},{"title":"Les adieux à Yogyakarta","phrases":[{"fr":"Je n'arrive pas à croire que c'est déjà notre dernière soirée.","tgt":"Aku tidak percaya ini sudah malam terakhir kita."},{"fr":"Ces deux semaines sont passées beaucoup trop vite.","tgt":"Dua minggu ini berlalu terlalu cepat."},{"fr":"Merci de m'avoir si bien accueilli chez toi.","tgt":"Terima kasih sudah menerimaku dengan begitu baik di rumahmu."},{"fr":"Ta famille m'a traité comme l'un des siens.","tgt":"Keluargamu memperlakukanku seperti anggota keluarga sendiri."},{"fr":"Je repars avec une valise pleine de souvenirs, et pas seulement d'objets.","tgt":"Aku pulang dengan koper penuh kenangan, bukan hanya barang."},{"fr":"Ne pleure pas, sinon je vais pleurer aussi !","tgt":"Jangan menangis, nanti aku ikut menangis!"},{"fr":"Je t'envoie un message dès que je suis arrivé, promis.","tgt":"Aku akan mengabarimu begitu sampai, janji."},{"fr":"Prends bien soin de toi et garde ce sourire.","tgt":"Jaga dirimu baik-baik dan tetaplah tersenyum."},{"fr":"Ce n'est pas un adieu, c'est juste un au revoir.","tgt":"Ini bukan perpisahan selamanya, hanya sampai jumpa."},{"fr":"À l'année prochaine, j'espère, à Yogyakarta ou à Paris !","tgt":"Semoga sampai jumpa tahun depan, di Yogyakarta atau di Paris!"}]},{"title":"Regard en arrière sur mon parcours en indonésien","phrases":[{"fr":"Au début, je ne savais même pas dire bonjour en indonésien.","tgt":"Dulu, aku bahkan tidak bisa mengucapkan “selamat pagi” dalam bahasa Indonesia."},{"fr":"Les premières phrases me paraissaient étranges, sans aucune conjugaison.","tgt":"Kalimat-kalimat pertama terasa aneh karena tidak ada konjugasi."},{"fr":"Puis j'ai découvert les préfixes, et tout a commencé à s'éclairer.","tgt":"Lalu aku mengenal awalan, dan semuanya mulai jelas."},{"fr":"Aujourd'hui, je peux débattre avec mes amis pendant des heures.","tgt":"Sekarang aku bisa berdebat dengan teman-temanku berjam-jam."},{"fr":"Je fais encore des erreurs, mais elles ne me font plus peur.","tgt":"Aku masih membuat kesalahan, tapi aku tidak takut lagi."},{"fr":"Les gens sourient toujours quand j'essaie de parler leur langue.","tgt":"Orang-orang selalu tersenyum waktu aku mencoba berbicara dalam bahasa mereka."},{"fr":"Chaque trajet passé à écouter ces leçons m'a rapproché du but.","tgt":"Setiap perjalanan sambil mendengarkan pelajaran ini membuatku semakin dekat dengan tujuan."},{"fr":"Parler indonésien m'a ouvert des portes que je n'imaginais pas.","tgt":"Berbicara bahasa Indonesia membuka pintu yang tidak pernah kubayangkan."},{"fr":"Quand je repense à mes débuts, je mesure tout le chemin accompli.","tgt":"Kalau mengingat awal belajarku, aku sadar betapa jauhnya aku sudah melangkah."},{"fr":"Et je sais que l'aventure ne fait que commencer.","tgt":"Dan aku tahu petualangan ini baru saja dimulai."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a emmenés de Yogyakarta à Prambanan.","tgt":"Modul terakhir ini membawa kita dari Yogyakarta ke Prambanan."},{"fr":"Nous avons débattu, raconté nos voyages et parlé de l'avenir.","tgt":"Kita sudah berdebat, bercerita tentang perjalanan, dan membicarakan masa depan."},{"fr":"« Buah tangan », « terpaksa », « sepertinya » : ces mots font désormais partie de notre vocabulaire.","tgt":"“Buah tangan”, “terpaksa”, “sepertinya”: kata-kata ini sekarang sudah menjadi bagian dari kosakata kita."},{"fr":"Nous savons même glisser un proverbe au bon moment.","tgt":"Kita bahkan bisa menyelipkan peribahasa pada saat yang tepat."},{"fr":"Ces trois niveaux nous ont menés des premiers mots jusqu'aux vraies conversations.","tgt":"Tiga tingkat ini membawa kita dari kata-kata pertama sampai percakapan sungguhan."},{"fr":"L'indonésien n'est plus une langue étrangère, c'est une langue amie.","tgt":"Bahasa Indonesia bukan lagi bahasa asing, tapi bahasa sahabat."},{"fr":"Continuez à parler, à écouter et à oser vous tromper.","tgt":"Teruslah berbicara, mendengarkan, dan berani salah."},{"fr":"La prochaine étape, c'est de vivre la langue sur place, en Indonésie.","tgt":"Langkah berikutnya adalah merasakan bahasa ini langsung di Indonesia."},{"fr":"Bravo pour votre persévérance tout au long de ce parcours.","tgt":"Selamat atas ketekunan Anda sepanjang perjalanan ini."},{"fr":"Bon courage pour la suite, et à très bientôt en Indonésie !","tgt":"Semangat terus, dan sampai jumpa lagi di Indonesia!"}]}]}]}];
